    ret = True
    pb, r = getfloat(mainwin.gui.endofLpfPassBandEdit.text())
    ret = r and ret
    sb, r = getfloat(mainwin.gui.startofLpfStopBandEdit.text())
    ret = r and ret
    atten, r = getfloat(mainwin.gui.lpfStopBandAttenEdit.text())
    ret = r and ret

    if(ret):
        tb = sb - pb

        try:
