thread_unbind(gr_thread_t thread)
{
#if defined(__GR_TARGET_DEFAULT__)
    cpu_set_t set;
    size_t len = sizeof(cpu_set_t);

    CPU_ZERO(&set);
    long ncpus = sysconf(_SC_NPROCESSORS_ONLN);
    for (long n = 0; n < ncpus; n++) {
        CPU_SET(n, &set);
    }

    int ret = pthread_setaffinity_np(thread, len, &set);
    if (ret != 0) {
        auto msg =
            fmt::format("{}: pthread_setaffinity_np failed with error {}", __func__, ret);
        thread_logger().error(msg);
        throw std::runtime_error(msg);
    }
#elif defined(__GR_TARGET_WIN__)
    DWORD_PTR dword_mask = sizeof(DWORD_PTR) - 1;
    DWORD_PTR ret = SetThreadAffinityMask(thread, dword_mask);
    if (ret == 0) {
        auto msg = fmt::format("thread_unbind failed with error: {}", GetLastError());
        thread_logger().error(msg);
        throw std::runtime_error(msg);
    }
#else
    thread_logger().error(
        "function {}{} not implemented on this platform", __func__, "(gr_thread_t)");
#endif
}

const_sink_c_impl::handle_pdus(pmt::pmt_t msg)
{
    size_t len = 0;
    pmt::pmt_t dict, samples;

    // Test to make sure this is either a PDU or a uniform vector of
    // samples. Get the samples PMT and the dictionary if it's a PDU.
    // If not, we throw an error and exit.
    if (pmt::is_pair(msg)) {
        dict = pmt::car(msg);
        samples = pmt::cdr(msg);
    } else if (pmt::is_uniform_vector(msg)) {
        samples = msg;
    } else {
        throw std::runtime_error("const_sink_c: message must be either "
                                 "a PDU or a uniform vector of samples.");
    }

    len = pmt::length(samples);

    const gr_complex* in;
    if (pmt::is_c32vector(samples)) {
        in = (const gr_complex*)pmt::c32vector_elements(samples, len);
    } else {
        throw std::runtime_error("const_sink_c: unknown data type "
                                 "of samples; must be complex.");
    }

    set_nsamps(len);

    // Plot if we're past the last update time
    if (gr::high_res_timer_now() - d_last_time > d_update_time) {
        d_last_time = gr::high_res_timer_now();

        // Copy data into the buffers.
        volk_32fc_deinterleave_64f_x2(d_residbufs_real[d_nconnections].data(),
                                      d_residbufs_imag[d_nconnections].data(),
                                      in,
                                      len);

        d_qApplication->postEvent(
            d_main_gui, new ConstUpdateEvent(d_residbufs_real, d_residbufs_imag, len));
    }
}

