freq_sample(int N,
                                       const std::vector<double>& A,
                                       std::vector<double>& h,
                                       symmetry_type symm)
{
    double M = (N - 1.0) / 2.0;
    if (symm == symmetry_type::POSITIVE) {
        if (N % 2) {
            for (int n = 0; n < N; n++) {
                double val = A[0];
                double x = PI2 * (n - M) / N;
                for (int k = 1; k <= M; k++)
                    val += 2.0 * A[k] * cos(x * k);
                h[n] = val / N;
            }
        } else {
            for (int n = 0; n < N; n++) {
                double val = A[0];
                double x = PI2 * (n - M) / N;
                for (int k = 1; k <= (N / 2 - 1); k++)
                    val += 2.0 * A[k] * cos(x * k);
                h[n] = val / N;
            }
        }
    } else {
        if (N % 2) {
            for (int n = 0; n < N; n++) {
                double val = 0;
                double x = PI2 * (n - M) / N;
                for (int k = 1; k <= M; k++)
                    val += 2.0 * A[k] * sin(x * k);
                h[n] = val / N;
            }
        } else {
            for (int n = 0; n < N; n++) {
                double val = A[N / 2] * sin(PI * (n - M));
                double x = PI2 * (n - M) / N;
                for (int k = 1; k <= (N / 2 - 1); k++)
                    val += 2.0 * A[k] * sin(x * k);
                h[n] = val / N;
            }
        }
    }
}

