dvbs2_modulator_bc_impl::general_work(int noutput_items,
                                          gr_vector_int& ninput_items,
                                          gr_vector_const_void_star& input_items,
                                          gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];
    int index;
    gr_complex zero;

    zero = gr_complex(0.0, 0.0);

    if (signal_interpolation == INTERPOLATION_OFF) {
        switch (signal_constellation) {
        case MOD_BPSK:
        case MOD_BPSK_SF2:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_bpsk[i & 1][index & 0x1];
            }
            break;
        case MOD_QPSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_qpsk[index & 0x3];
            }
            break;
        case MOD_8PSK:
        case MOD_8VSB:
        case MOD_8APSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_8psk[index & 0x7];
            }
            break;
        case MOD_16APSK:
        case MOD_8_8APSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_16apsk[index & 0xf];
            }
            break;
        case MOD_32APSK:
        case MOD_4_12_16APSK:
        case MOD_4_8_4_16APSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_32apsk[index & 0x1f];
            }
            break;
        case MOD_64APSK:
        case MOD_64QAM:
        case MOD_8_16_20_20APSK:
        case MOD_4_12_20_28APSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_64apsk[index & 0x3f];
            }
            break;
        case MOD_128APSK:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_128apsk[index & 0x7f];
            }
            break;
        case MOD_256APSK:
        case MOD_256QAM:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_256apsk[index & 0xff];
            }
            break;
        default:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_qpsk[index & 0x3];
            }
            break;
        }
    } else {
        switch (signal_constellation) {
        case MOD_BPSK:
        case MOD_BPSK_SF2:
            for (int i = 0; i < noutput_items; i++) {
                index = *in++;
                *out++ = m_bpsk[i & 1][index & 0x1];
                *out++ = zero;
            }
            break;
        case MOD_QPSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_qpsk[index & 0x3];
                *out++ = zero;
            }
            break;
        case MOD_8PSK:
        case MOD_8APSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_8psk[index & 0x7];
                *out++ = zero;
            }
            break;
        case MOD_16APSK:
        case MOD_8_8APSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_16apsk[index & 0xf];
                *out++ = zero;
            }
            break;
        case MOD_32APSK:
        case MOD_4_12_16APSK:
        case MOD_4_8_4_16APSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_32apsk[index & 0x1f];
                *out++ = zero;
            }
            break;
        case MOD_64APSK:
        case MOD_64QAM:
        case MOD_8_16_20_20APSK:
        case MOD_4_12_20_28APSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_64apsk[index & 0x3f];
                *out++ = zero;
            }
            break;
        case MOD_128APSK:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_128apsk[index & 0x7f];
                *out++ = zero;
            }
            break;
        case MOD_256APSK:
        case MOD_256QAM:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_256apsk[index & 0xff];
                *out++ = zero;
            }
            break;
        default:
            for (int i = 0; i < noutput_items / 2; i++) {
                index = *in++;
                *out++ = m_qpsk[index & 0x3];
                *out++ = zero;
            }
            break;
        }
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    if (signal_interpolation == INTERPOLATION_OFF) {
        consume_each(noutput_items);
    } else {
        consume_each(noutput_items / 2);
    }

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

