thread_priority(gr_thread_t thread)
{
#if defined(__GR_TARGET_DEFAULT__) || defined(__GR_TARGET_BSD__)
    sched_param param;
    int priority;
    int policy;
    int ret;
    ret = pthread_getschedparam(thread, &policy, &param);
