        gr_complex* dst = d_fft->get_inbuf();
        for (int i = 0; i < size; i++) // apply window
            dst[i] = data_in[i] * d_window[i];
    } else {
        gr_complex* dst = d_fft->get_inbuf();
        for (int i = 0; i < size; i++) // float to complex conversion
