    auto path = pathname(key);
    gr::thread::scoped_lock guard(s_vm_mutex);
    std::ifstream in_file(path, std::ios::in | std::ios::binary);
    if (!in_file.good()) {
        log_ioerror("get", path, in_file);
        return {};
