d_chunk_size(0)
{
    if ((d_fd = open(d_device_name.c_str(), O_WRONLY)) < 0) {
        d_logger->error("opening device {:s}: {:s}", d_device_name, strerror(errno));
        throw std::runtime_error("audio_oss_sink");
    }

    double CHUNK_TIME =
        std::max(0.001, prefs::singleton()->get_double("audio_oss", "latency", 0.005));

    d_chunk_size = (int)(d_sampling_rate * CHUNK_TIME);
    set_output_multiple(d_chunk_size);

    d_buffer = new short[d_chunk_size * 2];

    int format = AFMT_S16_NE;
    int orig_format = format;
    if (ioctl(d_fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        d_logger->error("{:s} ioctl failed: {:s}", d_device_name, strerror(errno));
        throw std::runtime_error("audio_oss_sink");
    }

    if (format != orig_format) {
        d_logger->error(
            "{:s} unable to support format {:d}. card requested {:d} instead.",
            d_device_name,
            orig_format,
            format);
    }

    // set to stereo no matter what.  Some hardware only does stereo
    int channels = 2;
    if (ioctl(d_fd, SNDCTL_DSP_CHANNELS, &channels) < 0 || channels != 2) {
        d_logger->error("could not set STEREO mode: {:s}", strerror(errno));
        throw std::runtime_error("audio_oss_sink");
    }

    // set sampling freq
    int sf = sampling_rate;
    if (ioctl(d_fd, SNDCTL_DSP_SPEED, &sf) < 0) {
        d_logger->error("{:s}: invalid sampling_rate {:d}", d_device_name, sampling_rate);
        sampling_rate = 8000;
        if (ioctl(d_fd, SNDCTL_DSP_SPEED, &sf) < 0) {
            d_logger->error("failed to set sampling_rate to 8000");
            throw std::runtime_error("audio_oss_sink");
        }
    }
}

probe_avg_mag_sqrd_c_impl::work(int noutput_items,
                                    gr_vector_const_void_star& input_items,
                                    gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];

    for (int i = 0; i < noutput_items; i++) {
        double mag_sqrd = in[i].real() * in[i].real() + in[i].imag() * in[i].imag();
        d_iir.filter(mag_sqrd); // computed for side effect: prev_output()
    }

    d_unmuted = d_iir.prev_output() >= d_threshold;
    d_level = d_iir.prev_output();
    return noutput_items;
}

