context:
atsc_randomizer_impl::work(int noutput_items,
                               gr_vector_const_void_star& input_items,
                               gr_vector_void_star& output_items)
{
    const atsc_mpeg_packet* in = (const atsc_mpeg_packet*)input_items[0];
    atsc_mpeg_packet_no_sync* out = (atsc_mpeg_packet_no_sync*)output_items[0];

    for (int i = 0; i < noutput_items; i++) {
        // sanity check incoming data.
        assert((in[i].data[0] == MPEG_SYNC_BYTE));
        assert((in[i].data[1] & MPEG_TRANSPORT_ERROR_BIT) == 0);

        // initialize plinfo for downstream
        //
        // We do this here because the randomizer is effectively
        // the head of the tx processing chain
        //
        out[i].pli.set_regular_seg(d_field2, d_segno);
        d_segno++;

        if (d_segno == 312) {
            d_segno = 0;
            d_field2 = !d_field2;
        }

        if (out[i].pli.first_regular_seg_p()) {
            d_rand.reset();
        }

        d_rand.randomize(out[i], in[i]);
    }

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

window::kaiser(int ntaps, double beta)
{
    if (beta < 0)
        throw std::out_of_range("window::kaiser: beta must be >= 0");

    std::vector<float> taps(ntaps);

    double IBeta = 1.0 / Izero(beta);
    double inm1 = 1.0 / ((double)(ntaps - 1));
    double temp;

    /* extracting first and last element out of the loop, since
       sqrt(1.0-temp*temp) might trigger unexpected floating point behaviour
       if |temp| = 1.0+epsilon, which can happen for i==0 and
       1/i==1/(ntaps-1)==inm1 ; compare
       https://github.com/gnuradio/gnuradio/issues/1348 .
       In any case, the 0. Bessel function of first kind is 1 at point 0.
     */
    taps[0] = IBeta;
    for (int i = 1; i < ntaps - 1; i++) {
        temp = 2 * i * inm1 - 1;
        taps[i] = Izero(beta * sqrt(1.0 - temp * temp)) * IBeta;
    }
    taps[ntaps - 1] = IBeta;
    return taps;
}

