file_descriptor_sink_impl::work(int noutput_items,
                                    gr_vector_const_void_star& input_items,
                                    gr_vector_void_star& output_items)
{
    const char* inbuf = static_cast<const char*>(input_items[0]);
    unsigned long byte_size = noutput_items * d_itemsize;

    while (byte_size > 0) {
        auto r = write(d_fd, inbuf, byte_size);
        if (r == -1) {
            if (errno == EINTR)
                continue;
            else {
                d_logger->error("{:s}", strerror(errno));
                return -1; // indicate we're done
            }
        } else {
            byte_size -= r;
            inbuf += r;
        }
    }

    return noutput_items;
}

pn_correlator_cc_impl::work(int noutput_items,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];
    gr_complex sum;

    for (int i = 0; i < noutput_items; i++) {
        sum = 0.0;

        for (int j = 0; j < d_len; j++) {
            if (j != 0) // retard PN generator one sample per period
                d_pn = 2.0 * d_reference.next_bit() - 1.0; // no conditionals
            sum += *in++ * d_pn;
        }

        *out++ = sum * gr_complex(1.0 / d_len, 0.0);
    }

    return noutput_items;
}

