tagged_stream_align_impl::general_work(int noutput_items,
                                           gr_vector_int& ninput_items,
                                           gr_vector_const_void_star& input_items,
                                           gr_vector_void_star& output_items)
{
    std::vector<tag_t> tags;
    if (d_have_sync) {
        int ncp = std::min(noutput_items, ninput_items[0]);
        get_tags_in_range(tags, 0, nitems_read(0), nitems_read(0) + noutput_items);
        for (size_t i = 0; i < tags.size(); i++) {
            gr::tag_t t = tags[i];
            int offset = (nitems_read(0) - nitems_written(0));
            t.offset -= offset;
            add_item_tag(0, t);
        }
        memcpy(output_items[0], input_items[0], ncp * d_itemsize);
        consume_each(ncp);
        return ncp;
    } else {
        get_tags_in_range(
            tags, 0, nitems_read(0), nitems_read(0) + ninput_items[0], d_lengthtag);
        if (!tags.empty()) {
            d_have_sync = true;
            consume_each(tags[0].offset - nitems_read(0));
        } else {
            consume_each(ninput_items[0]);
        }
        return 0;
    }
}

siso_f_impl::forecast(int noutput_items, gr_vector_int& ninput_items_required)
{
    int multiple;
    if (d_POSTI && d_POSTO)
        multiple = d_FSM.I() + d_FSM.O();
    else if (d_POSTI)
        multiple = d_FSM.I();
    else if (d_POSTO)
        multiple = d_FSM.O();
    else
        throw std::runtime_error("Not both POSTI and POSTO can be false.");

    // printf("forecast: Multiple = %d\n",multiple);
    int input_required1 = d_FSM.I() * (noutput_items / multiple);
    int input_required2 = d_FSM.O() * (noutput_items / multiple);
    // printf("forecast: Output requirements:  %d\n",noutput_items);
    // printf("forecast: Input requirements:  %d   %d\n",input_required1,input_required2);
    unsigned ninputs = ninput_items_required.size();
    for (unsigned int i = 0; i < ninputs / 2; i++) {
        ninput_items_required[2 * i] = input_required1;
        ninput_items_required[2 * i + 1] = input_required2;
    }
}

