        for (j = 0; j < 128; j++) {
            if ((i == 0) || (j == 0)) {
                gf_mul_table[i][j] = 0;
            } else {
                gf_mul_table[i][j] = gf_exp[gf_log[i] + gf_log[j]];
            }
        }
    }
}

