freq_sink_f_impl::fftresize()
{
    gr::thread::scoped_lock lock(d_setlock);

    int newfftsize = d_main_gui->getFFTSize();
    d_fftavg = d_main_gui->getFFTAverage();

    if (newfftsize != d_fftsize) {
        // Resize residbuf and replace data
        // +1 to handle PDU buffers
        for (int i = 0; i < d_nconnections + 1; i++) {
            d_residbufs[i].clear();
            d_residbufs[i].resize(newfftsize);
            d_magbufs[i].clear();
            d_magbufs[i].resize(newfftsize);
        }

        // Update the pointer to the newly allocated memory
        d_pdu_magbuf = d_magbufs[d_magbufs.size() - 1].data();

        // Set new fft size and reset buffer index
        // (throws away any currently held data, but who cares?)
        d_fftsize = newfftsize;
        d_index = 0;

        // Reset window to reflect new size
        buildwindow();

        // Reset FFTW plan for new size
        d_fft = std::make_unique<fft::fft_complex_fwd>(d_fftsize);

        d_fbuf.clear();
        d_fbuf.resize(d_fftsize);

        d_fft_shift.resize(d_fftsize);

        d_last_time = 0;

        set_output_multiple(d_fftsize);

        return true;
    }
    return false;
}

bind_sys_paths(py::module& m)
{
    auto paths = m.def_submodule("paths", "GNU Radio default paths");
    /* would have loved to #include <pybind11/stl/filesystem.h> and return the paths
     * directly, but that requires a pybind11 too modern for Ubuntu20.04, so for now, just
     * return the string representation. Let's not return different types depending on the
     * version of a dependency.
     *
     * TODO: revisit 3.11

    paths.def("tmp", &::gr::paths::tmp);
    paths.def("appdata", &::gr::paths::appdata);
    paths.def("userconf", &::gr::paths::userconf);
