alist::read(const char* fname)
{
    std::ifstream file;
    std::string line;
    std::stringstream ss;

    file.open(fname);
    if (!(file.is_open())) {
        std::cout << "Could not open the file" << std::endl;
    }

    // Parse N and M
    std::getline(file, line);
    ss << line;
    ss >> N >> M;
    num_nlist.resize(N);
    num_mlist.resize(M);
    nlist.resize(N);
    mlist.resize(M);
    ss.seekg(0, std::ios::end);
    ss.clear();

    // parse max_num_n and max_num_m
    std::getline(file, line);
    ss << line;
    ss >> max_num_nlist >> max_num_mlist;
    ss.seekg(0, std::ios::end);
    ss.clear();

    // Parse weight of each column n
    std::getline(file, line);
    ss << line;
    for (int i = 0; i < N; i++) {
        ss >> num_nlist[i];
        nlist[i].resize(num_nlist[i]);
    }
    ss.seekg(0, std::ios::end);
    ss.clear();

    // Parse weight of each row m
    std::getline(file, line);
    ss << line;
    for (int i = 0; i < M; i++) {
        ss >> num_mlist[i];
        mlist[i].resize(num_mlist[i]);
    }
    ss.seekg(0, std::ios::end);
    ss.clear();

    // Parse indices with non zero entries in ith column
    for (int column = 0; column < N; column++) {
        std::getline(file, line);
        ss << line;
        for (int entry = 0; entry < num_nlist[column]; entry++) {
            ss >> nlist[column][entry];
        }
        ss.seekg(0, std::ios::end);
        ss.clear();
    }

    // Parse indices with non zero entries in ith row
    for (int row = 0; row < M; row++) {
        std::getline(file, line);
        ss << line;
        for (int entry = 0; entry < num_mlist[row]; entry++) {
            ss >> mlist[row][entry];
        }
        ss.seekg(0, std::ios::end);
        ss.clear();
    }

    file.close();
    data_ok = true;
}

