dvb_bch_bb_impl::calculate_crc_table(void)
{
    for (int divident = 0; divident < 256;
         divident++) { /* iterate over all possible input byte values 0 - 255 */
        std::bitset<MAX_BCH_PARITY_BITS> curByte(divident);
        curByte <<= num_parity_bits - 8;

        for (unsigned char bit = 0; bit < 8; bit++) {
            if ((curByte[num_parity_bits - 1]) != 0) {
                curByte <<= 1;
                curByte ^= polynome;
            } else {
                curByte <<= 1;
            }
        }
        crc_table[divident] = curByte;
    }
}

decode_ccsds_27_fb_impl::work(int noutput_items,
                                  gr_vector_const_void_star& input_items,
                                  gr_vector_void_star& output_items)
{
    const float* in = (const float*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];

    for (int i = 0; i < noutput_items * 16; i++) {
        // Translate and clip [-1.0..1.0] to [28..228]
        float sample = in[i] * 100.0 + 128.0;
        if (sample > 255.0)
            sample = 255.0;
        else if (sample < 0.0)
            sample = 0.0;
        unsigned char sym = (unsigned char)(floor(sample));

        d_viterbi_in[d_count % 4] = sym;
        if ((d_count % 4) == 3) {
            // Every fourth symbol, perform butterfly operation
            viterbi_butterfly2(d_viterbi_in, d_mettab, d_state0, d_state1);

            // Every sixteenth symbol, read out a byte
            if (d_count % 16 == 11) {
                // long metric =
                viterbi_get_output(d_state0, out++);
                // printf("%li\n", *(out-1), metric);
            }

            // Periodically normalize the path metrics to prevent overflow
            if (d_count % 65536 == 65535) {
                long diff = d_state0[0].metric;
                for (int j = 0; j < 64; j++) {
                    d_state0[j].metric -= diff;
                }
            }
        }

        d_count++;
    }

    return noutput_items;
}

