        if (d_alpha == 2) {
            d_norm = 1.0 / sqrt(60);
        }
        if (d_alpha == 4) {
            d_norm = 1.0 / sqrt(108);
        }
        break;
    default:
        if (d_alpha == 1) {
            d_norm = 1.0 / sqrt(10);
        }
        if (d_alpha == 2) {
            d_norm = 1.0 / sqrt(20);
        }
        if (d_alpha == 4) {
            d_norm = 1.0 / sqrt(52);
        }
        break;
    }
