squash_ff_impl::work(int noutput_items,
                         gr_vector_const_void_star& input_items,
                         gr_vector_void_star& output_items)
{
    const float* in = (const float*)input_items[0];
    float* out = (float*)output_items[0];

    for (int count = 0; count < noutput_items; count++) {

        for (unsigned int i = 0; i < d_inum; i++)
            d_iwork[i] = in[i];

        gsl_spline_init(d_spline, d_igrid, d_iwork, d_inum);

        for (unsigned int i = 0; i < d_onum; i++)
            out[i] = gsl_spline_eval(d_spline, d_ogrid[i], d_accel);

        in += d_inum;
        out += d_onum;
    }

    return noutput_items;
}

simple_squelch_cc_impl::work(int noutput_items,
                                 gr_vector_const_void_star& input_items,
                                 gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    for (int i = 0; i < noutput_items; i++) {
        double mag_sqrd = in[i].real() * in[i].real() + in[i].imag() * in[i].imag();
        double f = d_iir.filter(mag_sqrd);
        if (f >= d_threshold)
            out[i] = in[i];
        else
            out[i] = 0;
    }

    d_unmuted = d_iir.prev_output() >= d_threshold;
    return noutput_items;
}

