dvbt2_interleaver_bb_impl::twist_interleave_columns(
    int* tempv, int* tempu, int rows, int mod, const int* twist)
{
    int index = 0, offset;
    for (int col = 0; col < mod; col++) {
        offset = twist[col];
        for (int row = 0; row < rows; row++) {
            tempv[offset + (rows * col)] = tempu[index++];
            offset++;
            if (offset == rows) {
                offset = 0;
            }
        }
    }
}

