siso_f_impl::forecast(int noutput_items, gr_vector_int& ninput_items_required)
{
    int multiple;
    if (d_POSTI && d_POSTO)
        multiple = d_FSM.I() + d_FSM.O();
    else if (d_POSTI)
        multiple = d_FSM.I();
    else if (d_POSTO)
        multiple = d_FSM.O();
    else
        throw std::runtime_error("Not both POSTI and POSTO can be false.");

    // printf("forecast: Multiple = %d\n",multiple);
    int input_required1 = d_FSM.I() * (noutput_items / multiple);
    int input_required2 = d_FSM.O() * (noutput_items / multiple);
    // printf("forecast: Output requirements:  %d\n",noutput_items);
    // printf("forecast: Input requirements:  %d   %d\n",input_required1,input_required2);
    unsigned ninputs = ninput_items_required.size();
    for (unsigned int i = 0; i < ninputs / 2; i++) {
        ninput_items_required[2 * i] = input_required1;
        ninput_items_required[2 * i + 1] = input_required2;
    }
}

dvbt_bit_inner_deinterleaver_impl::general_work(
    int noutput_items,
    gr_vector_int& ninput_items,
    gr_vector_const_void_star& input_items,
    gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* outh = (unsigned char*)output_items[0];
    unsigned char* outl = nullptr;

    if (d_hierarchy != NH) {
        outl = (unsigned char*)output_items[1];
    }

    int bmax = noutput_items * d_nsize / d_bsize;

    // First index of d_b is Bit interleaver number
    // Second index of d_b is the position inside Bit interleaver
    unsigned char d_b[MAX_MODULATION_ORDER][INTERLEAVER_BLOCK_SIZE];

    for (int bcount = 0; bcount < bmax; bcount++) {
        for (int w = 0; w < d_bsize; w++) {
            int c = in[(bcount * d_bsize) + w];

            for (int e = 0; e < d_v; e++) {
                d_b[e][d_lookup_H[w][e]] = (c >> (d_v - e - 1)) & 1;
            }
        }

        for (int i = 0; i < d_bsize; i++) {
            if (d_hierarchy == NH) {
                // Create output from demultiplexer
                int c = 0;

                for (int k = 0; k < d_v; k++) {
                    c = (c << 1) | d_b[d_perm[(d_v * i) + k]][i];
                }

                outh[(bcount * d_bsize) + i] = c;
            } else {
                int c = 0;

                // High priority output - first 2 streams
                for (int k = 0; k < 2; k++) {
                    c = (c << 1) | d_b[(d_v * i + k) % 2][(d_v * i + k) / 2];
                }

                outh[(bcount * d_bsize) + i] = c;

                c = 0;
                // Low priority output - (v - 2) streams
                for (int k = 2; k < (d_v - 2); k++) {
                    c = (c << 1) | d_b[d_perm[d_v * i + k]][(d_v * i + k) / (d_v - 2)];
                }

                outl[(bcount * d_bsize) + i] = c;
            }
        }
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    consume_each(noutput_items);

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

