        hier_in = dst->message_port_is_hier_out(dstport);
        ;
    } else {
        hier_out = src->message_port_is_hier_out(srcport);
        hier_in = dst->message_port_is_hier_in(dstport);
    }

    hier_block2_sptr src_block(cast_to_hier_block2_sptr(src));
    hier_block2_sptr dst_block(cast_to_hier_block2_sptr(dst));

    if (src_block && src.get() != d_owner) {
        d_debug_logger->debug("msg_connect: src is hierarchical, setting parent to {:p}",
                              (void*)this);
        src_block->d_detail->set_parent(this->d_owner);
    }

    if (dst_block && dst.get() != d_owner) {
        d_debug_logger->debug("msg_connect: dst is hierarchical, setting parent to {:p}",
                              (void*)this);
        dst_block->d_detail->set_parent(this->d_owner);
    }

    // add edge for this message connection
    d_debug_logger->debug("msg_connect( ({}, {}, {:d}), ({}, {}, {:d}) )",
                          src->identifier(),
                          pmt::write_string(srcport),
                          hier_out,
                          dst->identifier(),
                          pmt::write_string(dstport),
                          hier_in);
    d_fg->connect(msg_endpoint(src, srcport, hier_out),
                  msg_endpoint(dst, dstport, hier_in));
}

dvbt_symbol_inner_interleaver_impl::calculate_R(int i)
{
    const int Nr = int(ceil(log2(d_fft_length)));
    int reg = 0;

    if (i == 0) {
        reg = 0;
    } else if (i == 1) {
        reg = 0;
    } else {
        reg = 1;
        for (int k = 3; k <= i; k++) {
            char new_bit = 0;

            if (d_transmission_mode == T2k) {
                new_bit = (reg ^ (reg >> 3)) & 1;
            } else if (d_transmission_mode == T8k) {
                new_bit = (reg ^ (reg >> 1) ^ (reg >> 4) ^ (reg >> 6)) & 1;
            } else {
                new_bit = (reg ^ (reg >> 3)) & 1;
            }

            int mask = (1 << Nr) - 1;
            reg = ((reg >> 1) | (new_bit << (Nr - 2))) & mask;
        }
    }

    int newreg = 0;

    for (int k = 0; k < (Nr - 1); k++) {
        char bit = (reg >> k) & 1;
        newreg = newreg | (bit << d_bit_perm[k]);
    }

    return newreg;
}

repack_bits_bb_impl::calculate_output_stream_length(const gr_vector_int& ninput_items)
{
    int n_out_bytes_required = (ninput_items[0] * d_k) / d_l;
    if ((ninput_items[0] * d_k) % d_l &&
        (!d_packet_mode || (d_packet_mode && !d_align_output))) {
        n_out_bytes_required++;
    }

    return n_out_bytes_required;
}

