eye_sink_f_impl::_test_trigger_norm(int nitems, gr_vector_const_void_star inputs)
{
    int trigger_index;
    const float* in = (const float*)inputs[d_trigger_channel];
    for (trigger_index = 0; trigger_index < nitems; trigger_index++) {
        d_trigger_count++;

        // Test if trigger has occurred based on the input stream,
        // channel number, and slope direction
        if (_test_trigger_slope(&in[trigger_index])) {
            d_triggered = true;
            d_start = d_index + trigger_index - d_trigger_delay;
            d_end = d_start + d_size;
            d_trigger_count = 0;
            _adjust_tags(-d_start);
            break;
        }
    }

    // If using auto trigger mode, trigger periodically even
    // without a trigger event.
    if ((d_trigger_mode == gr::qtgui::TRIG_MODE_AUTO) && (d_trigger_count > d_size)) {
        d_triggered = true;
        d_trigger_count = 0;
    }
}

clock_tracking_loop::update_gains()
{
    float omega_n_T, omega_d_T, zeta_omega_n_T, cosx_omega_d_T;
    float k0, k1, sinh_zeta_omega_n_T;
    float alpha, beta;

    omega_n_T = d_omega_n_norm;
    zeta_omega_n_T = d_zeta * omega_n_T;
    k0 = 2.0f / d_ted_gain;
    k1 = expf(-zeta_omega_n_T);
    sinh_zeta_omega_n_T = sinhf(zeta_omega_n_T);

    if (d_zeta > 1.0f) { // Over-damped (or critically-damped too)

        omega_d_T = omega_n_T * sqrtf(d_zeta * d_zeta - 1.0f);
        cosx_omega_d_T = coshf(omega_d_T);
        // cosh ---------^^^^

    } else if (d_zeta == 1.0f) { // Critically-damped

        omega_d_T = 0.0f;
        cosx_omega_d_T = 1.0f;
        // cosh(omega_d_T) & cos(omega_d_T) are both 1 for omega_d_T == 0

    } else { // Under-damped (or critically-damped too)

        omega_d_T = omega_n_T * sqrtf(1.0 - d_zeta * d_zeta);
        cosx_omega_d_T = cosf(omega_d_T);
        // cos ----------^^^
    }

    alpha = k0 * k1 * sinh_zeta_omega_n_T;
    beta = k0 * (1 - k1 * (sinh_zeta_omega_n_T + cosx_omega_d_T));

    set_alpha(alpha);
    set_beta(beta);
}

