tpc_decoder::gamma(const std::vector<float> rx_array, const int symbol)
{
    float rm = 0;
    int ii;
    int mask;
    int nn = rx_array.size();

    mask = 1;
    for (ii = 0; ii < nn; ii++) {
        if (symbol & mask)
            rm += rx_array[nn - ii - 1];
        mask = mask << 1;
    }

    //     DEBUG_PRINT("nn=%d symbol=%d rm = %f\n", nn, symbol, rm);
    //     DEBUG_PRINT_F(fp, "nn=%d symbol=%d rm = %f\n", nn, symbol, rm);

    return (rm);
}

