dictionary_logger_backend::sink_it_(const spdlog::details::log_msg& message)
{
    const auto& logger_name = message.logger_name;
    if (has_regex) {
        if (!std::regex_match(logger_name.begin(), logger_name.end(), src_regex)) {
            // do nothing if regex is set and does not match
            return;
        }
    }

    const auto& payload = message.payload;
    std::scoped_lock lock(map_mutex);

    auto& message_set =
        log_entries[std::string{ logger_name.data(), logger_name.size() }];
    // usually, log messages should come in chronologically
    message_set.emplace_hint(message_set.end(),
                             log_entry(message.time, { payload.data(), payload.size() }));
}

prefs::has_option(const std::string& section, const std::string& option)
{
    if (option_to_env(section, option))
        return true;

    if (!has_section(section)) {
        return false;
    }

    std::string s = section;
    stolower(s);
    std::string o = option;
    stolower(o);

    std::lock_guard<std::mutex> lk(d_mutex);
    const auto& sec = d_config_map[s];
    return sec.find(o) != sec.end();
}

vector_map_impl::work(int noutput_items,
                          gr_vector_const_void_star& input_items,
                          gr_vector_void_star& output_items)
{
    const char** inv = (const char**)&input_items[0];
    char** outv = (char**)&output_items[0];

    for (unsigned int n = 0; n < (unsigned int)(noutput_items); n++) {
        for (unsigned int i = 0; i < d_mapping.size(); i++) {
            unsigned int out_vlen = d_mapping[i].size();
            for (unsigned int j = 0; j < out_vlen; j++) {
                unsigned int s = d_mapping[i][j][0];
                unsigned int k = d_mapping[i][j][1];
                memcpy(outv[i] + out_vlen * d_item_size * n + d_item_size * j,
                       inv[s] + d_in_vlens[s] * d_item_size * n + k * d_item_size,
                       d_item_size);
            }
        }
    }

    return noutput_items;
}

