constellation_8psk_natural::decision_maker(const gr_complex* sample)
{
    unsigned int ret = 0;

    float re = sample->real();
    float im = sample->imag();

    if ((re + im) < 0)
        ret = 4;
    if (fabsf(im) > fabsf(re)) {
        ret |= 2;
        if (re * im < 0)
            ret |= 1;
    }
    if (fabsf(im) < fabsf(re) && re * im > 0)
        ret |= 1;

    return ret;
}

