def read_big_bitlist(bitlist):
    ret = []
    for j in range(0, len(bitlist) / 64):
        res = 0
        for i in range(0, 64):
            if int(bitlist[j * 64 + i]) == 1:
                res += 1 << (64 - i - 1)
        ret.append(res)
    res = 0
    j = 0
    for i in range(len(bitlist) % 64):
        if int(bitlist[len(ret) * 64 + i]) == 1:
            res += 1 << (64 - j - 1)
        j += 1
    ret.append(res)
    return ret

