compute_A(double freq,
                                       unsigned int n_taps_half,
                                       const std::vector<double>& ad,
                                       const std::vector<double>& x,
                                       const std::vector<double>& y)
{
    double denom = 0;
    double numer = 0;
    const double xc = cos(PI2 * freq);
    for (unsigned int i = 0; i <= n_taps_half; i++) {
        double c = xc - x[i];
        if (fabs(c) < 1.0e-7) {
            numer = y[i];
            denom = 1;
            break;
        }
        c = ad[i] / c;
        denom += c;
        numer += c * y[i];
    }
    return numer / denom;
}

