work(int noutput_items,
                                                  gr_vector_const_void_star& input_items,
                                                  gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock l(this->d_setlock);

    const IN_T* in = (const IN_T*)input_items[0];
    OUT_T* out = (OUT_T*)output_items[0];

    if (d_updated) {
        this->set_history(d_fir.ntaps());
        d_updated = false;
        return 0; // history requirements may have changed.
    }

    if (this->decimation() == 1) {
        d_fir.filterN(out, in, noutput_items);
    } else {
        d_fir.filterNdec(out, in, noutput_items, this->decimation());
    }

    return noutput_items;
}

dvbt2_framemapper_cc_impl::add_crc32_bits(unsigned char* in, int length)
{
    unsigned int crc = 0xffffffff;
    int b;
    int i = 0;

    for (int n = 0; n < length; n++) {
        b = in[i++] ^ ((crc >> 31) & 0x01);
        crc <<= 1;
        if (b) {
            crc ^= CRC_POLY;
        }
    }

    for (int n = 31; n >= 0; n--) {
        in[i++] = (crc & (1 << n)) ? 1 : 0;
    }
    return 32;
}

