{
    if (sps <= 0) {
        throw std::out_of_range("fll_band_edge_cc: invalid number of sps. Must be > 0.");
    }
    {
        /* local lock - release before calling design_filter, such that other setter calls
         * might also called before the large mutex'ed section in design_filter. */
        gr::thread::scoped_lock lock(d_setlock);
        d_sps = sps;
    }
    set_max_freq(M_TWOPI * (2.0 / sps));
    set_min_freq(-M_TWOPI * (2.0 / sps));
    set_beta(4.0 * d_bandwidth / sps);
    design_filter();
}

d_result_reflected(result_reflected)
{
    if ((num_bits < 8) || (num_bits > 64)) {
        throw std::runtime_error("CRC number of bits must be between 8 and 64");
    }

    d_table[0] = 0;
    if (d_input_reflected) {
        poly = reflect(poly);
        uint64_t crc = 1;
        int i = 128;
        do {
            if (crc & 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
            for (int j = 0; j < 256; j += 2 * i) {
                d_table[i + j] = (crc ^ d_table[j]) & d_mask;
            }
            i >>= 1;
        } while (i > 0);
    } else {
        const uint64_t msb = static_cast<uint64_t>(1) << (num_bits - 1);
        uint64_t crc = msb;
        int i = 1;
        do {
            if (crc & msb) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
            for (int j = 0; j < i; ++j) {
                d_table[i + j] = (crc ^ d_table[j]) & d_mask;
            }
            i <<= 1;
        } while (i < 256);
    }
}

