    //  if((bitcnt % 8) == 5 && bitcnt > 32) {

    //  Find current best path
    unsigned int i, beststate;
    int bestmetric;

    bestmetric = state[0].metric;
    beststate = 0;
    for (i = 1; i < 64; i++)
