firdes::compute_ntaps(double sampling_freq,
                          double transition_width,
                          fft::window::win_type window_type,
                          double param)
{
    double a = fft::window::max_attenuation(window_type, param);
    int ntaps = (int)(a * sampling_freq / (22.0 * transition_width));
    if ((ntaps & 1) == 0) // if even...
        ntaps++;          // ...make odd

    return ntaps;
}

modnn(struct rs* rs, unsigned int x)
{
    while (x >= rs->nn) {
        x -= rs->nn;
        x = (x >> rs->mm) + (x & rs->nn);
    }
    return x;
}

