constellation::calc_hard_symbol_metric(const gr_complex* sample, float* metric)
{
    float minm = FLT_MAX;
    unsigned int minmi = 0;
    for (unsigned int o = 0; o < d_arity; o++) {
        float dist = get_distance(o, sample);
        if (dist < minm) {
            minm = dist;
            minmi = o;
        }
    }
