filter(const gr_complex input)
{
    gr_complex acc;
    unsigned i = 0;
    unsigned n = ntaps_ff();
    unsigned m = ntaps_fb();

    if (n == 0)
        return (gr_complex)0;

    int latest_n = d_latest_n;
    int latest_m = d_latest_m;

    acc = d_fftaps[0] * input;
    for (i = 1; i < n; i++)
        acc += (d_fftaps[i] * d_prev_input[latest_n + i]);
    for (i = 1; i < m; i++)
        acc += (d_fbtaps[i] * d_prev_output[latest_m + i]);

    // store the values twice to avoid having to handle wrap-around in the loop
    d_prev_output[latest_m] = acc;
    d_prev_output[latest_m + m] = acc;
    d_prev_input[latest_n] = input;
    d_prev_input[latest_n + n] = input;

    latest_n--;
    latest_m--;
    if (latest_n < 0)
        latest_n += n;
    if (latest_m < 0)
        latest_m += m;

    d_latest_m = latest_m;
    d_latest_n = latest_n;
    return static_cast<gr_complex>(acc);
}

polar_encoder::encode_vector_packed_interbyte(unsigned char* target) const
{
    int branch_byte_size = 1;
    unsigned char* pos;
    int n_branches = block_size() >> 4;
    int byte = 0;
    for (int stage = 3; stage < block_power(); ++stage) {
        pos = target;

        for (int branch = 0; branch < n_branches; ++branch) {

            byte = 0;
            while (byte < branch_byte_size) {
                *pos ^= *(pos + branch_byte_size);
                ++pos;
                ++byte;
            }

            pos += branch_byte_size;
        }

        n_branches >>= 1;
        branch_byte_size <<= 1;
    }
}

