eye_sink_f_impl::handle_pdus(pmt::pmt_t msg)
{
    size_t len;
    pmt::pmt_t dict, samples;

    // Test to make sure this is either a PDU or a uniform vector of
    // samples. Get the samples PMT and the dictionary if it's a PDU.
    // If not, we throw an error and exit.
    if (pmt::is_pair(msg)) {
        dict = pmt::car(msg);
        samples = pmt::cdr(msg);
    } else if (pmt::is_uniform_vector(msg)) {
        samples = msg;
    } else {
        throw std::runtime_error("eye_sink_c: message must be either "
                                 "a PDU or a uniform vector of samples.");
    }

    len = pmt::length(samples);

    const float* in;
    if (pmt::is_f32vector(samples)) {
        in = (const float*)pmt::f32vector_elements(samples, len);
    } else {
        throw std::runtime_error("eye_sink_f: unknown data type "
                                 "of samples; must be float.");
    }

    // Plot if we're past the last update time
    if (gr::high_res_timer_now() - d_last_time > d_update_time) {
        d_last_time = gr::high_res_timer_now();

        set_nsamps(len);

        volk_32f_convert_64f(d_buffers[d_nconnections].data(), in, len);

        std::vector<std::vector<gr::tag_t>> t;
        d_qApplication->postEvent(d_main_gui, new TimeUpdateEvent(d_buffers, len, t));
    }
}

FreqControlPanel::toggleFFTSize(int val)
{
    // Check if val is contained in combobox
    if (d_fft_size_combo->findText(QString::number(val)) > 0)
        d_fft_size_combo->setCurrentText(QString::number(val));
    else {
        // Find greatest entry in combobox < val
        int count = 1;
        int test = val >> 1;
        while (test > 0) {
            count *= 2;
            test = test >> 1;
        }
        d_fft_size_combo->setCurrentText(QString::number(count));
    }
}

skiphead_impl::general_work(int noutput_items,
                                gr_vector_int& ninput_items_,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    const char* in = (const char*)input_items[0];
    char* out = (char*)output_items[0];

    int ninput_items = std::min(ninput_items_[0], noutput_items);
    int ii = 0; // input index

    while (ii < ninput_items) {
        uint64_t ni_total = ii + d_nitems; // total items processed so far
        if (ni_total < d_nitems_to_skip) { // need to skip some more

            int n_to_skip =
                (int)std::min(d_nitems_to_skip - ni_total, (uint64_t)(ninput_items - ii));
            ii += n_to_skip;
        }

        else { // nothing left to skip. copy away
            // Grab all tags in the window and shift their offsets appropriately
            get_tags_in_window(d_tags, 0, ii, ninput_items);
            for (auto& tag : d_tags) {
                tag.offset -= d_nitems_to_skip;
                add_item_tag(0, tag);
            }
            int n_to_copy = ninput_items - ii;
            if (n_to_copy > 0) {
                size_t itemsize = output_signature()->sizeof_stream_item(0);
                memcpy(out, in + (ii * itemsize), n_to_copy * itemsize);
            }

            d_nitems += ninput_items;
            consume_each(ninput_items);
            return n_to_copy;
        }
    }

    d_nitems += ninput_items;
    consume_each(ninput_items);
    return 0;
}

