def ask_yes_no(question, default):
    """ Asks a binary question. Returns True for yes, False for no.
    default is given as a boolean. """
    question += {True: ' [Y/n] ', False: ' [y/N] '}[default]
    if input(question).lower() != {True: 'n', False: 'y'}[default]:
        return default
    else:
        return not default

hier_block2_detail::resolve_port(int port, bool is_input)
{
    std::stringstream msg;

    d_debug_logger->debug("Resolving port {:d} as an {:s} of {:s}",
                          port,
                          is_input ? "input" : "output",
                          d_owner->name());

    endpoint_vector_t result;

    if (is_input) {
        if (port < 0 || port >= (signed)d_inputs.size()) {
            msg << "resolve_port: hierarchical block '" << d_owner->name() << "': input "
                << port << " is out of range";
            throw std::runtime_error(msg.str());
        }

        if (d_inputs[port].empty()) {
            msg << "resolve_port: hierarchical block '" << d_owner->name() << "': input "
                << port << " is not connected internally";
            throw std::runtime_error(msg.str());
        }

        endpoint_vector_t& endps = d_inputs[port];
        endpoint_viter_t p;
        for (p = endps.begin(); p != endps.end(); p++) {
            endpoint_vector_t tmp = resolve_endpoint(*p, true);
            std::copy(tmp.begin(), tmp.end(), back_inserter(result));
        }
    } else {
        if (port < 0 || port >= (signed)d_outputs.size()) {
            msg << "resolve_port: hierarchical block '" << d_owner->name() << "': output "
                << port << " is out of range";
            throw std::runtime_error(msg.str());
        }

        if (d_outputs[port] == endpoint()) {
            msg << "resolve_port: hierarchical block '" << d_owner->name() << "': output "
                << port << " is not connected internally";
            throw std::runtime_error(msg.str());
        }

        result = resolve_endpoint(d_outputs[port], false);
    }

    if (result.empty()) {
        msg << "resolve_port: hierarchical block '" << d_owner->name()
            << "': unable to resolve " << (is_input ? "input port " : "output port ")
            << port;
        throw std::runtime_error(msg.str());
    }

    return result;
}

multiply_by_tag_value_cc_impl::work(int noutput_items,
                                        gr_vector_const_void_star& input_items,
                                        gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    std::vector<tag_t> tags;
    get_tags_in_window(tags, 0, 0, noutput_items, d_tag_key);

    int start = 0, end;
    for (const auto& tag : tags) {
        end = tag.offset - nitems_read(0);
        end *= d_vlen;

        // Multiply based on the current value of k from 'start' to 'end'
#if VOLK_VERSION >= 030100
        volk_32fc_s32fc_multiply2_32fc(&out[start], &in[start], &d_k, (end - start));
#else
        volk_32fc_s32fc_multiply_32fc(&out[start], &in[start], d_k, (end - start));
#endif
        start = end;

        // Extract new value of k
        pmt::pmt_t k = tag.value;
        if (pmt::is_complex(k)) {
            d_k = pmt::to_complex(k);
        } else if (pmt::is_number(k)) {
            d_k = gr_complex(pmt::to_double(k), 0);
        } else {
            d_logger->warn("Got key '{:s}' with incompatible value of '{:s}'",
                           pmt::write_string(d_tag_key),
                           pmt::write_string(k));
        }
    }

#if VOLK_VERSION >= 030100
    volk_32fc_s32fc_multiply2_32fc(
        &out[start], &in[start], &d_k, (d_vlen * noutput_items - start));
#else
    volk_32fc_s32fc_multiply_32fc(
        &out[start], &in[start], d_k, (d_vlen * noutput_items - start));
#endif

    return noutput_items;
}

