    } else if (type == "CONSTANT") {
        d_siggen_ref->set_waveform(::uhd::rfnoc::siggen_waveform::CONSTANT, chan);
    } else if (type == "SINE_WAVE") {
        d_siggen_ref->set_waveform(::uhd::rfnoc::siggen_waveform::SINE_WAVE, chan);
