codec2_encode_sp_impl::unpack_frame(const unsigned char* packed, unsigned char* out)
{
    int byte_idx = 0, bit_idx = 0;
    for (int k = 0; k < d_bits_per_frame; k++) {
        out[k] = (packed[byte_idx] >> (7 - bit_idx)) & 0x01;
        bit_idx = (bit_idx + 1) % 8;
        if (bit_idx == 0) {
            byte_idx++;
        }
    }
}

