        d_alpha = 1;
        break;
    case ALPHA1:
        d_alpha = 1;
        break;
    case ALPHA2:
        d_alpha = 2;
        break;
    case ALPHA4:
        d_alpha = 4;
        break;
    default:
        d_alpha = 1;
        break;
    }

    // ETSI EN 400 744 Clause 4.4
    // Normalization factor
    switch (d_m) {
    case 2:
        d_norm = 1.0 / sqrt(2);
        break;
    case 4:
        if (d_alpha == 1) {
            d_norm = 1.0 / sqrt(10);
        }
        if (d_alpha == 2) {
            d_norm = 1.0 / sqrt(20);
        }
        if (d_alpha == 4) {
            d_norm = 1.0 / sqrt(52);
        }
        break;
    case 6:
        if (d_alpha == 1) {
            d_norm = 1.0 / sqrt(42);
        }
        if (d_alpha == 2) {
            d_norm = 1.0 / sqrt(60);
        }
        if (d_alpha == 4) {
            d_norm = 1.0 / sqrt(108);
        }
        break;
    default:
        if (d_alpha == 1) {
            d_norm = 1.0 / sqrt(10);
        }
        if (d_alpha == 2) {
            d_norm = 1.0 / sqrt(20);
        }
        if (d_alpha == 4) {
            d_norm = 1.0 / sqrt(52);
        }
        break;
    }
}

