    } else {
        d_logger->info("FFT size must be >= {} and <= {}.\nSo falling back to {}.",
                       d_main_gui.MIN_FFT_SIZE,
                       d_main_gui.MAX_FFT_SIZE,
                       d_main_gui.DEFAULT_FFT_SIZE);
        d_main_gui.setFFTSize(d_main_gui.DEFAULT_FFT_SIZE);
    }
}

