waterfall_sink_c_impl::resize_bufs(int size)
{
    // Resize residbuf and replace data.
    for (auto& buf : d_residbufs) {
        buf.clear();
        buf.resize(size);
    }
    for (auto& mag : d_magbufs) {
        mag.clear();
        mag.resize(size);
    }

    // Expand PDU buffer to required size.
    auto& last_magbuf = d_magbufs[d_magbufs.size() - 1];
    last_magbuf.resize(size * d_nrows);
    d_pdu_magbuf = last_magbuf.data();
}

def _update_search_tree(self, widget):
        key = widget.get_text().lower()
        if not key:
            self.treeview.set_model(self.treestore)
            self.expand_module_in_tree()
        else:
            matching_blocks = [b for b in list(self.platform.blocks.values())
                               if key in b.key.lower() or key in b.label.lower()]

            self.treestore_search.clear()
            self._categories_search = {tuple(): None}
            for block in matching_blocks:
                self.add_block(block, self.treestore_search,
                               self._categories_search)
            self.treeview.set_model(self.treestore_search)
            self.treeview.expand_all()

vector_sink_f_impl::work(int noutput_items,
                             gr_vector_const_void_star& input_items,
                             gr_vector_void_star& output_items)
{
    const float* in = (const float*)input_items[0];

    // See if we generate a message
    check_clicked();

    for (int i = 0; i < noutput_items; i++) {
        if (gr::high_res_timer_now() - d_last_time > d_update_time) {
            for (int n = 0; n < d_nconnections; n++) {
                in = ((const float*)input_items[n]) + d_vlen;
                for (unsigned int x = 0; x < d_vlen; x++) {
                    d_magbufs[n][x] =
                        (double)((1.0 - d_vecavg) * d_magbufs[n][x] + (d_vecavg)*in[x]);
                }
            }
            d_last_time = gr::high_res_timer_now();
            d_qApplication->postEvent(d_main_gui, new FreqUpdateEvent(d_magbufs, d_vlen));
        }
    }

    return noutput_items;
}

