permutation_impl::work(int noutput_items,
                           gr_vector_const_void_star& input_items,
                           gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock guard(d_setlock);
    int nstreams = input_items.size();

    for (int m = 0; m < nstreams; m++) {
        const char* in = (const char*)input_items[m];
        char* out = (char*)output_items[m];

        // per stream processing
        for (int i = 0; i < noutput_items / d_SYMS_PER_BLOCK; i++) {
            // Index i refers to blocks.
            // Beginning of packet (in blocks)
            int i0 = d_K * (i / d_K);
            // position of block within packet (in blocks)
            int j0 = i % d_K;
            // new position of block within packet (in blocks)
            int k0 = d_TABLE[j0];
            memcpy(&(out[i * d_SYMS_PER_BLOCK * d_BYTES_PER_SYMBOL]),
                   &(in[(i0 + k0) * d_SYMS_PER_BLOCK * d_BYTES_PER_SYMBOL]),
                   d_BYTES_PER_SYMBOL * d_SYMS_PER_BLOCK);
        }
        // end per stream processing
    }
    return noutput_items;
}

benchmark(functor test, size_t block_size)
{
    std::vector<float> outp(2 * block_size);
    float* output = outp.data();
    float *x = &output[0], *y = &output[block_size];

    // generate input in the first half, and also in the second half to touch the memory
    gr::xoroshiro128p_prng rng(42);
    for (auto& value : outp) {
        value = rng() / static_cast<double>(1ULL << 32) - (1ULL << 32);
    }

    auto before = std::chrono::high_resolution_clock::now();
    // do the actual work

    test(x, y);

    auto after = std::chrono::high_resolution_clock::now();
    // get ending CPU usage
    auto dur =
        std::chrono::duration_cast<std::chrono::duration<double, std::ratio<1, 1>>>(
            after - before);

    // prevent the compiler from discarding the output, not doing the calculations.
    volatile auto sum = std::accumulate(outp.cbegin(), outp.cend(), 0.0f);
    if (sum == std::numeric_limits<decltype(sum)>::min()) {
        // should never be hit
        return decltype(dur){};
    }

    return dur;
}

