{
    int total_bits;
    int total_bit_errors;

    if (freedv_get_test_frames(d_freedv)) {
        total_bits = freedv_get_total_bits(d_freedv);
        total_bit_errors = freedv_get_total_bit_errors(d_freedv);
        d_logger->error("bits: {:8d} errors: {:8d} BER: {:3.2f}",
                        total_bits,
                        total_bit_errors,
