float_to_uchar_impl::work(int noutput_items,
                              gr_vector_const_void_star& input_items,
                              gr_vector_void_star& output_items)
{
    const float* in = (const float*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];

#if VOLK_VERSION >= 030100
    volk_32f_s32f_x2_convert_8u(out, in, d_scale, d_bias, d_vlen * noutput_items);
#else
    const float min_val = 0.0f;
    const float max_val = UINT8_MAX;
    const int nitems = d_vlen * noutput_items;
    for (int j = 0; j < nitems; ++j) {
        const float r = in[j] * d_scale + d_bias;
        unsigned char u;
        if (r > max_val) {
            u = (uint8_t)(max_val);
        } else if (r < min_val) {
            u = (uint8_t)(min_val);
        } else {
            u = (uint8_t)(rintf(r));
        }
        out[j] = u;
    }
#endif

    return noutput_items;
}

message_debug_impl::print(const pmt::pmt_t& msg)
{
    if (pmt::is_pdu(msg)) {
        const auto& meta = pmt::car(msg);
        const auto& vector = pmt::cdr(msg);

        fmt::print("{:*^{}}\n"
                   "{:s}\n",
                   " VERBOSE PDU DEBUG PRINT ",
                   PRINT_LINE_LENGTH,
                   pmt::write_string(meta));

        size_t len = pmt::blob_length(vector);
        if (d_en_uvec) {
            fmt::print("pdu length = {:10d} bytes\n"
                       "pdu vector contents = \n",
                       len);
            size_t offset(0);
            const uint8_t* d =
                (const uint8_t*)pmt::uniform_vector_elements(vector, offset);
            for (size_t i = 0; i < len; i += 16) {
                fmt::print("{:04x}: ", static_cast<unsigned int>(i));
                for (size_t j = i; j < std::min(i + 16, len); j++) {
                    fmt::print("{:02x} ", d[j]);
                }
                fmt::print("\n");
            }
        } else {
            fmt::print("pdu length = {:10d} bytes (printing disabled)\n", len);
        }

    } else {
        fmt::print("{:*^{}}\n"
                   "{:s}\n",
                   " MESSAGE DEBUG PRINT ",
                   PRINT_LINE_LENGTH,
                   pmt::write_string(msg));
