QRfnocF15Surface::sendWaterfall(const uint8_t* wf, int n)
{
    int m;

    // Limit to max height
    if (n > d_wf_lines) {
        wf += d_fft_bins * (n - d_wf_lines);
        n = d_wf_lines;
    }

    // Copy the new data
    while (n) {
        m = n > (d_wf_lines - d_wf.pos) ? (d_wf_lines - d_wf.pos) : n;
        memcpy(&d_wf.data_buf[d_wf.pos * d_fft_bins], wf, m * d_fft_bins);
        d_wf.pos = (d_wf.pos + m) % d_wf_lines;
        wf += m * d_fft_bins;
        n -= m;
    }

    // Force refresh
    d_wf.dirty = true;
}

