encode(unsigned char* symbols,
                     const unsigned char* data,
                     unsigned int nbytes,
                     unsigned char encstate)
{
    int i;

    while (nbytes-- != 0) {
        for (i = 7; i >= 0; i--) {
            encstate = (encstate << 1) | ((*data >> i) & 1);
            *symbols++ = Partab[encstate & POLYA];
            *symbols++ = Partab[encstate & POLYB];
        }
        data++;
    }

    return encstate;
}

dvbt2_interleaver_bb_impl::generate_lookup()
{
    int rows, index = 0;
    // vectors instead of arrays because they're fairly big.
    std::vector<int> tempv2(FRAME_SIZE_NORMAL);
    std::vector<int> tempu2(FRAME_SIZE_NORMAL);
    const int* twist;
    const int *c1, *c2, *c3, *c4, *c5, *c6, *c7, *c8;
    const int *c9, *c10, *c11, *c12, *c13, *c14, *c15, *c16;

    for (int i = 0; i < FRAME_SIZE_NORMAL; i++) {
        lookup_table[i] = i;
    }

    const int* in = &lookup_table[0];

    switch (signal_constellation) {
        // ignore QPSK, not worth it, as there is no column interleaving
    case MOD_16QAM:
        rows = frame_size / (mod * 2);

        if (frame_size == FRAME_SIZE_NORMAL) {
            twist = &twist16n[0];
        } else {
            twist = &twist16s[0];
        }

        interleave_parity_bits(tempu2.data(), in);

        c1 = &tempv2[0];
        c2 = &tempv2[rows];
        c3 = &tempv2[rows * 2];
        c4 = &tempv2[rows * 3];
        c5 = &tempv2[rows * 4];
        c6 = &tempv2[rows * 5];
        c7 = &tempv2[rows * 6];
        c8 = &tempv2[rows * 7];

        twist_interleave_columns(tempv2.data(), tempu2.data(), rows, mod * 2, twist);

        for (int j = 0; j < rows; j++) {
            tempu2[index++] = c1[j];
            tempu2[index++] = c2[j];
            tempu2[index++] = c3[j];
            tempu2[index++] = c4[j];
            tempu2[index++] = c5[j];
            tempu2[index++] = c6[j];
            tempu2[index++] = c7[j];
            tempu2[index++] = c8[j];
