    case MOD_64QAM:
        rows = frame_size / (mod * 2);

        if (frame_size == FRAME_SIZE_NORMAL) {
            twist = twist64n;
        } else {
            twist = twist64s;
        }

        interleave_parity_bits(tempu2.data(), in);

        c1 = &tempv2[0];
