        for (int j = 0; j < rows; j++) {
            tempu2[index++] = c1[j];
            tempu2[index++] = c2[j];
            tempu2[index++] = c3[j];
            tempu2[index++] = c4[j];
            tempu2[index++] = c5[j];
            tempu2[index++] = c6[j];
            tempu2[index++] = c7[j];
            tempu2[index++] = c8[j];
            tempu2[index++] = c9[j];
            tempu2[index++] = c10[j];
            tempu2[index++] = c11[j];
            tempu2[index++] = c12[j];
        }
        break;

    case MOD_256QAM:
        if (frame_size == FRAME_SIZE_NORMAL) {
            rows = frame_size / (mod * 2);

            interleave_parity_bits(tempu2.data(), in);

            c1 = &tempv2[0];
            c2 = &tempv2[rows];
            c3 = &tempv2[rows * 2];
            c4 = &tempv2[rows * 3];
            c5 = &tempv2[rows * 4];
            c6 = &tempv2[rows * 5];
            c7 = &tempv2[rows * 6];
            c8 = &tempv2[rows * 7];
            c9 = &tempv2[rows * 8];
            c10 = &tempv2[rows * 9];
            c11 = &tempv2[rows * 10];
            c12 = &tempv2[rows * 11];
            c13 = &tempv2[rows * 12];
            c14 = &tempv2[rows * 13];
            c15 = &tempv2[rows * 14];
            c16 = &tempv2[rows * 15];

            twist_interleave_columns(
                tempv2.data(), tempu2.data(), rows, mod * 2, twist256n);

            for (int j = 0; j < rows; j++) {
                tempu2[index++] = c1[j];
                tempu2[index++] = c2[j];
                tempu2[index++] = c3[j];
                tempu2[index++] = c4[j];
                tempu2[index++] = c5[j];
                tempu2[index++] = c6[j];
                tempu2[index++] = c7[j];
                tempu2[index++] = c8[j];
                tempu2[index++] = c9[j];
                tempu2[index++] = c10[j];
                tempu2[index++] = c11[j];
                tempu2[index++] = c12[j];
                tempu2[index++] = c13[j];
                tempu2[index++] = c14[j];
                tempu2[index++] = c15[j];
                tempu2[index++] = c16[j];
            }
        } else { // frame_size == FRAME_SIZE_SHORT
            rows = frame_size / mod;

            interleave_parity_bits(tempu2.data(), in);

            c1 = &tempv2[0];
            c2 = &tempv2[rows];
            c3 = &tempv2[rows * 2];
            c4 = &tempv2[rows * 3];
            c5 = &tempv2[rows * 4];
            c6 = &tempv2[rows * 5];
            c7 = &tempv2[rows * 6];
