    // I am tempted to automate like this
    if (d_FSM.I() <= d_FSM.O())
        set_relative_rate((uint64_t)multiple, (uint64_t)d_FSM.O());
    else
        set_relative_rate((uint64_t)multiple, (uint64_t)d_FSM.I());
}

