amsg_source_impl::recv_loop()
{
    message::sptr msg;
    ::uhd::async_metadata_t* md;

    while (_running) {
        msg = message::make(0, 0.0, 0.0, sizeof(::uhd::async_metadata_t));
        md = (::uhd::async_metadata_t*)msg->msg();

        while (!_dev->get_device()->recv_async_msg(*md, 0.1)) {
            if (!_running)
                return;
        }

        post(msg);
    }
}

