{
    int sr = 0x4e46;
    for (int i = 0; i < 384; i++) {
        int b = ((sr) ^ (sr >> 1)) & 1;
        if (b == 0) {
            p1_randomize[i] = 1;
        } else {
            p1_randomize[i] = -1;
        }
        sr >>= 1;
        if (b)
            sr |= 0x4000;
    }
}

