check_lfsr_32k_s_impl::work(int noutput_items,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    const unsigned short* in = (const unsigned short*)input_items[0];

    for (int i = 0; i < noutput_items; i++) {
        unsigned short x = in[i];
        unsigned short expected;

        switch (d_state) {
        case MATCH0:
            if (x == d_buffer[0])
                enter_MATCH1();
            break;

        case MATCH1:
            if (x == d_buffer[1])
                enter_MATCH2();
            else
                enter_MATCH0();
            break;

        case MATCH2:
            if (x == d_buffer[2])
                enter_LOCKED();
            else
                enter_MATCH0();
            break;

        case LOCKED:
            expected = d_buffer[d_index];
            d_index = d_index + 1;
            if (d_index >= BUFSIZE)
                d_index = 0;

            if (x == expected)
                right();
            else {
                wrong();
                log_error(expected, x);
                if (wrong_three_times())
                    enter_SEARCHING();
            }
            break;

        default:
            abort();
        }

        d_ntotal++;
    }

    return noutput_items;
}

