make_scheduler(flat_flowgraph_sptr ffg, int max_noutput_items, bool catch_exceptions)
{
    static scheduler_maker factory = nullptr;
    gr::logger_ptr logger, debug_logger;
    gr::configure_default_loggers(logger, debug_logger, "top_block_impl");

    if (!factory) {
        char* environment_var = std::getenv("GR_SCHEDULER");
        if (!environment_var) {
            const auto& [name, fac] = scheduler_list.at(0);
            factory = fac;
            logger->debug("Using default scheduler \"{}\"", name);
        } else {
            for (auto& [name, maker] : scheduler_list) {
                if (name == environment_var) {
                    factory = maker;
                    break;
                }
            }
            if (!factory) {
                const auto& [name, fac] = scheduler_list.at(0);
                factory = fac;
                logger->warn("Invalid GR_SCHEDULER environment variable value \"{:s}\".  "
                             "Using \"{:s}\"",
                             environment_var,
                             name);
            }
        }
    }
    return factory(ffg, max_noutput_items, catch_exceptions);
}

NumberDisplayForm::saveFigure()
{
    QPixmap qpix = this->grab();

    QString types = QString(tr("JPEG file (*.jpg);;Portable Network Graphics file "
                               "(*.png);;Bitmap file (*.bmp);;TIFF file (*.tiff)"));

    QString filename, filetype;
    QFileDialog* filebox = new QFileDialog(0, "Save Image", "./", types);
    filebox->setViewMode(QFileDialog::Detail);
    filebox->setAcceptMode(QFileDialog::AcceptSave);
    filebox->setFileMode(QFileDialog::AnyFile);
    if (filebox->exec()) {
        filename = filebox->selectedFiles()[0];
        filetype = filebox->selectedNameFilter();
    } else {
        return;
    }

    if (filetype.contains(".jpg")) {
        qpix.save(filename + ".jpg", "JPEG");
    } else if (filetype.contains(".png")) {
        qpix.save(filename + ".png", "PNG");
    } else if (filetype.contains(".bmp")) {
        qpix.save(filename + ".bmp", "BMP");
    } else if (filetype.contains(".tiff")) {
        qpix.save(filename + ".tiff", "TIFF");
    } else {
        qpix.save(filename + ".jpg", "JPEG");
    }

    delete filebox;
}

