file_meta_sink_impl::update_last_header_detached()
{
    // Update the last header info with the number of samples this
    // block represents.
    size_t hdrlen = pmt::to_uint64(pmt::dict_ref(d_header, mp("strt"), pmt::PMT_NIL));
    size_t seg_size = d_itemsize * d_total_seg_size;
    pmt::pmt_t s = pmt::from_uint64(seg_size);
    update_header(mp("bytes"), s);
    update_header(mp("strt"), pmt::from_uint64(METADATA_HEADER_SIZE + d_extra_size));
    if (fseek(d_hdr_fp, -hdrlen, SEEK_CUR) == -1) {
        throw std::runtime_error("fseek() failed.");
    }
    write_header(d_hdr_fp, d_header, d_extra);
}

packet_header_default::header_parser(const unsigned char* in,
                                          std::vector<tag_t>& tags)
{
    unsigned header_len = 0;
    unsigned header_num = 0;
    tag_t tag;

    int k = 0; // Position in "in"
    for (int i = 0; i < 12 && k < d_header_len; i += d_bits_per_byte, k++) {
        header_len |= (((int)in[k]) & d_mask) << i;
    }
    tag.key = d_len_tag_key;
    tag.value = pmt::from_long(header_len);
    tags.push_back(tag);
    if (k >= d_header_len) {
        return true;
    }
    if (d_num_tag_key == pmt::PMT_NIL) {
        k += 12;
    } else {
        for (int i = 0; i < 12 && k < d_header_len; i += d_bits_per_byte, k++) {
            header_num |= (((int)in[k]) & d_mask) << i;
        }
        tag.key = d_num_tag_key;
        tag.value = pmt::from_long(header_num);
        tags.push_back(tag);
    }
    if (k >= d_header_len) {
        return true;
    }

    unsigned char buffer[] = { (unsigned char)(header_len & 0xFF),
                               (unsigned char)(header_len >> 8),
                               (unsigned char)(header_num & 0xFF),
                               (unsigned char)(header_num >> 8) };
    unsigned char crc_calcd = d_crc_impl.compute(buffer, sizeof(buffer));
    for (int i = 0; i < 8 && k < d_header_len; i += d_bits_per_byte, k++) {
        if ((((int)in[k]) & d_mask) != (((int)crc_calcd >> i) & d_mask)) {
            return false;
        }
    }

    return true;
}

