catv_reed_solomon_enc_bb_impl::reed_solomon_enc(const unsigned char* message,
                                                     unsigned char* output)
{
    // Generator polynomial from p.7 of ANSI/SCTE 07 2013
    unsigned char g[] = {
        1, gf_exp[52], gf_exp[116], gf_exp[119], gf_exp[61], gf_exp[15]
    };
    int i, j;

    memcpy(output, message, 122);
    memset(output + 122, 0, 6);

    for (i = 0; i < 122; i++) {
        for (j = 1; j < 6; j++) {
            output[i + j] ^= gf_mul_table[output[i]][g[j]];
        }
        output[i] = message[i];
    }

    output[127] = gf_poly_eval(output, 127, gf_exp[6]);
}

d_error(0)
{
    if (taps.empty())
        throw std::runtime_error("pfb_clock_sync_fff: please specify a filter.");

    // Let scheduler adjust our relative_rate.
    enable_update_rate(true);

    d_sps = floor(sps);

    // Set the damping factor for a critically damped system
    d_damping = 2 * d_nfilters;

    // Set the bandwidth, which will then call update_gains()
    set_loop_bandwidth(loop_bw);

    // Store the last filter between calls to work
    // The accumulator keeps track of overflow to increment the stride correctly.
    // set it here to the fractional difference based on the initial phaes
    d_k = init_phase;
    d_rate = (sps - floor(sps)) * (double)d_nfilters;
    d_rate_i = (int)floor(d_rate);
    d_rate_f = d_rate - (float)d_rate_i;
    d_filtnum = (int)floor(d_k);

    d_filters.reserve(d_nfilters);
    d_diff_filters.reserve(d_nfilters);

    // Create an FIR filter for each channel and zero out the taps
    std::vector<float> vtaps(1, 0);
    for (int i = 0; i < d_nfilters; i++) {
        d_filters.emplace_back(vtaps);
        d_diff_filters.emplace_back(vtaps);
    }

    // Now, actually set the filters' taps
    std::vector<float> dtaps;
    create_diff_taps(taps, dtaps);
    set_taps(taps, d_taps, d_filters);
    set_taps(dtaps, d_dtaps, d_diff_filters);

    set_relative_rate((uint64_t)d_osps, (uint64_t)d_sps);
}

