basic_block::message_port_sub(pmt::pmt_t port_id, pmt::pmt_t target)
{
    if (!pmt::dict_has_key(d_message_subscribers, port_id)) {
        std::stringstream ss;
        ss << "Port does not exist: \"" << pmt::write_string(port_id)
           << "\" on block: " << pmt::write_string(target) << std::endl;
        throw std::runtime_error(ss.str());
    }
    pmt::pmt_t currlist = pmt::dict_ref(d_message_subscribers, port_id, pmt::PMT_NIL);

    // ignore re-adds of the same target
    if (!pmt::list_has(currlist, target))
        d_message_subscribers = pmt::dict_add(
            d_message_subscribers, port_id, pmt::list_add(currlist, target));
}

def _validate_output_language_compat(self):
        """check if this block supports the selected output language"""
        current_output_language = self.parent.get_option('output_language')

        if current_output_language == 'cpp':
            if 'cpp' not in self.flags:
                self.add_error_message(
                    "This block does not support C++ output.")

            if self.key == 'parameter':
                if not self.params['type'].value:
                    self.add_error_message(
                        "C++ output requires you to choose a parameter type.")

alsa_sink::write_buffer(const void* vbuffer, unsigned nframes, unsigned sizeof_frame)
{
    const unsigned char* buffer = (const unsigned char*)vbuffer;

    while (nframes > 0) {
        int r = snd_pcm_writei(d_pcm_handle.get(), buffer, nframes);
        if (r == -EAGAIN) {
            if (d_ok_to_block == true)
                continue; // try again
            break;
        } else if (r == -EPIPE) { // underrun
            d_nunderuns++;
            // we need to have an lvalue, async pitfall!
            auto future_local = std::async(::fputs, "aU", stderr);

            if ((r = snd_pcm_prepare(d_pcm_handle.get())) < 0) {
                output_error_msg("snd_pcm_prepare failed. Can't recover from underrun",
                                 r);
                return false;
            }
            continue; // try again
        }
#ifdef ESTRPIPE
        else if (r == -ESTRPIPE) { // h/w is suspended (whatever that means)
                                   // This is apparently related to power management
            d_nsuspends++;
            if ((r = snd_pcm_resume(d_pcm_handle.get())) < 0) {
                output_error_msg("failed to resume from suspend", r);
                return false;
            }
            continue; // try again
        }
#endif
        else if (r < 0) {
            output_error_msg("snd_pcm_writei failed", r);
            return false;
        }

        nframes -= r;
        buffer += r * sizeof_frame;
    }

    return true;
}

