{
    const unsigned char* iptr = (const unsigned char*)input_items[0];
    unsigned char* optr = (unsigned char*)output_items[0];

    int size = noutput_items;

    while (size >= 8) {
        *optr++ = *iptr++ + d_k;
        *optr++ = *iptr++ + d_k;
