{
    // Slower deicison maker as we can't slice along one axis.
    // Maybe there's a better way to do this, still.

    bool a = real(*sample) > 0;
    bool b = imag(*sample) > 0;
    if (a) {
        if (b)
            return 0x0;
        else
            return 0x3;
    } else {
        if (b)
            return 0x1;
        else
            return 0x2;
    }
}

