tpc_decoder::constant_log_map(const float delta1, const float delta2)
{
    // Return maximum of delta1 and delta2
    // and in correction value if |delta1-delta2| < TVALUE
    float diff;
    diff = delta2 - delta1;

    if (diff > TVALUE)
        return (delta2);
    else if (diff < -TVALUE)
        return (delta1);
    else if (diff > 0)
        return (delta2 + CVALUE);
    else
        return (delta1 + CVALUE);
}

