bind_soapy_types(py::module& m)
{
    py::class_<gr::soapy::range_t>(m, "range_t")
        // Constructors
        .def(py::init<>())
        .def(py::init<double, double>())
        .def(py::init<double, double, double>())

        // Methods
        .def("minimum", &gr::soapy::range_t::minimum)
        .def("maximum", &gr::soapy::range_t::maximum)
        .def("step", &gr::soapy::range_t::step)

        .def("__str__", [](const gr::soapy::range_t& range) -> std::string {
            std::string ret = "(minimum: ";
            ret += std::to_string(range.minimum());
            ret += ", maximum: ";
            ret += std::to_string(range.maximum());
            ret += ", step: ";
            ret += std::to_string(range.step());
            ret += ")";

            return ret;
        });

    py::enum_<gr::soapy::argtype_t>(m, "argtype_t")
        .value("BOOL", gr::soapy::arginfo_t::BOOL)
        .value("INT", gr::soapy::arginfo_t::INT)
        .value("FLOAT", gr::soapy::arginfo_t::FLOAT)
        .value("STRING", gr::soapy::arginfo_t::STRING)
        .export_values();

    py::class_<gr::soapy::arginfo_t>(m, "arginfo_t")
        // Constructors
        .def(py::init<>())

        // Properties
        .def_readwrite("key", &gr::soapy::arginfo_t::key)
        .def_property(
            "value",
            [](const gr::soapy::arginfo_t& arginfo) -> py::object {
                return cast_string_to_arginfo_type(arginfo.type, arginfo.value);
            },
            // So we can implicitly convert to Soapy's convention
            [](gr::soapy::arginfo_t& arginfo, py::object obj) -> void {
                const auto info = cast_pyobject_to_arginfo_string(obj);

                arginfo.value = info.value;
                arginfo.type = info.type;
            })

        .def_readwrite("name", &gr::soapy::arginfo_t::name)
        .def_readwrite("description", &gr::soapy::arginfo_t::description)
        .def_readwrite("units", &gr::soapy::arginfo_t::units)
        .def_readwrite("type", &gr::soapy::arginfo_t::type)
        .def_readwrite("range", &gr::soapy::arginfo_t::range)
        .def_readwrite("options", &gr::soapy::arginfo_t::options)
        .def_readwrite("option_names", &gr::soapy::arginfo_t::optionNames)

        .def("__str__", [](const gr::soapy::arginfo_t& arginfo) -> std::string {
            return (arginfo.key + "=" + arginfo.value);
        });
}

atsc_fs_checker_impl::general_work(int noutput_items,
                                       gr_vector_int& ninput_items,
                                       gr_vector_const_void_star& input_items,
                                       gr_vector_void_star& output_items)
{
    auto in = static_cast<const float*>(input_items[0]);
    auto out = static_cast<float*>(output_items[0]);
    auto out_pl = static_cast<plinfo*>(output_items[1]);

    int output_produced = 0;

    for (int i = 0; i < noutput_items; i++) {
        // check for a hit on the PN 511 pattern
        int errors = 0;

        for (int j = 0; j < LENGTH_511 && errors < PN511_ERROR_LIMIT; j++)
            errors +=
                (in[i * ATSC_DATA_SEGMENT_LENGTH + j + OFFSET_511] >= 0) ^ atsc_pn511[j];

        this->d_debug_logger->debug("second PN63 error count = {:d}", errors);

        if (errors < PN511_ERROR_LIMIT) { // 511 pattern is good.
            // determine if this is field 1 or field 2
            errors = 0;
            for (int j = 0; j < LENGTH_2ND_63; j++)
                errors += (in[i * ATSC_DATA_SEGMENT_LENGTH + j + OFFSET_2ND_63] >= 0) ^
                          atsc_pn63[j];

            // we should have either field 1 (== PN63) or field 2 (== ~PN63)
            if (errors <= PN63_ERROR_LIMIT) {
                this->d_debug_logger->debug("Found FIELD_SYNC_1");
                d_field_num = 1;    // We are in field number 1 now
                d_segment_num = -1; // This is the first segment
            } else if (errors >= (LENGTH_2ND_63 - PN63_ERROR_LIMIT)) {
                this->d_debug_logger->debug("Found FIELD_SYNC_2");
                d_field_num = 2;    // We are in field number 2 now
                d_segment_num = -1; // This is the first segment
            } else {
                // should be extremely rare.
                this->d_logger->warn("PN63 error count = {:d}", errors);
            }
        }

        if (d_field_num == 1 || d_field_num == 2) { // If we have sync
            // So we copy out current packet data to an output packet and fill its plinfo
            memcpy(&out[output_produced * ATSC_DATA_SEGMENT_LENGTH],
                   &in[i * ATSC_DATA_SEGMENT_LENGTH],
                   ATSC_DATA_SEGMENT_LENGTH * sizeof(float));

            plinfo pli_out;
            pli_out.set_regular_seg((d_field_num == 2), d_segment_num);

            d_segment_num++;
            if (d_segment_num > (ATSC_SEGMENTS_PER_DATA_FIELD - 1)) {
                d_field_num = 0;
                d_segment_num = 0;
            } else {
                out_pl[output_produced++] = pli_out;
            }
        }
    }

    consume_each(noutput_items);
    return output_produced;
}

