ber_bf_impl::update_counters(const int items,
                                         const unsigned char* inbuffer0,
                                         const unsigned char* inbuffer1)
{
    uint32_t ret;
    for (int i = 0; i < items; i++) {
        volk_32u_popcnt(&ret, static_cast<uint32_t>(inbuffer0[i] ^ inbuffer1[i]));
        d_total_errors += ret;
    }
    d_total += items;
}

