dpll_bb_impl::work(int noutput_items,
                       gr_vector_const_void_star& input_items,
                       gr_vector_void_star& output_items)
{
    const char* iptr = (const char*)input_items[0];
    char* optr = (char*)output_items[0];

    for (int i = 0; i < noutput_items; i++) {
        optr[i] = 0;
        if (iptr[i] == 1) {
            if (d_restart == 0) {
                d_pulse_phase = 1;
            } else {
                if (d_pulse_phase > 0.5)
                    d_pulse_phase += d_gain * (1.0 - d_pulse_phase);
                else
                    d_pulse_phase -= d_gain * d_pulse_phase;
            }
            d_restart = 3;
        }
        if (d_pulse_phase > d_decision_threshold) {
            d_pulse_phase -= 1.0;
            if (d_restart > 0) {
                d_restart -= 1;
                optr[i] = 1;
            }
        }
        d_pulse_phase += d_pulse_frequency;
    }
    return noutput_items;
}

freedv_rx_ss_impl::general_work(int noutput_items,
                                    gr_vector_int& ninput_items,
                                    gr_vector_const_void_star& input_items,
                                    gr_vector_void_star& output_items)
{
    short* in = const_cast<short*>((const short*)input_items[0]);
    short* out = (short*)output_items[0];

    int in_offset = 0, out_offset = 0;

    while ((noutput_items - out_offset) >= d_max_modem_samples &&
           (ninput_items[0] - in_offset) >= d_nin) {
        d_nout = freedv_rx(d_freedv, out + out_offset, in + in_offset);
        out_offset += d_nout;
        in_offset += d_nin;
        d_nin = freedv_nin(d_freedv);
    }

    freedv_get_modem_stats(d_freedv, &d_sync, &d_snr_est);
    freedv_get_modem_extended_stats(d_freedv, &d_stats);
    d_total_bit_errors = freedv_get_total_bit_errors(d_freedv);

    consume_each(in_offset);
    return out_offset;
}

