    /* At this point, we have inserted all N elements from interleaver_indices into our
     * deinterleaver_indices, no duplicates occurred during processing of N elements, and
     * none was >= N, which implies the range is unique and consecutive from 0 to N-1.
     */
    _interleaver_indices = interleaver_indices;
    _deinterleaver_indices = std::move(deinterleaver_indices);
}

context:
pfb_decimator_ccf_impl::work_fft_exp(int noutput_items,
                                         gr_vector_const_void_star& input_items,
                                         gr_vector_void_star& output_items)
{
    const gr_complex* in;
    gr_complex* out = (gr_complex*)output_items[0];

    int i;

    // Filter each input stream by the FFT filters; do all
    // noutput_items at once to avoid repeated calls to the FFT
    // setup and operation.
    for (unsigned int j = 0; j < d_rate; j++) {
        in = (const gr_complex*)input_items[d_rate - j - 1];
        d_fft_filters[j].filter(noutput_items, in, &(d_tmp[j * noutput_items]));
    }

    // Rotate and add filter outputs (k=channel number; M=number of
    // channels; and x[j] is the output of filter j.
    //   y[i] = \sum_{j=0}{M-1} (x[j][i]*exp(2j \pi j k / M))
    for (i = 0; i < noutput_items; i++) {
        out[i] = 0;
        for (unsigned int j = 0; j < d_rate; j++) {
            out[i] += d_tmp[j * noutput_items + i] * d_rotator[j];
        }
    }

    return noutput_items;
}

