        callback_t(T* callback_, priv_lvl_t priv_, const ::std::string& desc_)
            : callback_base_t(
                  priv_, "", 0, desc_, pmt::pmt_t(), pmt::pmt_t(), pmt::pmt_t()),
              callback(callback_)
        {
