                            gr_vector_const_void_star& input_items,
                            gr_vector_void_star& output_items)
{
    const T* iptr = (const T*)input_items[0];
    T* optr = (T*)output_items[0];

    int size = noutput_items;

    while (size >= 8) {
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        *optr++ = *iptr++ & d_k;
        size -= 8;
    }

    while (size-- > 0)
        *optr++ = *iptr++ & d_k;

    return noutput_items;
}

