context:
clock_recovery_mm_cc_impl::general_work(int noutput_items,
                                            gr_vector_int& ninput_items,
                                            gr_vector_const_void_star& input_items,
                                            gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    bool write_foptr = output_items.size() >= 2;

    int ii = 0;                                          // input index
    int oo = 0;                                          // output index
    int ni = ninput_items[0] - d_interp.ntaps() - FUDGE; // don't use more input than this

    assert(d_mu >= 0.0);
    assert(d_mu <= 1.0);

    float mm_val = 0;
    gr_complex u, x, y;

    // This loop writes the error to the second output, if it exists
    if (write_foptr) {
        float* foptr = (float*)output_items[1];
        while (oo < noutput_items && ii < ni) {
            d_p_2T = d_p_1T;
            d_p_1T = d_p_0T;
            d_p_0T = d_interp.interpolate(&in[ii], d_mu);

            d_c_2T = d_c_1T;
            d_c_1T = d_c_0T;
            d_c_0T = slicer_0deg(d_p_0T);

            fast_cc_multiply(x, d_c_0T - d_c_2T, conj(d_p_1T));
            fast_cc_multiply(y, d_p_0T - d_p_2T, conj(d_c_1T));
            u = y - x;
            mm_val = u.real();
            out[oo++] = d_p_0T;

            // limit mm_val
            mm_val = gr::branchless_clip(mm_val, 1.0);
            d_omega = d_omega + d_gain_omega * mm_val;
            d_omega =
                d_omega_mid + gr::branchless_clip(d_omega - d_omega_mid, d_omega_lim);

            d_mu = d_mu + d_omega + d_gain_mu * mm_val;
            ii += (int)floor(d_mu);
            d_mu -= floor(d_mu);

            // write the error signal to the second output
            foptr[oo - 1] = mm_val;

            if (ii < 0) // clamp it.  This should only happen with bogus input
                ii = 0;
        }
    }
    // This loop does not write to the second output (ugly, but faster)
    else {
        while (oo < noutput_items && ii < ni) {
            d_p_2T = d_p_1T;
            d_p_1T = d_p_0T;
            d_p_0T = d_interp.interpolate(&in[ii], d_mu);

            d_c_2T = d_c_1T;
            d_c_1T = d_c_0T;
            d_c_0T = slicer_0deg(d_p_0T);

            fast_cc_multiply(x, d_c_0T - d_c_2T, conj(d_p_1T));
            fast_cc_multiply(y, d_p_0T - d_p_2T, conj(d_c_1T));
            u = y - x;
            mm_val = u.real();
            out[oo++] = d_p_0T;

            // limit mm_val
            mm_val = gr::branchless_clip(mm_val, 1.0);

            d_omega = d_omega + d_gain_omega * mm_val;
            d_omega =
                d_omega_mid + gr::branchless_clip(d_omega - d_omega_mid, d_omega_lim);

            d_mu = d_mu + d_omega + d_gain_mu * mm_val;
            ii += (int)floor(d_mu);
            d_mu -= floor(d_mu);

            if (d_verbose) {
                d_logger->info("{:.8f}\t{:.8f}", d_omega, d_mu);
            }

            if (ii < 0) // clamp it.  This should only happen with bogus input
                ii = 0;
        }
    }

    if (ii > 0) {
        assert(ii <= ninput_items[0]);
        consume_each(ii);
    }

    return oo;
}

dvbt2_framemapper_cc_impl::l1post_ldpc_lookup_generate(void)
{
    int im;
    int index;
    int pbits;
    int q;
    index = 0;
    im = 0;

    pbits = FRAME_SIZE_SHORT - NBCH_1_2; // number of parity bits
    q = 25;

    for (int row = 0; row < 20; row++) {
        for (int n = 0; n < 360; n++) {
            for (int col = 1; col <= ldpc_tab_1_2S[row][0]; col++) {
                l1post_ldpc_encode.p[index] = (ldpc_tab_1_2S[row][col] + (n * q)) % pbits;
                l1post_ldpc_encode.d[index] = im;
                index++;
            }
            im++;
        }
    }
    l1post_ldpc_encode.table_length = index;
}

