eye_sink_f_impl::_test_trigger_tags(int nitems)
{
    int trigger_index;

    uint64_t nr = nitems_read(d_trigger_channel);
    std::vector<gr::tag_t> tags;
    get_tags_in_range(tags, d_trigger_channel, nr, nr + nitems + 1, d_trigger_tag_key);
    if (!tags.empty()) {
        trigger_index = tags[0].offset - nr;
        int start = d_index + trigger_index - d_trigger_delay - 1;
        if (start >= 0) {
            d_triggered = true;
            d_start = start;
            d_end = d_start + d_size;
            d_trigger_count = 0;
            _adjust_tags(-d_start);
        }
    }
}

dvbs2_physical_cc_impl::pl_header_encode(unsigned char modcod,
                                              unsigned char type,
                                              int* out)
{
    unsigned char code;

    if (modcod & 0x80) {
        code = modcod | (type & 0x1);
    } else {
        code = (modcod << 2) | type;
    }
    // Add the modcod and type information and scramble it
    b_64_8_code(code, out);
}

ted_generalized_msk::compute_error_ff()
{
    float u;

    u = (d_input[1].real() * d_input[1].real() * d_input[5].real() * d_input[5].real()) -
        (d_input[3].real() * d_input[3].real() * d_input[7].real() * d_input[7].real());

    return gr::branchless_clip(u, 3.0f);
}

