dvbt2_framemapper_cc_impl::l1pre_ldpc_lookup_generate(void)
{
    int im;
    int index;
    int pbits;
    int q;
    index = 0;
    im = 0;

    pbits = FRAME_SIZE_SHORT - NBCH_1_4; // number of parity bits
    q = 36;

    for (int row = 0; row < 9; row++) {
        for (int n = 0; n < 360; n++) {
            for (int col = 1; col <= ldpc_tab_1_4S[row][0]; col++) {
                l1pre_ldpc_encode.p[index] = (ldpc_tab_1_4S[row][col] + (n * q)) % pbits;
                l1pre_ldpc_encode.d[index] = im;
                index++;
            }
            im++;
        }
    }
    l1pre_ldpc_encode.table_length = index;
}

correlate_access_code_tag_ff_impl::set_access_code(const std::string& access_code)
{
    gr::thread::scoped_lock l(d_mutex_access_code);

    d_len = access_code.length(); // # of bytes in string
    if (d_len > 64)
        return false;

    // set len bottom bits to 1.
    d_mask = ((~0ULL) >> (64 - d_len));

    d_access_code = 0;
    for (unsigned i = 0; i < d_len; i++) {
        d_access_code = (d_access_code << 1) | (access_code[i] & 1);
    }

    d_logger->debug("Access code: {:x}", d_access_code);
    d_logger->debug("Mask: {:x}", d_mask);

    return true;
}

