QRfnocF15Surface::drawWaterfall()
{
    float x[2], y[2];
    float e = 0.5f / d_fft_bins;
    float v[2];

    /* Draw Waterfall texture */
    d_cmap->enable(d_palette, d_wf.tex);

    x[0] = d_layout.x[1];
    x[1] = d_layout.x[2];
    y[0] = d_layout.y[1];
    y[1] = d_layout.y[2];

    v[0] = (float)(d_wf.pos) / (float)(d_wf_lines);
    v[1] = v[0] + 1.0f;

    glBegin(GL_QUADS);
    glTexCoord2d(0.0f + e, v[0]);
    glVertex2d(x[0], y[0]);
    glTexCoord2d(1.0f + e, v[0]);
    glVertex2d(x[1], y[0]);
    glTexCoord2d(1.0f + e, v[1]);
    glVertex2d(x[1], y[1]);
    glTexCoord2d(0.0f + e, v[1]);
    glVertex2d(x[0], y[1]);
    glEnd();

    d_cmap->disable();
}

