pmt_pool::free(void* foo)
{
    if (!foo)
        return;

    scoped_lock guard(d_mutex);

    item* p = (item*)foo;
    p->d_next = d_freelist;
    d_freelist = p;
    d_n_items--;
    if (d_max_items != 0)
        d_cond.notify_one();
}

