work(int noutput_items,
                                 gr_vector_const_void_star& input_items,
                                 gr_vector_void_star& output_items)
{
    if (d_updated) {
        d_length = d_new_length;
        d_scale = d_new_scale;
        std::fill(std::begin(d_scales), std::end(d_scales), d_scale);
        this->set_history(d_length);
        d_updated = false;
        return 0; // history requirements might have changed
    }

    const T* in = static_cast<const T*>(input_items[0]);
    T* out = static_cast<T*>(output_items[0]);

    const unsigned int num_iter = std::min(noutput_items, d_max_iter);
    if (d_vlen == 1) {
        T sum = std::accumulate(&in[0], &in[d_length - 1], T{});

        for (unsigned int i = 0; i < num_iter; i++) {
            sum += in[i + d_length - 1];
            out[i] = sum * d_scale;
            sum -= in[i];
        }

    } else { // d_vlen > 1
        // gets automatically optimized well
        std::copy(&in[0], &in[d_vlen], std::begin(d_sum));

        for (int i = 1; i < d_length - 1; i++) {
            volk_add(d_sum.data(), &in[i * d_vlen], d_vlen);
        }

        for (unsigned int i = 0; i < num_iter; i++) {
            volk_add(d_sum.data(), &in[(i + d_length - 1) * d_vlen], d_vlen);
            volk_mul(&out[i * d_vlen], d_sum.data(), d_scales.data(), d_vlen);
            volk_sub(d_sum.data(), &in[i * d_vlen], d_vlen);
        }
    }
    return num_iter;
}

rfnoc_block::_msg_handler_command(pmt::pmt_t msg)
{
    // pmt_dict is a subclass of pmt_pair. Make sure we use pmt_pair!
    if (!pmt::is_dict(msg) && pmt::is_pair(msg)) {
        d_logger->debug(
            "Command message is pair, converting to dict: '{}': car({}), cdr({})",
            msg,
            pmt::car(msg),
            pmt::cdr(msg));
        msg = pmt::dict_add(pmt::make_dict(), pmt::car(msg), pmt::cdr(msg));
    }

    // Make sure, we use dicts!
    if (!pmt::is_dict(msg)) {
        d_logger->error("Command message is neither dict nor pair: {}",
                        pmt::write_string(msg));
        return;
    }

    /*** Start the actual message processing *************************/
    /// 1) Read chan value
    int chan = int(pmt::to_long(pmt::dict_ref(msg,
                                              cmd_chan_key(),
                                              pmt::from_long(-1) // Default to all chans
                                              )));

    /// 2) Loop through all the values
    d_debug_logger->debug("Processing command message {}", pmt::write_string(msg));
    pmt::pmt_t msg_items = pmt::dict_items(msg);
    for (size_t i = 0; i < pmt::length(msg_items); i++) {
        try {
            _dispatch_msg_cmd_handler(pmt::write_string(pmt::car(pmt::nth(i, msg_items))),
                                      pmt::cdr(pmt::nth(i, msg_items)),
                                      chan,
                                      msg);
        } catch (const pmt::wrong_type& e) {
            d_logger->alert("Invalid command value for key {}: {}",
                            pmt::car(pmt::nth(i, msg_items)),
                            pmt::cdr(pmt::nth(i, msg_items)));
            break;
        }
    }
}

