xoroshiro128p_jump(uint64_t* state)
{
    static const uint64_t JUMP[] = { 0xbeac0467eba5facb, 0xd86b048b86aa9922 };

    uint64_t s0 = 0;
    uint64_t s1 = 0;
    for (unsigned int i = 0; i < sizeof(JUMP) / sizeof(*JUMP); ++i) {
        for (unsigned int b = 0; b < 64; ++b) {
            if (JUMP[i] & UINT64_C(1) << b) {
                s0 ^= state[0];
                s1 ^= state[1];
            }
            xoroshiro128p_next(state);
        }
    }

    state[0] = s0;
    state[1] = s1;
}

time_raster_sink_b_impl::set_multiplier(const std::vector<float>& mult)
{
    if (mult.empty()) {
        for (int i = 0; i < d_nconnections + 1; i++) {
            d_mult[i] = 1.0f;
        }
    } else if (mult.size() == (size_t)d_nconnections) {
        for (int i = 0; i < d_nconnections; i++) {
            d_mult[i] = mult[i];
        }
    } else if (mult.size() == (size_t)d_nconnections + 1) {
        for (int i = 0; i < d_nconnections + 1; i++) {
            d_mult[i] = mult[i];
        }
    } else {
        throw std::runtime_error(
            "time_raster_sink_b_impl::set_multiplier incorrect dimensions.");
    }
}

