context:
permutation_impl::work(int noutput_items,
                           gr_vector_const_void_star& input_items,
                           gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock guard(d_setlock);
    int nstreams = input_items.size();

    for (int m = 0; m < nstreams; m++) {
        const char* in = (const char*)input_items[m];
        char* out = (char*)output_items[m];

        // per stream processing
        for (int i = 0; i < noutput_items / d_SYMS_PER_BLOCK; i++) {
            // Index i refers to blocks.
            // Beginning of packet (in blocks)
            int i0 = d_K * (i / d_K);
            // position of block within packet (in blocks)
            int j0 = i % d_K;
            // new position of block within packet (in blocks)
            int k0 = d_TABLE[j0];
            memcpy(&(out[i * d_SYMS_PER_BLOCK * d_BYTES_PER_SYMBOL]),
                   &(in[(i0 + k0) * d_SYMS_PER_BLOCK * d_BYTES_PER_SYMBOL]),
                   d_BYTES_PER_SYMBOL * d_SYMS_PER_BLOCK);
        }
        // end per stream processing
    }
    return noutput_items;
}

dvbt_energy_descramble_impl::general_work(int noutput_items,
                                              gr_vector_int& ninput_items,
                                              gr_vector_const_void_star& input_items,
                                              gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];

    int to_consume, to_out;

    // Search for a NSYNC
    while ((in[d_index] != d_NSYNC) && (d_index < d_search)) {
        d_index += d_bsize;
    }

    /*
     * If we did not find a NSYNC then just consume
     * and return 0.
     */
    if (d_index >= d_search) {
        d_index = 0;
        to_consume = 2;
        to_out = 0;
    } else {
        // We found a NSYNC, descramble the data

        to_consume = (noutput_items / (d_nblocks * d_bsize)) - 2;
        to_out = noutput_items - 2 * (d_nblocks * d_bsize);

        for (int count = 0, i = 0; i < to_consume; i++) {
            init_prbs();

            for (int mux_pkt = 0; mux_pkt < d_MUX_PKT; mux_pkt++) {
                out[count++] = d_SYNC;
                // PRBS clocking starts right after NSYNC

                for (int k = 1; k < d_bsize; k++) {
                    out[count] = in[d_index + count] ^ clock_prbs(d_nblocks);
                    count++;
                }

                // For subsequent blocks PRBS is clocked also on SYNC
                // but its output is not used
                clock_prbs(d_nblocks);
            }
        }
    }

    // Tell runtime how many input items we consumed
    consume_each(to_consume);

    // Tell runtime system how many output items we produced.
    return (to_out);
}

