buffer_double_mapped::space_available()
{
    if (d_readers.empty())
        return d_bufsize - 1; // See comment below

    else {

        // Find out the maximum amount of data available to our readers
        int most_data = d_readers[0]->items_available();
        uint64_t min_items_read = d_readers[0]->nitems_read();
        for (size_t i = 1; i < d_readers.size(); i++) {
            most_data = std::max(most_data, d_readers[i]->items_available());
            min_items_read = std::min(min_items_read, d_readers[i]->nitems_read());
        }

        if (min_items_read != d_last_min_items_read) {
            prune_tags(d_last_min_items_read);
            d_last_min_items_read = min_items_read;
        }

#ifdef BUFFER_DEBUG
        d_logger->debug(
            "[{}] space_available() called d_write_index: {} -- space_available: {}",
            this,
            d_write_index,
            d_bufsize - most_data - 1);
#endif

        // The -1 ensures that the case d_write_index == d_read_index is
        // unambiguous.  It indicates that there is no data for the reader
        return d_bufsize - most_data - 1;
    }
}

linear_equalizer_impl::work(int noutput_items,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    {
        gr::thread::scoped_lock guard(d_mutex);
        if (d_updated) {
            d_taps = d_new_taps;
            set_history(d_taps.size());
            d_updated = false;
            return 0; // history requirements may have changed.
        }
    }

    unsigned long int nread = nitems_read(0);
    std::vector<tag_t> tags;
    get_tags_in_window(tags, 0, 0, noutput_items * decimation(), d_training_start_tag);
    std::vector<unsigned int> training_start_samples(tags.size());
    unsigned int tag_index = 0;
    for (const auto& tag : tags) {
        training_start_samples[tag_index++] = tag.offset - nread;
    }

    auto in = static_cast<const gr_complex*>(input_items[0]);
    auto out = static_cast<gr_complex*>(output_items[0]);

    int outlen = output_items.size();
    unsigned short* state = nullptr;
    gr_complex* taps = nullptr;

    if (outlen > 1)
        taps = static_cast<gr_complex*>(output_items[1]);
    if (outlen > 2)
        state = static_cast<unsigned short*>(output_items[2]);

    return equalize(in,
                    out,
                    noutput_items * decimation(),
                    noutput_items,
                    training_start_samples,
                    true,
                    taps,
                    state);
}

atsc_field_sync_mux_impl::init_field_sync_common(
    unsigned char* p, int mask, const unsigned char saved_symbols[N_SAVED_SYMBOLS])
{
    static const unsigned char bin_map[2] = { 1,
                                              6 }; // map binary values to 1 of 8 levels

    int i = 0;

    p[i++] = bin_map[1]; // data segment sync pulse
    p[i++] = bin_map[0];
    p[i++] = bin_map[0];
    p[i++] = bin_map[1];

    for (int j = 0; j < 511; j++) { // PN511
        p[i++] = bin_map[atsc_pn511[j]];
    }

    for (int j = 0; j < 63; j++) { // PN63
        p[i++] = bin_map[atsc_pn63[j]];
    }

    for (int j = 0; j < 63; j++) { // PN63, toggled on field 2
        p[i++] = bin_map[atsc_pn63[j] ^ mask];
    }

    for (int j = 0; j < 63; j++) { // PN63
        p[i++] = bin_map[atsc_pn63[j]];
    }

    p[i++] = bin_map[0]; // 24 bits of 8VSB mode identifier
    p[i++] = bin_map[0];
    p[i++] = bin_map[0];
    p[i++] = bin_map[0];

    p[i++] = bin_map[1];
    p[i++] = bin_map[0];
    p[i++] = bin_map[1];
    p[i++] = bin_map[0];

    p[i++] = bin_map[0];
    p[i++] = bin_map[1];
    p[i++] = bin_map[0];
    p[i++] = bin_map[1];

    p[i++] = bin_map[1];
    p[i++] = bin_map[1];
    p[i++] = bin_map[1];
    p[i++] = bin_map[1];

    p[i++] = bin_map[0];
    p[i++] = bin_map[1];
    p[i++] = bin_map[0];
    p[i++] = bin_map[1];

    p[i++] = bin_map[1];
    p[i++] = bin_map[0];
    p[i++] = bin_map[1];
    p[i++] = bin_map[0];

    for (int j = 0; j < 92; j++) { // 92 more bits
        p[i++] = bin_map[atsc_pn63[j % 63]];
    }

    // now copy the last 12 symbols of the previous segment

    for (int j = 0; j < N_SAVED_SYMBOLS; j++) {
        p[i++] = saved_symbols[j];
    }

    assert(i == ATSC_DATA_SEGMENT_LENGTH);
}

