freq_axis_render(struct freq_axis* fx, char* str, int step)
{
    /* Special case: count mode */
    if (step && (fx->mode == FX_MODE_COUNT)) {
        sprintf(str, "%+d", step);
        return;
    }

    /* Special case: no center frequency */
    if (!step && (fx->center == 0.0)) {
        sprintf(str, "0");
        return;
    }

    /* Relative case */
    if (step && (fx->mode == FX_MODE_RELATIVE)) {
        sprintf(str, fx->rel_fmt, step * fx->rel_step);
        return;
    }

    /* Normal full absolute frequency */
    sprintf(str, fx->abs_fmt, (fx->center + step * fx->step) * fx->abs_scale);
}

cc_encoder_impl::generic_work(const void* in_buffer, void* out_buffer)
{
    const unsigned char* in = (const unsigned char*)in_buffer;
    unsigned char* out = (unsigned char*)out_buffer;

    unsigned int my_state = d_start_state;

    if (d_mode == CC_TAILBITING) {
        for (unsigned int i = 0; i < d_k - 1; ++i) {
            my_state = (my_state << 1) | (in[d_frame_size - (d_k - 1) + i] & 1);
        }
    }

    for (unsigned int i = 0; i < d_frame_size; ++i) {
        my_state = (my_state << 1) | (in[i] & 1);
        for (unsigned int j = 0; j < d_rate; ++j) {
            out[i * d_rate + j] =
                (d_polys[j] < 0) ^ parity(my_state & abs(d_polys[j])) ? 1 : 0;
        }
    }

    if (d_mode == CC_TERMINATED) {
        for (unsigned int i = 0; i < d_k - 1; ++i) {
            my_state = (my_state << 1) | ((d_start_state >> (d_k - 2 - i)) & 1);
            for (unsigned int j = 0; j < d_rate; ++j) {
                out[(i + d_frame_size) * d_rate + j] =
                    (d_polys[j] < 0) ^ parity(my_state & abs(d_polys[j])) ? 1 : 0;
            }
        }
    }

    if (d_mode == CC_TRUNCATED) {
        my_state = d_start_state;
    }

    d_start_state = my_state;
}

