HistogramDisplayPlot::plotNewData(const std::vector<const double*> dataPoints,
                                       const uint64_t numDataPoints,
                                       const double timeInterval)
{
    if (!d_stop) {
        if ((numDataPoints > 0)) {

            // keep track of the min/max values for when autoscaleX is called.
            d_xmin = 1e20;
            d_xmax = -1e20;
            for (unsigned int n = 0; n < d_nplots; ++n) {
                d_xmin = std::min(
                    d_xmin,
                    *std::min_element(dataPoints[n], dataPoints[n] + numDataPoints));
                d_xmax = std::max(
                    d_xmax,
                    *std::max_element(dataPoints[n], dataPoints[n] + numDataPoints));
            }

            // If autoscalex has been clicked, clear the data for the new
            // bin widths and reset the x-axis.
            if (d_autoscalex_state) {
                clear();
                _resetXAxisPoints(d_xmin, d_xmax);
                d_autoscalex_state = false;
            }

            if (!d_accum) {
                clear();
            }

            unsigned int index;
            for (unsigned int n = 0; n < d_nplots; ++n) {
                for (uint64_t point = 0; point < numDataPoints; point++) {
                    index =
                        std::lround(1e-20 + (dataPoints[n][point] - d_left) / d_width);
                    if (index < d_bins)
                        d_ydata[n][static_cast<unsigned int>(index)] += 1;
                }
            }

            auto height = std::numeric_limits<double>::lowest();
            for (const auto& dy : d_ydata) {
                height =
                    std::max(height, *std::max_element(std::begin(dy), std::end(dy)));
            }

            if (d_autoscale_state)
                _autoScaleY(0, height);

            replot();
        }
    }
}

message_debug_impl::log(const pmt::pmt_t& msg)
{
    if (pmt::is_pdu(msg)) {
        const auto& meta = pmt::car(msg);
        const auto& vector = pmt::cdr(msg);
        auto length = pmt::blob_length(vector);
        auto begin = reinterpret_cast<const uint8_t*>(pmt::blob_data(vector));
        auto output_length = length;
        if (!d_en_uvec)
            output_length = std::min<decltype(length)>(output_length, 16);
        auto datastring = fmt::format("{:X}{}",
                                      fmt::join(begin, begin + output_length, " "),
                                      output_length < length ? " …" : "");
        d_logger->log(d_level,
                      "PDU {:s}: {:10d} B [{}] ",
                      pmt::write_string(meta),
                      length,
                      datastring);
        return;
    }
    d_logger->log(d_level, "Message: {}", pmt::write_string(msg));
}

