crc::reflect(uint64_t word) const
{
    uint64_t ret;
    ret = word & 1;
    for (unsigned i = 1; i < d_num_bits; ++i) {
        word >>= 1;
        ret = (ret << 1) | (word & 1);
    }
    return ret;
}

