            else:
                curve.setData(self.freq[:int(npts // 2)],
                              self.fftdB[:int(npts // 2)])

        # Set axes to new scales.

        # Set plot limits and reset axis zoom.
        if self.iir:
            xmax = self.freq[npts - 1]
        else:
            xmax = self.freq[npts // 2]

