packet_headerparser_b_impl::work(int noutput_items,
                                     gr_vector_const_void_star& input_items,
                                     gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];

    if (noutput_items < d_header_formatter->header_len()) {
        return 0;
    }

    std::vector<tag_t> tags;
    get_tags_in_range(
        tags, 0, nitems_read(0), nitems_read(0) + d_header_formatter->header_len());

    if (!d_header_formatter->header_parser(in, tags)) {
        d_logger->info("Detected an invalid packet at item {:d}", nitems_read(0));
        message_port_pub(d_port, pmt::PMT_F);
    } else {
        pmt::pmt_t dict(pmt::make_dict());
        for (unsigned i = 0; i < tags.size(); i++) {
            dict = pmt::dict_add(dict, tags[i].key, tags[i].value);
        }
        message_port_pub(d_port, dict);
    }

    return d_header_formatter->header_len();
}

fmdet_cf_impl::work(int noutput_items,
                        gr_vector_const_void_star& input_items,
                        gr_vector_void_star& output_items)
{
    const gr_complex* iptr = (const gr_complex*)input_items[0];
    float* optr = (float*)output_items[0];

    int size = noutput_items;

    gr_complex Sdot, S0;
    gr_complex S1 = d_S1, S2 = d_S2, S3 = d_S3, S4 = d_S4;

    while (size-- > 0) {
        S0 = *iptr++;

        Sdot = d_scl * (-S0 + 8.f * S1 - 8.f * S3 + S4);

        d_freq = (S2.real() * Sdot.imag() - S2.imag() * Sdot.real()) /
                 (S2.real() * S2.real() + S2.imag() * S2.imag());

        S4 = S3;
        S3 = S2;
        S2 = S1;
        S1 = S0;

        *optr++ = d_freq - d_bias;
    }
    d_S1 = S1;
    d_S2 = S2;
    d_S3 = S3;
    d_S4 = S4;
    return noutput_items;
}

