constellation::get_closest_point(const gr_complex* sample)
{
    float min_euclid_dist = get_distance(0, sample);
    unsigned int min_index = 0;
    for (unsigned int j = 1; j < d_arity; j++) {
        float euclid_dist = get_distance(j, sample);
        if (euclid_dist < min_euclid_dist) {
            min_euclid_dist = euclid_dist;
            min_index = j;
        }
    }
    return min_index;
}

wvps_ff_impl::work(int noutput_items,
                       gr_vector_const_void_star& input_items,
                       gr_vector_void_star& output_items)
{
    const float* in = (const float*)input_items[0];
    float* out = (float*)output_items[0];

    for (int count = 0; count < noutput_items; count++) {

        // any power?

        if (in[0] == 0.0) {
            for (int i = 0; i < d_olen; i++)
                out[i] = 0.0;

        } else {

            // get power normalization from 0-th wavelet coefficient

            float scl = 1.0 / (in[0] * in[0]);
            int k = 1;

            // sum powers over sequences of bins,
            // sequence lengths in increasing powers of 2

            for (int e = 0; e < d_olen; e++) {
                int m = 01 << e;
                float sum = 0.0;

                for (int l = 0; l < m; l++)
                    sum += (in[k + l] * in[k + l]);

                out[e] = scl * sum;
                k += m;
            }
        }

        in += d_ilen;
        out += d_olen;
    }

    return noutput_items;
}

