context:
dvbs2_interleaver_bb_impl::general_work(int noutput_items,
                                            gr_vector_int& ninput_items,
                                            gr_vector_const_void_star& input_items,
                                            gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int consumed = 0;
    int produced = 0;
    int rows;

    switch (signal_constellation) {
    case MOD_BPSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size;
            for (int j = 0; j < rows; j++) {
                out[produced++] = in[consumed++];
            }
        }
        break;
    case MOD_BPSK_SF2:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size;
            for (int j = 0; j < rows; j++) {
                out[produced++] = in[consumed];
                out[produced++] = in[consumed++];
            }
        }
        break;
    case MOD_QPSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 2;
            for (int j = 0; j < rows; j++) {
                out[produced] = in[consumed++] << 1;
                out[produced++] |= in[consumed++];
            }
        }
        break;
    case MOD_8PSK:
    case MOD_8APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 3;
            const unsigned char *c1, *c2, *c3;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            for (int j = 0; j < rows; j++) {
                out[produced++] = (c1[j] << 2) | (c2[j] << 1) | (c3[j]);
                consumed += 3;
            }
        }
        break;
    case MOD_16APSK:
    case MOD_8_8APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 4;
            const unsigned char *c1, *c2, *c3, *c4;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            c4 = &in[consumed + rowaddr3];
            for (int j = 0; j < rows; j++) {
                out[produced++] = (c1[j] << 3) | (c2[j] << 2) | (c3[j] << 1) | (c4[j]);
                consumed += 4;
            }
        }
        break;
    case MOD_32APSK:
    case MOD_4_12_16APSK:
    case MOD_4_8_4_16APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 5;
            const unsigned char *c1, *c2, *c3, *c4, *c5;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            c4 = &in[consumed + rowaddr3];
            c5 = &in[consumed + rowaddr4];
            for (int j = 0; j < rows; j++) {
                out[produced++] =
                    (c1[j] << 4) | (c2[j] << 3) | (c3[j] << 2) | (c4[j] << 1) | c5[j];
                consumed += 5;
            }
        }
        break;
    case MOD_64APSK:
    case MOD_8_16_20_20APSK:
    case MOD_4_12_20_28APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 6;
            const unsigned char *c1, *c2, *c3, *c4, *c5, *c6;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            c4 = &in[consumed + rowaddr3];
            c5 = &in[consumed + rowaddr4];
            c6 = &in[consumed + rowaddr5];
            for (int j = 0; j < rows; j++) {
                out[produced++] = (c1[j] << 5) | (c2[j] << 4) | (c3[j] << 3) |
                                  (c4[j] << 2) | (c5[j] << 1) | c6[j];
                consumed += 6;
            }
        }
        break;
    case MOD_128APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = (frame_size + 6) / 7;
            const unsigned char *c1, *c2, *c3, *c4, *c5, *c6, *c7;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            c4 = &in[consumed + rowaddr3];
            c5 = &in[consumed + rowaddr4];
            c6 = &in[consumed + rowaddr5];
            c7 = &in[consumed + rowaddr6];
            for (int j = 0; j < rows; j++) {
                out[produced++] = (c1[j] << 6) | (c2[j] << 5) | (c3[j] << 4) |
                                  (c4[j] << 3) | (c5[j] << 2) | (c6[j] << 1) | c7[j];
                consumed += 7;
            }
            for (int j = 0; j < 12; j++) {
                out[produced++] = 0x7f;
            }
        }
        break;
    case MOD_256APSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 8;
            const unsigned char *c1, *c2, *c3, *c4, *c5, *c6, *c7, *c8;
            c1 = &in[consumed + rowaddr0];
            c2 = &in[consumed + rowaddr1];
            c3 = &in[consumed + rowaddr2];
            c4 = &in[consumed + rowaddr3];
            c5 = &in[consumed + rowaddr4];
            c6 = &in[consumed + rowaddr5];
            c7 = &in[consumed + rowaddr6];
            c8 = &in[consumed + rowaddr7];
            for (int j = 0; j < rows; j++) {
                out[produced++] = (c1[j] << 7) | (c2[j] << 6) | (c3[j] << 5) |
                                  (c4[j] << 4) | (c5[j] << 3) | (c6[j] << 2) |
                                  (c7[j] << 1) | c8[j];
                consumed += 8;
            }
        }
        break;
    default:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 2;
            for (int j = 0; j < rows; j++) {
                out[produced] = in[consumed++] << 1;
                out[produced++] |= in[consumed++];
            }
        }
        break;
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    consume_each(consumed);

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

cc_decoder_impl::set_frame_size(unsigned int frame_size)
{
    bool ret = true;
    if (frame_size > d_max_frame_size) {
        d_logger->info("cc_decoder: tried to set frame to {:d}; max possible is {:d}",
                       frame_size,
                       d_max_frame_size);
        frame_size = d_max_frame_size;
        ret = false;
    }

    d_frame_size = frame_size;

    switch (d_mode) {
    case (CC_TAILBITING):
        d_veclen = d_frame_size + (6 * (s_k - 1));
        if (d_veclen * s_rate > d_managed_in.size()) {
            throw std::runtime_error(
                "cc_decoder: attempt to resize beyond d_managed_in buffer size!");
        }
        break;

    case (CC_TRUNCATED):
        d_veclen = d_frame_size;
        break;

    case (CC_STREAMING):
        d_veclen = d_frame_size + s_k - 1;
        break;

    case (CC_TERMINATED):
        // If the input is being padded out to a byte, we know the
        // real frame size is without the padding.
        d_frame_size -= d_padding * s_rate;
        d_veclen = d_frame_size + s_k - 1;
        break;

    default:
        throw std::runtime_error("cc_decoder: mode not recognized");
    }

    return ret;
}

