    int counter = 0;

    gr::buffer_sptr buf(gr::buffer_double_mapped::make_buffer(
        nitems, sizeof(int), nitems, 1, gr::block_sptr()));

    int last_sa;
    int sa;

    sa = buf->space_available();
    BOOST_CHECK(sa > 0);
    last_sa = sa;

    for (int i = 0; i < 5; i++) {
        sa = buf->space_available();
        BOOST_CHECK_EQUAL(last_sa, sa);
        last_sa = sa;

        int* p = (int*)buf->write_pointer();
        BOOST_CHECK(p != 0);

        for (int j = 0; j < sa; j++)
            *p++ = counter++;

        buf->update_write_pointer(sa);
    }
}

