phase_detector(gr_complex sample, float ref_phase)
    {
        float sample_phase;
        //  sample_phase = atan2(sample.imag(),sample.real());
        sample_phase = gr::fast_atan2f(sample.imag(), sample.real());
        return mod_2pi(sample_phase - ref_phase);
