context:
conv_bit_corr_bb_impl::general_work(int noutput_items,
                                        gr_vector_int& ninput_items,
                                        gr_vector_const_void_star& input_items,
                                        gr_vector_void_star& output_items)
{
    if (d_flush_count > 0) {
        int items = (ninput_items[0] > static_cast<int>(d_flush_count)) ? d_flush_count
                                                                        : ninput_items[0];
        consume_each(items);
        d_flush_count -= items;
        return 0;
    }

    const uint8_t* in = (const uint8_t*)input_items[0];
    const uint8_t* score_in = (const uint8_t*)input_items[0];

    // counting on  1:1 forecast + history to provide enough ninput_items... may need to
    // insert check printf("%d, %d, %d", ninput_items[0], noutput_items, d_counter);
    int correlation_cycles =
        (noutput_items / output_multiple() <= static_cast<int>(d_counter))
            ? noutput_items / output_multiple()
            : d_counter;


    for (int p = 0; p < correlation_cycles; ++p) {
        // reset scores
        for (unsigned int j = 0; j < d_correlator.size(); ++j) {
            for (unsigned int i = 0; i < d_corr_sym; ++i) {
                d_score_keeper[j][i] = 0;
            }
        }

        // correlate against each correlation constant
        for (unsigned int j = 0; j < d_correlator.size(); ++j) {
            for (unsigned int k = 0; k < d_corr_sym; ++k) {
                for (unsigned int i = 0; i < d_correlator[j].size(); ++i) {
                    d_score_keeper[j][k] +=
                        (score_in[d_correlator[j][i] + k] >= 128) ? 1 : 0;
                }
            }

            for (unsigned int k = 0; k < d_corr_sym; ++k) {
                d_acc[j * (d_corr_sym) + k] += d_score_keeper[j][k] % 2;
            }
        }
        score_in += d_corr_sym;
    }

    // decrement the cut counter

    d_counter -= correlation_cycles;

    // d_counter == 0: check the accumulator and update states
    if (d_counter == 0) {
        d_message = 1;
        d_produce = 0;
        float my_min = 1.0;
        for (unsigned int i = 0; (i < d_correlator.size()) && (!d_produce); ++i) {
            for (unsigned int k = 0; k < d_corr_sym; ++k) {

                my_min = (d_acc[i * (d_corr_sym) + k] / (float)d_cut < my_min)
                             ? d_acc[i * (d_corr_sym) + k] / (float)d_cut
                             : my_min;

                if (d_acc[i * (d_corr_sym) + k] < d_thresh) {
                    d_produce = 1;
                    d_message = 0;
                    d_acquire = k;
                    d_lane = i + 1;
                    d_op = 1;
                    // printf("winner: lane %u, punc_cycle %u, pos/neg corr %d", i, k,
                    // d_op);
                    break;
                } else if (d_acc[i * (d_corr_sym) + k] > (d_cut - d_thresh)) {
                    d_acquire = k;
                    d_lane = i + 1;
                    d_op = -1;
                    // printf("winner: lane %u, punc_cycle %u, pos/neg corr %d", i, k,
                    // d_op);
                    break;
                }
            }
            d_data_garble_rate = 100.0 * data_garble_rate(d_correlator[i].size(), my_min);
            d_havelock = d_data_garble_rate < 3;
        }

        // clear the accumulator, reset the counter
        d_counter = d_cut;
        for (unsigned int i = 0; i < d_correlator.size(); ++i) {
            for (unsigned int k = 0; k < d_corr_sym; ++k) {
                d_acc[i * (d_corr_sym) + k] = 0;
            }
        }

        // examine the new states and react to environment, make a final production
        // decision
        if (d_message) {
            d_msgsent++;
            // stub code
            d_message = 0;
        }
    }
    // states are set

    if (d_produce) {
        // printf("producing");
        unsigned char* out = (unsigned char*)output_items[0];
        memcpy(out,
               &(in[d_acquire]),
               correlation_cycles * d_corr_sym * sizeof(unsigned char));

        consume_each(d_corr_sym * correlation_cycles);
        return d_corr_sym * correlation_cycles;
    }

    else {
        consume_each(d_corr_sym * correlation_cycles);
        return 0;
    }
}

