windows_sink::open_waveout_device(void)
{
    UINT u_device_id;
    unsigned long result;

    /** Identifier of the waveform-audio output device to open. It
      can be either a device identifier or a handle of an open
      waveform-audio input device. You can use the following flag
      instead of a device identifier.
      WAVE_MAPPER The function selects a waveform-audio output
      device capable of playing the given format.
    */
    if (d_device_name.empty() || default_device_name() == d_device_name)
        u_device_id = WAVE_MAPPER;
    else
        // The below could be uncommented to allow selection of different device handles
        // however it is unclear what other devices are out there and how a user
        // would know the device ID so at the moment we will ignore that setting
        // and stick with WAVE_MAPPER
        u_device_id = find_device(d_device_name);
    if (verbose)
        d_debug_logger->info("waveOut Device ID: {:d}", u_device_id);

    // Check if the sampling rate/bits/channels are good to go with the device.
    MMRESULT supported = is_format_supported(&wave_format, u_device_id);
    if (supported != MMSYSERR_NOERROR) {
        char err_msg[50];
        waveOutGetErrorText(supported, err_msg, 50);
        d_debug_logger->info("format error: {:s}", err_msg);
        d_logger->error("Requested audio format is not supported by device {:s} driver",
                        strerror(errno));
        return -1;
    }

    // Open a waveform device for output using event callback.
    result = waveOutOpen(&d_h_waveout,
                         u_device_id,
                         &wave_format,
                         (DWORD_PTR)d_wave_write_event,
                         0,
                         CALLBACK_EVENT | WAVE_ALLOWSYNC);

    if (result) {
        d_logger->error("Failed to open waveform output device. {:s}", strerror(errno));
        return -1;
    }

    return 0;
}

udp_sink_impl::work(int noutput_items,
                        gr_vector_const_void_star& input_items,
                        gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock guard(d_setlock);

    long num_bytes_to_transmit = noutput_items * d_block_size;
    const char* in = (const char*)input_items[0];

    // Discard bytes if the input is longer than the buffer
    long overrun = num_bytes_to_transmit - d_localqueue_writer->bufsize();
    if (overrun > 0) {
        num_bytes_to_transmit -= overrun;
        in += overrun;
    }

    // Build a long local queue to pull from so we can break it up easier
    if (d_localqueue_writer->space_available() < num_bytes_to_transmit)
        d_localqueue_reader->update_read_pointer(num_bytes_to_transmit -
                                                 d_localqueue_writer->space_available());
    memcpy(d_localqueue_writer->write_pointer(), in, num_bytes_to_transmit);
    d_localqueue_writer->update_write_pointer(num_bytes_to_transmit);

    // Local buffer for transmitting
    std::vector<asio::const_buffer> transmitbuffer;

    // Let's see how many blocks are in the buffer
    int bytes_available = d_localqueue_reader->items_available();
    long blocks_available = bytes_available / d_precomp_datasize;

    for (int cur_block = 0; cur_block < blocks_available; cur_block++) {
        // Clear the next transmit buffer
        transmitbuffer.clear();

        // build our next header if we need it
        if (d_header_type != HEADERTYPE_NONE) {
            build_header();

            transmitbuffer.push_back(
                asio::buffer((const void*)d_tmpheaderbuff, d_header_size));
        }

        // Set up for transmit
        transmitbuffer.push_back(
            asio::buffer(d_localqueue_reader->read_pointer(), d_precomp_datasize));

        // Send
        d_udpsocket->send_to(transmitbuffer, d_endpoint);

        d_localqueue_reader->update_read_pointer(d_precomp_datasize);
    }

    int itemsreturned = blocks_available * d_precomp_data_overitemsize;

    return itemsreturned;
}

