context:
header_format_default::parse(int nbits_in,
                                  const unsigned char* input,
                                  std::vector<pmt::pmt_t>& info,
                                  int& nbits_processed)
{
    nbits_processed = 0;

    while (nbits_processed < nbits_in) {
        switch (d_state) {
        case STATE_SYNC_SEARCH: // Look for the access code correlation
            while (nbits_processed < nbits_in) {
                // shift in new data
                d_data_reg = (d_data_reg << 1) | ((input[nbits_processed++]) & 0x1);

                // compute hamming distance between desired access code and current data
                uint64_t wrong_bits = 0;
                uint64_t nwrong = d_threshold + 1;

                wrong_bits = (d_data_reg ^ d_access_code) & d_mask;
                volk_64u_popcnt(&nwrong, wrong_bits);

                if (nwrong <= d_threshold) {
                    enter_have_sync();
                    break;
                }
            }
            break;

        case STATE_HAVE_SYNC:
            while (nbits_processed <= nbits_in) { // Shift bits one at a time into header
                d_hdr_reg.insert_bit(input[nbits_processed++]);
                if (d_hdr_reg.length() == (header_nbits() - d_access_code_len)) {

                    // we have a full header, check to see if it has been received
                    // properly
                    if (header_ok()) {
                        int payload_len = header_payload();
                        enter_have_header(payload_len);
                        info.push_back(d_info);
                        return true;
                    } else {
                        enter_search(); // bad header
                        return false;
                    }
                    break;
                }
            }
            break;
        }
    }

    return false;
}

correlate_access_code_tag_ff_impl::set_access_code(const std::string& access_code)
{
    gr::thread::scoped_lock l(d_mutex_access_code);

    d_len = access_code.length(); // # of bytes in string
    if (d_len > 64)
        return false;

    // set len bottom bits to 1.
    d_mask = ((~0ULL) >> (64 - d_len));

    d_access_code = 0;
    for (unsigned i = 0; i < d_len; i++) {
        d_access_code = (d_access_code << 1) | (access_code[i] & 1);
    }

    d_logger->debug("Access code: {:x}", d_access_code);
    d_logger->debug("Mask: {:x}", d_mask);

    return true;
}

