device_source_impl::work(int noutput_items,
                             gr_vector_const_void_star& input_items,
                             gr_vector_void_star& output_items)
{
    ssize_t ret;

    // Check if we've processed what we have first
    if (!items_in_buffer) {
        ret = iio_buffer_refill(buf);
        if (ret < 0) {
            /* -EBADF happens when the buffer is cancelled */
            if (ret != -EBADF) {

                char buf[256];
                iio_strerror(-ret, buf, sizeof(buf));
                d_logger->warn("Unable to refill buffer: {:s}", buf);
            }
            return -1;
        }

        items_in_buffer = (unsigned long)ret / iio_buffer_step(buf);
        if (!items_in_buffer)
            return 0;

        byte_offset = 0;

        // Tag start of new packet
        if (d_len_tag_key != pmt::PMT_NIL) {
            size_t toutputs;
            if (override_tagged_output_channels > 0)
                toutputs = override_tagged_output_channels;
            else
                toutputs = output_items.size();

            for (size_t i = 0; i < toutputs; i += 1) {
                this->add_item_tag(i,
                                   this->nitems_written(0),
                                   this->d_len_tag_key,
                                   pmt::from_long(items_in_buffer));
            }
        }
    }

    // Process samples
    unsigned long items = std::min(items_in_buffer, (unsigned long)noutput_items);

    for (size_t i = 0; i < output_items.size(); i++)
        channel_read(channel_list[i], output_items[i], items * sizeof(short));

    items_in_buffer -= items;
    byte_offset += items * iio_buffer_step(buf);

    return (int)items;
}

firdes::sanity_check_2f(double sampling_freq,
                             double fa, // first cutoff freq
                             double fb, // second cutoff freq
                             double transition_width)
{
    if (sampling_freq <= 0.0)
        throw std::out_of_range("firdes check failed: sampling_freq > 0");

    if (fa <= 0.0 || fa > sampling_freq / 2)
        throw std::out_of_range("firdes check failed: 0 < fa <= sampling_freq / 2");

    if (fb <= 0.0 || fb > sampling_freq / 2)
        throw std::out_of_range("firdes check failed: 0 < fb <= sampling_freq / 2");

    if (fa > fb)
        throw std::out_of_range("firdes check failed: fa <= fb");

    if (transition_width <= 0)
        throw std::out_of_range("firdes check failed: transition_width > 0");
}

