dvb_bbheader_bb_impl::add_crc8_bits(unsigned char* in, int length)
{
    int crc = 0;
    int b;
    int i = 0;

    for (int n = 0; n < length; n++) {
        b = in[i++] ^ (crc & 0x01);
        crc >>= 1;
        if (b) {
            crc ^= CRC_POLY;
        }
    }

    if (input_mode == INPUTMODE_HIEFF) {
        crc ^= 0x80;
    }

    for (int n = 0; n < 8; n++) {
        in[i++] = (crc & (1 << n)) ? 1 : 0;
    }
    return 8; // Length of CRC
}

