base_source_impl::load_message(bool wait)
{
    /* Poll for input */
    zmq::pollitem_t items[] = { { static_cast<void*>(d_socket), 0, ZMQ_POLLIN, 0 } };
    zmq::poll(&items[0], 1, std::chrono::milliseconds{ wait ? d_timeout : 0 });

    if (!(items[0].revents & ZMQ_POLLIN))
        return false;

        /* Is this the start or continuation of a multi-part message? */
#if USE_NEW_CPPZMQ_SET_GET
    auto more = d_socket.get(zmq::sockopt::rcvmore);
#else
    int64_t more = 0;
    size_t more_len = sizeof(more);
    d_socket.getsockopt(ZMQ_RCVMORE, &more, &more_len);
#endif

    /* Reset */
    d_msg.rebuild();
    d_tags.clear();
    d_consumed_items = 0;
    d_consumed_bytes = 0;

    /* Get the message */
#if USE_NEW_CPPZMQ_SEND_RECV
    const bool ok = bool(d_socket.recv(d_msg));
#else
    const bool ok = d_socket.recv(&d_msg);
#endif
    if (!ok) {
        // This shouldn't happen since we polled POLLIN, but ZMQ wants us to check
        // the return value.
        d_logger->warn("Failed to recv() message.");
        return false;
    }

    /* Throw away key and get the first message. Avoid blocking if a multi-part
     * message is not sent */
    if (!d_key.empty() && !more) {
#if USE_NEW_CPPZMQ_SET_GET
        auto is_multipart = d_socket.get(zmq::sockopt::rcvmore);
#else
        int64_t is_multipart;
        d_socket.getsockopt(ZMQ_RCVMORE, &is_multipart, &more_len);
#endif

        d_msg.rebuild();
        if (is_multipart) {
#if USE_NEW_CPPZMQ_SEND_RECV
            const bool multi_ok = bool(d_socket.recv(d_msg));
#else
            const bool multi_ok = d_socket.recv(&d_msg);
#endif
            if (!multi_ok) {
                d_logger->error("Failure to receive multi-part message.");
            }
        } else {
            return false;
        }
    }
    /* Parse header from the first (or only) message of a multi-part message */
    if (d_pass_tags && !more) {
        uint64_t rcv_offset;

        /* Parse header */
        d_consumed_bytes = parse_tag_header(d_msg, rcv_offset, d_tags);

        /* Fixup the tags offset to be relative to the start of this message */
        for (unsigned int i = 0; i < d_tags.size(); i++) {
            d_tags[i].offset -= rcv_offset;
        }
    }

    /* Each message must contain an integer multiple of data vectors */
    if ((d_msg.size() - d_consumed_bytes) % d_vsize != 0) {
        throw std::runtime_error("Incompatible vector sizes: need a multiple of " +
                                 std::to_string(d_vsize) + " bytes per message");
    }

    /* We got one ! */
    return true;
}

def _update_docs_page(self):
        """Show documentation from XML and try to display best matching docstring"""
        buf = self._docs_text_display.get_buffer()
        buf.delete(buf.get_start_iter(), buf.get_end_iter())
        pos = buf.get_end_iter()

        in_tree = self._block.category and self._block.category[0] == "Core"

        # Add link to wiki page for this block, at the top, as long as it's not an OOT block
        if self._block.is_connection:
            self._docs_link.set_markup('Connection')
        elif in_tree:
            # For in-tree modules, use prefix as configured
            prefix = self._config.wiki_block_docs_url_prefix
        else:
            prefix = ""

        suffix = None
        if self._block.doc_url:
            suffix = self._block.doc_url
        elif in_tree:
            suffix = self._block.label.replace(" ", "_")

        if suffix:
            url = urljoin(prefix, suffix)
            icon = "🗗 "
            if urlparse(url).scheme not in ("", "file"):
                icon += "🌐"
            self._docs_link.set_markup(f'<a href="{url}">{icon} Visit Documentation Page</a>')
        elif self._block.is_connection:
            self._docs_link.set_markup('Connection Properties')
        else:
            self._docs_link.set_markup('Out of Tree Block, No documentation URL specified')

        docstrings = self._block.documentation.copy()
        if not docstrings:
            return

        # show documentation string from block yaml
        from_yaml = docstrings.pop('', '')
        for line in from_yaml.splitlines():
            if line.lstrip() == line and line.endswith(':'):
                buf.insert_with_tags_by_name(pos, line + '\n', 'b')
            else:
                buf.insert(pos, line + '\n')
        if from_yaml:
            buf.insert(pos, '\n')

        # if given the current parameters an exact match can be made
        block_templates = getattr(self._block, 'templates', None)
        if block_templates:
            block_constructor = block_templates.render(
                'make').rsplit('.', 2)[-1]
            block_class = block_constructor.partition('(')[0].strip()
            if block_class in docstrings:
                docstrings = {block_class: docstrings[block_class]}

        # show docstring(s) extracted from python sources
        for cls_name, docstring in docstrings.items():
            buf.insert_with_tags_by_name(pos, cls_name + '\n', 'b')
            buf.insert(pos, docstring + '\n\n')
        pos.backward_chars(2)
        buf.delete(pos, buf.get_end_iter())

format(const gr::io_signature& iosig,
                                         fmt::format_context& ctx) const
{
    auto min_streams = iosig.min_streams();
    auto max_streams = iosig.max_streams();
    const auto itemsizes = iosig.sizeof_stream_items();

    const auto stream_range = (max_streams == gr::io_signature::IO_INFINITE)
                                  ? fmt::format("{} – {}", min_streams, max_streams)
                                  : fmt::format("{} – ∞", min_streams);

    const auto sizes = (itemsizes.size() < static_cast<size_t>(max_streams))
                           ? fmt::format("{}, …", fmt::join(itemsizes, ", "))
                           : fmt::format("{}", fmt::join(itemsizes, ", "));

    return fmt::format_to(ctx.out(),
                          "Stream Range: {:>20s}\n"
                          "Item Sizes:   {:>20s}\n"
                          "Buffer Types: {:>20s}",
                          (max_streams == gr::io_signature::IO_INFINITE)
                              ? fmt::format("{} – {}", min_streams, max_streams)
                              : fmt::format("{} – ∞", min_streams),
                          (itemsizes.size() < static_cast<size_t>(max_streams))
                              ? fmt::format("{}, …", fmt::join(itemsizes, ", "))
                              : fmt::format("{}", fmt::join(itemsizes, ", ")),
                          // TODO: Implement printing of buffer types
                          "printing not implemented");
}

