dvbt_reference_signals_impl::general_work(int noutput_items,
                                              gr_vector_int& ninput_items,
                                              gr_vector_const_void_star& input_items,
                                              gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];
    gr_complex* dst;

    for (int i = 0; i < noutput_items; i++) {
        d_pg.update_output(&in[i * d_ninput], &out[i * d_noutput]);
        dst = ofdm_fft.get_inbuf();
        memcpy(&dst[ofdm_fft_size / 2],
               &out[i * d_noutput],
               sizeof(gr_complex) * ofdm_fft_size / 2);
        memcpy(&dst[0],
               &out[(i * d_noutput) + (ofdm_fft_size / 2)],
               sizeof(gr_complex) * ofdm_fft_size / 2);
        ofdm_fft.execute();
        volk_32f_s32f_multiply_32f(reinterpret_cast<float*>(&out[i * d_noutput]),
                                   reinterpret_cast<float*>(ofdm_fft.get_outbuf()),
                                   normalization,
                                   ofdm_fft_size * 2);
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    consume_each(noutput_items);

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

