                           const unsigned char* bytes,
                           int nbytes) const
{
    int n = 0;
    for (int i = 0; i < nbytes; i++) {
        unsigned int t = bytes[i];
        for (int j = d_k - 1; j >= 0; j--)
            bits[n++] = (t >> j) & 0x01;
    }
}

