            d_logger->info("Full seconds {:d}, Frac seconds {:g}, abs sample offset {:d}",
                           pmt::to_uint64(pmt::tuple_ref(value, 0)),
                           pmt::to_double(pmt::tuple_ref(value, 1)),
                           offset);
        }

        return ninput_items;
    }
}

