time_delta_impl::update_stats(double x)
{
    // uses Welford's Method to calculate the running variance
    double prev_mean = d_mean;
    d_n++;
    d_mean = d_mean + (x - d_mean) / d_n;
    d_var_acc += (x - d_mean) * (x - prev_mean);
    d_var = d_var_acc / (d_n - 1);
}

