{
    unsigned char tmp[K];

    assert((int)(amount_of_pad + sizeof(in.data)) == K);

    // add missing prefix zero padding to message
    memset(tmp, 0, amount_of_pad);
    memcpy(&tmp[amount_of_pad], in.data, sizeof(in.data));

