WaterfallDisplayForm::newData(const QEvent* updateEvent)
{
    const WaterfallUpdateEvent* event = (const WaterfallUpdateEvent*)updateEvent;
    const std::vector<const double*> dataPoints = event->getPoints();
    const uint64_t numDataPoints = event->getNumDataPoints();
    const gr::high_res_timer_type dataTimestamp = event->getDataTimestamp();

    for (size_t i = 0; i < dataPoints.size(); i++) {
        const double* min_val =
            std::min_element(&dataPoints[i][0], &dataPoints[i][numDataPoints - 1]);
        const double* max_val =
            std::max_element(&dataPoints[i][0], &dataPoints[i][numDataPoints - 1]);
        if (*min_val < d_min_val)
            d_min_val = *min_val;
        if (*max_val > d_max_val)
            d_max_val = *max_val;
    }

    getPlot()->plotNewData(dataPoints, numDataPoints, d_time_per_fft, dataTimestamp, 0);
}

pfb_clock_sync_ccf_impl::general_work(int noutput_items,
                                          gr_vector_int& ninput_items,
                                          gr_vector_const_void_star& input_items,
                                          gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    if (d_updated) {
        std::vector<float> dtaps;
        create_diff_taps(d_updated_taps, dtaps);
        set_taps(d_updated_taps, d_taps, d_filters);
        set_taps(dtaps, d_dtaps, d_diff_filters);
        d_updated = false;
        return 0; // history requirements may have changed.
    }

    float *err = NULL, *outrate = NULL, *outk = NULL;
    if (output_items.size() == 4) {
        err = (float*)output_items[1];
        outrate = (float*)output_items[2];
        outk = (float*)output_items[3];
    }

    std::vector<tag_t> tags;
    get_tags_in_window(tags, 0, 0, d_sps * noutput_items, pmt::intern("time_est"));

    int i = 0, count = 0;
    float error_r, error_i;

    // produce output as long as we can and there are enough input samples
    while (i < noutput_items) {
        if (!tags.empty()) {
            size_t offset = tags[0].offset - nitems_read(0);
            if ((offset >= (size_t)count) && (offset < (size_t)(count + d_sps))) {
                float center = (float)pmt::to_double(tags[0].value);
                d_k = d_nfilters * (center + (offset - count));

                tags.erase(tags.begin());
            }
        }

        for (int out_idx = 0; out_idx < d_osps; out_idx++) {
            d_filtnum = (int)floor(d_k);

            // Keep the current filter number in [0, d_nfilters]
            // If we've run beyond the last filter, wrap around and go to next sample
            // If we've gone below 0, wrap around and go to previous sample
            while (d_filtnum >= d_nfilters) {
                d_k -= d_nfilters;
                d_filtnum -= d_nfilters;
                count += 1;
            }
            while (d_filtnum < 0) {
                d_k += d_nfilters;
                d_filtnum += d_nfilters;
                count -= 1;
            }

            out[i + out_idx] = d_filters[d_filtnum].filter(&in[count + out_idx]);
            d_k = d_k + d_rate_i + d_rate_f; // update phase


            // Manage Tags
            std::vector<tag_t> xtags;
            d_new_in = nitems_read(0) + count + out_idx + d_sps;
            get_tags_in_range(xtags, 0, d_old_in, d_new_in);
            for (const auto& tag : xtags) {
                tag_t new_tag = tag;
                // new_tag.offset = d_last_out + d_taps_per_filter/(2*d_sps) - 2;
                new_tag.offset = d_last_out + d_taps_per_filter / 4 - 2;
                add_item_tag(0, new_tag);
            }
            d_old_in = d_new_in;
            d_last_out = nitems_written(0) + i + out_idx;

            if (output_items.size() == 4) {
                err[i] = d_error;
                outrate[i] = d_rate_f;
                outk[i] = d_k;
            }
        }

        // Update the phase and rate estimates for this symbol
        gr_complex diff = d_diff_filters[d_filtnum].filter(&in[count]);
        error_r = out[i].real() * diff.real();
        error_i = out[i].imag() * diff.imag();
        d_error = (error_i + error_r) / 2.0; // average error from I&Q channel

        // Run the control loop to update the current phase (k) and
        // tracking rate estimates based on the error value
        // Interpolating here to update rates for ever sps.
        for (int s = 0; s < d_sps; s++) {
            d_rate_f = d_rate_f + d_beta * d_error;
            d_k = d_k + d_rate_f + d_alpha * d_error;
        }

        // Keep our rate within a good range
        d_rate_f = gr::branchless_clip(d_rate_f, d_max_dev);

        i += d_osps;
        count += (int)floor(d_sps);
    }

    consume_each(count);
    return i;
}

