fftshift_and_sum(double* outFFT,
                             const float* inFFT,
                             uint64_t num_points,
                             double& sum_mean,
                             double& peak_ampl,
                             int& peak_bin)
{
    const float* inptr = inFFT + num_points / 2;
    double* outptr = outFFT;

    sum_mean = 0;
    peak_ampl = -HUGE_VAL;
    peak_bin = 0;

    // Run this twice to perform the fftshift operation on the data here as well
    for (uint64_t point = 0; point < num_points / 2; point++) {
        float pt = (*inptr);
        *outptr = pt;
        if (*outptr > peak_ampl) {
            peak_bin = point;
            peak_ampl = *outptr;
        }
        sum_mean += *outptr;

        inptr++;
        outptr++;
    }

    // This loop takes the first half of the input data and puts it in the
    // second half of the plotted data
    inptr = inFFT;
    for (uint64_t point = 0; point < num_points / 2; point++) {
        float pt = (*inptr);
        *outptr = pt;
        if (*outptr > peak_ampl) {
            peak_bin = point;
            peak_ampl = *outptr;
        }
        sum_mean += *outptr;

        inptr++;
        outptr++;
    }
}

