viterbi_butterfly8(unsigned char* symbols,
                        int mettab[2][256],
                        struct viterbi_state* state0,
                        struct viterbi_state* state1)
{
    unsigned int bitcnt;
    int mets[4];

    struct viterbi_state *state, *next;
    state = state0;
    next = state1;
    // Operate on 16 symbols (8 bits) at a time
    for (bitcnt = 0; bitcnt < 8; bitcnt++) {
        // Read input symbol pair and compute all possible branch metrics
        mets[0] = mettab[0][symbols[0]] + mettab[0][symbols[1]];
        mets[1] = mettab[0][symbols[0]] + mettab[1][symbols[1]];
        mets[2] = mettab[1][symbols[0]] + mettab[0][symbols[1]];
        mets[3] = mettab[1][symbols[0]] + mettab[1][symbols[1]];
        symbols += 2;

        // These macro calls were generated by genbut.c
        BUTTERFLY(0, 0);
        BUTTERFLY(1, 1);
        BUTTERFLY(2, 3);
        BUTTERFLY(3, 2);
        BUTTERFLY(4, 3);
        BUTTERFLY(5, 2);
        BUTTERFLY(6, 0);
        BUTTERFLY(7, 1);
        BUTTERFLY(8, 0);
        BUTTERFLY(9, 1);
        BUTTERFLY(10, 3);
        BUTTERFLY(11, 2);
        BUTTERFLY(12, 3);
        BUTTERFLY(13, 2);
        BUTTERFLY(14, 0);
        BUTTERFLY(15, 1);
        BUTTERFLY(16, 2);
        BUTTERFLY(17, 3);
        BUTTERFLY(18, 1);
        BUTTERFLY(19, 0);
        BUTTERFLY(20, 1);
        BUTTERFLY(21, 0);
        BUTTERFLY(22, 2);
        BUTTERFLY(23, 3);
        BUTTERFLY(24, 2);
        BUTTERFLY(25, 3);
        BUTTERFLY(26, 1);
        BUTTERFLY(27, 0);
        BUTTERFLY(28, 1);
        BUTTERFLY(29, 0);
        BUTTERFLY(30, 2);
        BUTTERFLY(31, 3);

        // Swap current and next states
        if (bitcnt & 1) {
            state = state0;
            next = state1;
        } else {
            state = state1;
            next = state0;
        }
    }
}

def disable_file(self, fname):
        """ Comment out a file.
        Example:
        add_library(
            file1.cc
        )

        Here, file1.cc becomes #file1.cc with disable_file('file1.cc').
        """
        starts_line = False
        for line in self.cfile.splitlines():
            if len(line.strip()) == 0 or line.strip()[0] == '#':
                continue
            if re.search(r'\b' + fname + r'\b', line):
                if re.match(fname, line.lstrip()):
                    starts_line = True
                break
        comment_out_re = r'#\1' + '\n' + self.indent
        if not starts_line:
            comment_out_re = r'\n' + self.indent + comment_out_re
        (self.cfile, nsubs) = re.subn(
            r'(\b' + fname + r'\b)\s*', comment_out_re, self.cfile)
        if nsubs == 0:
            logger.warning(
                "Warning: A replacement failed when commenting out {}. Check the CMakeFile.txt manually.".format(fname))
        elif nsubs > 1:
            logger.warning(
                "Warning: Replaced {} {} times (instead of once). Check the CMakeFile.txt manually.".format(fname, nsubs))

