freq_axis_build(struct freq_axis* fx, double center, double span, int n_div)
{
    /* Basic info */
    fx->center = center;
    fx->span = span;
    fx->step = span / n_div;

    /* Select mode of operation */
    if (span == 0.0) {
        fx->mode = FX_MODE_COUNT;
    } else if (center == 0.0) {
        fx->mode = FX_MODE_RELATIVE;
    } else if (floor(log10f(fx->step)) < (floor(log10f(fx->center)) - 4)) {
        fx->mode = FX_MODE_RELATIVE;
    } else {
        fx->mode = FX_MODE_ABSOLUTE;
    }

    /* Select display format for absolute frequencies */
    if (center != 0.0) {
        double min_freq, max_freq, big_freq;
        char prefix[2] = { 0, 0 };
        int exp, x, y, z;

        max_freq = fx->center + (span / 2.0);
        min_freq = fx->center - (span / 2.0);

        big_freq = (fabs(max_freq) > fabs(min_freq)) ? fabs(max_freq) : fabs(min_freq);

        _si_scaling(big_freq, 4, prefix, &exp);

        if (prefix[0] == ' ')
            prefix[0] = '\0';

        fx->abs_scale = 1.0 / powf(10.0, exp);

        x = (int)floor(log10f(big_freq)) - exp + 1;
        y = _num_decimals(fx->center * fx->abs_scale);
        z = _num_decimals(fx->step * fx->abs_scale);

        if (z > y)
            y = z;

        if (x + y > 6)
            y = 6 - x;

        sprintf(fx->abs_fmt, "%%.%dlf%s", y, prefix);
    }

    /* Select display format for relative mode */
    if (fx->mode == FX_MODE_RELATIVE) {
        double max_dev = fx->step * 5;
        char prefix[2] = { 0, 0 };
        int exp, x, y;

        _si_scaling(max_dev, 3, prefix, &exp);

        if (prefix[0] == ' ')
            prefix[0] = '\0';

        fx->rel_step = fx->step / powf(10.0, exp);

        x = (int)floor(log10f(max_dev)) - exp + 1;
        y = _num_decimals(fx->rel_step);

        if (x + y > 4)
            y = 4 - x;

        sprintf(fx->rel_fmt, "%%+.%dlf%s", y, prefix);
    }
}

work(int noutput_items,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    T* out = (T*)output_items[0];

    uint32_t produced = 0;
    int data_remaining = d_data.size();

    // if there are no data in the queue, see if more PDUs are ready
    if (data_remaining == 0) {
        if (d_pdu_queue.empty()) {
            // if we have nothing to do, sleep for a short duration to prevent rapid
            // successive calls and then return zero items
            std::this_thread::sleep_for(std::chrono::microseconds(25));
            return 0;
        }

        // fetch another PDU of data and update the size of the data
        data_remaining = queue_data();
        if (data_remaining == 0) {
            std::this_thread::sleep_for(std::chrono::microseconds(25));
            return 0;
        }
    } /* end if data_remaining == 0 */

    // data_remaining is not zero so go ahead and update
    if (d_tag_sob) {
        this->add_item_tag(
            0, this->nitems_written(0), metadata_keys::tx_sob(), pmt::PMT_T);
        d_tag_sob = false;

        // if there is a time tag waiting, use it then reset the time tag
        if (!pmt::eqv(d_time_tag, pmt::PMT_NIL)) {
            this->add_item_tag(
                0, this->nitems_written(0), metadata_keys::tx_time(), d_time_tag);
            d_time_tag = pmt::PMT_NIL;
        }
    }

    // if everything remaining will fit, send it and tag EOB
    if (data_remaining <= noutput_items) {
        memcpy(out, &d_data[0], d_itemsize * data_remaining);
        // tag last item "tx_eob, True"
        this->add_item_tag(0,
                           this->nitems_written(0) + data_remaining - 1,
                           metadata_keys::tx_eob(),
                           pmt::PMT_T);
        d_data.clear();
        produced = data_remaining;

        // not everything will fit... send first noutput_items from PDU
    } else {
        if (noutput_items) {
            memcpy(out, &d_data[0], d_itemsize * noutput_items);
            d_data.erase(d_data.begin(), d_data.begin() + noutput_items);
            produced = noutput_items;
        }
    }

    // Tell runtime system how many output items we produced.
    return produced;
}

