    for (int i = 0; i < noutput_items; i += miso_items) {
        memcpy(out1, in, sizeof(gr_complex) * miso_items);
        out1 += miso_items;
        for (int j = 0; j < miso_items; j += 2) {
            temp1 = std::conj(*in++);
            temp2 = std::conj(*in++);
            *out2++ = -temp2;
            *out2++ = temp1;
        }
    }

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

