{
    unsigned char c2 = 0x7F, c1 = 0x7F, c0 = 0x7F;
    unsigned char c2_new, c1_new, c0_new;
    int n, i;

    for (n = 0; n < max_offset; n++) {
        rseq[n] = c2;
        c2_new = c1;
        c1_new = c0 ^ c2;
        c0_new = c2;
        for (i = 0; i < 3; i++) {
            c0_new <<= 1;
            if (c0_new & 0x80) {
                c0_new = (c0_new & 0x7F) ^ 0x09;
            }
        }
        c2 = c2_new;
        c1 = c1_new;
        c0 = c0_new;
    }
}

