block_interleaving::set_interleaver_indices(
    const std::vector<size_t>& interleaver_indices)
{
    if (interleaver_indices.empty()) {
        throw std::invalid_argument("Incorrect interleaver indices! Can't be empty.");
    }

    std::vector<size_t> deinterleaver_indices(interleaver_indices.size(), 0);
    bool zero_seen = false;
    for (size_t counter = 0; counter < interleaver_indices.size(); ++counter) {
        const auto index = interleaver_indices[counter];

        // check bounds
        if (index >= interleaver_indices.size()) {
            throw std::invalid_argument(fmt::format(
                "Incorrect interleaver indices! Expected {0} unique elements in the "
                "range[0, {0}) in random order, but element {1} >= {0}!",
                interleaver_indices.size(),
                index));
        }

        // check for duplicate zero
        if (index == 0) {
            if (zero_seen) {
                throw std::invalid_argument(fmt::format(
                    "Incorrect interleaver indices! Expected {0} unique elements in the "
                    "range[0, {0}) in random order, but element {1} appears twice, at "
                    "positions {2} and {3}!",
                    interleaver_indices.size(),
                    index,
                    deinterleaver_indices[index],
                    counter));
            }
            zero_seen = true;
            deinterleaver_indices[0] = counter;
        }

        // put into deinterleaver, check duplicity while doing that
        else if (deinterleaver_indices[index] == 0) { // not yet used
            deinterleaver_indices[index] = counter;
        } else {
            throw std::invalid_argument(fmt::format(
                "Incorrect interleaver indices! Expected {0} unique elements in the "
                "range[0, {0}) in random order, but element {1} appears twice, at "
                "positions {2} and {3}!",
                interleaver_indices.size(),
                index,
                deinterleaver_indices[index],
                counter));
        }
    }

    /* At this point, we have inserted all N elements from interleaver_indices into our
     * deinterleaver_indices, no duplicates occurred during processing of N elements, and
     * none was >= N, which implies the range is unique and consecutive from 0 to N-1.
     */
    _interleaver_indices = interleaver_indices;
    _deinterleaver_indices = std::move(deinterleaver_indices);
}

b_send_eof(send_eof)
{
    // Lets set up the max payload size for the UDP packet based on the requested
    // payload size. Some important notes:  For a standard IP/UDP packet, say
    // crossing the Internet with a standard MTU, 1472 is the max UDP payload
    // size.  Larger values can be sent, however the IP stack will fragment the
    // packet.  This can cause additional network overhead as the packet gets
    // reassembled. Now for local nets that support jumbo frames, the max payload
    // size is 8972 (9000-the UDP 28-byte header) Same rules apply with
    // fragmentation.

    switch (d_header_type) {
    case HEADERTYPE_SEQNUM:
        d_header_size = sizeof(header_seq_num);
        break;

    case HEADERTYPE_SEQPLUSSIZE:
        d_header_size = sizeof(header_seq_plus_size);
        break;

    case HEADERTYPE_NONE:
        d_header_size = 0;
        break;

    default:
        d_logger->error("Unknown header type.");
        throw std::invalid_argument("Unknown UDP header type.");
        break;
    }

    if (d_payloadsize < 8) {
        d_logger->error("Payload size is too small.  Must be at "
                        "least 8 bytes once header/trailer adjustments are made.");
        throw std::invalid_argument(
            "Payload size is too small.  Must be at "
            "least 8 bytes once header/trailer adjustments are made.");
    }

    d_block_size = d_itemsize * d_veclen;

    d_precomp_datasize = d_payloadsize - d_header_size;
    d_precomp_data_overitemsize = d_precomp_datasize / d_itemsize;

    int out_multiple = (d_payloadsize - d_header_size) / d_block_size;

    if (out_multiple == 1)
        out_multiple = 2; // Ensure we get pairs, for instance complex -> ichar pairs

    gr::block::set_output_multiple(out_multiple);
}

