random::reseed(uint64_t seed)
{
    d_seed = seed;
    if (d_seed == 0) {
        auto now = std::chrono::system_clock::now().time_since_epoch();
        auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();
        d_rng.seed(ns);
    } else {
        d_rng.seed(d_seed);
    }
}

