dec2bases(unsigned int num, const std::vector<int>& bases, std::vector<int>& s)
{
    int l = s.size();
    unsigned int n = num;
    for (int i = 0; i < l; i++) {
        s[l - i - 1] = n % bases[l - i - 1];
        n /= bases[l - i - 1];
    }
    if (n != 0) {
        printf("Number %d requires more than %d digits.", num, l);
        return false;
    } else
        return true;
}

