        d_out_r = floor(rounder * abs(d_goertzel_r->output())) / rounder;

        // printf("d_out_l=%f d_out_c=%f d_out_r=%f\n", d_out_l, d_out_c, d_out_r);
        d_mute = (d_out_c < d_level || d_out_c < d_out_l || d_out_c < d_out_r);
    }
}

