header_payload_demux_impl::check_buffers_ready(int output_symbols_reqd,
                                                    int extra_output_items_reqd,
                                                    int noutput_items,
                                                    int input_items_reqd,
                                                    gr_vector_int& ninput_items,
                                                    int n_items_read)
{
    // Check there's enough space on the output buffer
    if (d_output_symbols) {
        if (noutput_items < output_symbols_reqd + extra_output_items_reqd) {
            return false;
        }
    } else {
        if (noutput_items <
            (output_symbols_reqd * d_items_per_symbol) + extra_output_items_reqd) {
            return false;
        }
    }

    // Check there's enough items on the input
    if (input_items_reqd > (ninput_items[0] - n_items_read) ||
        (ninput_items.size() == 2 &&
         (input_items_reqd > (ninput_items[1] - n_items_read)))) {
        return false;
    }

    // All good
    return true;
}

pfb_synthesizer_ccf_impl::set_channel_map(const std::vector<int>& map)
{
    gr::thread::scoped_lock guard(d_mutex);

    if (!map.empty()) {
        int max = *std::max_element(map.begin(), map.end());
        int min = *std::min_element(map.begin(), map.end());
        if ((max >= static_cast<int>(d_twox * d_numchans)) || (min < 0)) {
            throw std::invalid_argument(
                "pfb_synthesizer_ccf_impl::set_channel_map: map range out of bounds.");
        }
        d_channel_map = map;

        // Zero out fft buffer so that unused channels are always 0
        std::fill_n(d_fft->get_inbuf(), d_twox * d_numchans, 0);
    }
}

ber_sink_b_impl::general_work(int noutput_items,
                                  gr_vector_int& ninput_items,
                                  gr_vector_const_void_star& input_items,
                                  gr_vector_void_star& output_items)
{
    if (gr::high_res_timer_now() - d_last_time > d_update_time) {
        d_last_time = gr::high_res_timer_now();
        d_qApplication->postEvent(
            d_main_gui,
            new ConstUpdateEvent(d_esno_buffers, d_ber_buffers, d_nconnections));
    }

    // check stopping condition
    int done = 0, maxed = 0;
    for (int j = 0; j < d_curves; ++j) {
        for (int i = 0; i < d_nconnections; ++i) {

            if (d_total_errors[j * d_nconnections + i] >= d_ber_min_errors) {
                done++;
            } else if (std::log10(((double)d_ber_min_errors) /
                                  (d_total[j * d_nconnections + i] * 8.0)) <
                       d_ber_limit) {
                maxed++;
            }
        }
    }

    if (done + maxed == (int)(d_nconnections * d_curves)) {
        d_qApplication->postEvent(
            d_main_gui,
            new ConstUpdateEvent(d_esno_buffers, d_ber_buffers, d_nconnections));
        return -1;
    }

    float ber;
    for (unsigned int i = 0; i < ninput_items.size(); i += 2) {

        if ((d_total_errors[i >> 1] < d_ber_min_errors) &&
            (std::log10(((double)d_ber_min_errors) / (d_total[i >> 1] * 8.0)) >=
             d_ber_limit)) {

            int items = ninput_items[i] <= ninput_items[i + 1] ? ninput_items[i]
                                                               : ninput_items[i + 1];

            const unsigned char* inbuffer0 = (const unsigned char*)input_items[i];
            const unsigned char* inbuffer1 = (const unsigned char*)input_items[i + 1];

            if (items > 0) {
                uint32_t ret;
                for (int j = 0; j < items; j++) {
                    volk_32u_popcnt(&ret,
                                    static_cast<uint32_t>(inbuffer0[j] ^ inbuffer1[j]));
                    d_total_errors[i >> 1] += ret;
                }

                d_total[i >> 1] += items;

                ber = std::log10(((double)d_total_errors[i >> 1]) /
                                 (d_total[i >> 1] * 8.0));
                d_ber_buffers[i / (d_nconnections * 2)][(i % (d_nconnections * 2)) >> 1] =
                    ber;
            }
            consume(i, items);
            consume(i + 1, items);

            if (d_total_errors[i >> 1] >= d_ber_min_errors) {
                d_logger->info("    {:d} over {:d}  -->  {:g}",
                               d_total_errors[i >> 1],
                               d_total[i >> 1] * 8,
                               ber);
            } else if (std::log10(((double)d_ber_min_errors) / (d_total[i >> 1] * 8.0)) <
                       d_ber_limit) {
                d_logger->info("BER Limit Reached");
                d_ber_buffers[i / (d_nconnections * 2)][(i % (d_nconnections * 2)) >> 1] =
                    d_ber_limit;
                d_total_errors[i >> 1] = d_ber_min_errors + 1;
            }
        } else {
            consume(i, ninput_items[i]);
            consume(i + 1, ninput_items[i + 1]);
        }
    }

    return 0;
}

rfnoc_f15_display_impl::_work_hist(const uint8_t* input, int n_items, int port)
{
    static const pmt::pmt_t EOB_KEY = pmt::string_to_symbol("rx_eob");
    std::vector<tag_t> v;
    const uint64_t nR = nitems_read(port);
    // End-of-frame index, relative to the input buffer
    int pEOF;

    /* Anything to do ? */
    if (n_items < 1)
        return 0;

    /* Grab all tags available, we'll need them either way */
    get_tags_in_range(v, port, nR, nR + n_items, EOB_KEY);

    /* If not aligned we just search for EOF */
    if (!d_aligned) {
        /* No tags ?  Drop all useless data while we wait for one */
        if (v.empty())
            return n_items;

        /* Start at zero right after the tag */
        d_subframe = 0;
        d_aligned = true;

        return v[0].offset - nR + 1;
    }

    /* Check alignment */
    pEOF = v.empty() ? -1 : (v[0].offset - nR);

    if (n_items >= (d_subframe_num - d_subframe)) {
        /* We have the end of the frame, must be an EOF on that */
        if (pEOF != (d_subframe_num - d_subframe - 1)) {
            d_aligned = false;
            return 0;
        }
    } else {
        /* We don't have the end of the frame yet, there can't be any EOF */
        if (pEOF >= 0) {
            d_aligned = false;
            return 0;
        }
    }

    /* Limit to expected frame boundary */
    if (n_items > (d_subframe_num - d_subframe))
        n_items = d_subframe_num - d_subframe;

    /* Copy the data */
    memcpy(&d_frame[d_fft_bins * d_subframe], input, n_items * d_fft_bins);

    d_subframe += n_items;

    /* Are we done ? */
    if (d_subframe == d_subframe_num) {
        /* Send the frame to the display surface */
        d_gui->sendFrame(d_frame, d_subframe_num * d_fft_bins);

        /* Start over */
        d_subframe = 0;
    }

    return n_items;
}

