    message_port_register_in(pmt::mp("in"));
    set_msg_handler(pmt::mp("in"), [this](pmt::pmt_t msg) { this->handle_pdus(msg); });

    d_scale = 1.0f;

    d_icols = static_cast<int>(ceil(d_cols));
    d_tmpflt.resize(d_icols);

    // +1 for the PDU buffer
