repack_bits_bb_impl::work(int noutput_items,
                              gr_vector_int& ninput_items,
                              gr_vector_const_void_star& input_items,
                              gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock guard(d_setlock);
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int bytes_to_write = noutput_items;

    if (d_packet_mode) { // noutput_items could be larger than necessary
        int bytes_to_read = ninput_items[0];
        bytes_to_write = bytes_to_read * d_k / d_l;
        if (!d_align_output && (((bytes_to_read * d_k) % d_l) != 0)) {
            bytes_to_write++;
        }
    }

    int n_read = 0;
    int n_written = 0;
    switch (d_endianness) {
    case GR_LSB_FIRST:
        while (n_written < bytes_to_write && n_read < ninput_items[0]) {
            if (d_out_index == 0) { // Starting a fresh byte
                out[n_written] = 0;
            }
            out[n_written] |= ((in[n_read] >> d_in_index) & 0x01) << d_out_index;

            d_in_index = (d_in_index + 1) % d_k;
            d_out_index = (d_out_index + 1) % d_l;
            if (d_in_index == 0) {
                n_read++;
                d_in_index = 0;
            }
            if (d_out_index == 0) {
                n_written++;
                d_out_index = 0;
            }
        }

        if (d_packet_mode) {
            if (d_out_index) {
                n_written++;
                d_out_index = 0;
            }
        } else {
            consume_each(n_read);
        }
        break;


    case GR_MSB_FIRST:
        while (n_written < bytes_to_write && n_read < ninput_items[0]) {
            if (d_out_index == 0) { // Starting a fresh byte
                out[n_written] = 0;
            }
            out[n_written] |= ((in[n_read] >> (d_k - 1 - d_in_index)) & 0x01)
                              << (d_l - 1 - d_out_index);

            d_in_index = (d_in_index + 1) % d_k;
            d_out_index = (d_out_index + 1) % d_l;
            if (d_in_index == 0) {
                n_read++;
                d_in_index = 0;
            }
            if (d_out_index == 0) {
                n_written++;
                d_out_index = 0;
            }
        }

        if (d_packet_mode) {
            if (d_out_index) {
                n_written++;
                d_out_index = 0;
            }
        } else {
            consume_each(n_read);
        }
        break;

    default:
        throw std::runtime_error("repack_bits_bb: unrecognized endianness value.");
    }

    return n_written;
}

message_debug_impl::print(const pmt::pmt_t& msg)
{
    if (pmt::is_pdu(msg)) {
        const auto& meta = pmt::car(msg);
        const auto& vector = pmt::cdr(msg);

        fmt::print("{:*^{}}\n"
                   "{:s}\n",
                   " VERBOSE PDU DEBUG PRINT ",
                   PRINT_LINE_LENGTH,
                   pmt::write_string(meta));

        size_t len = pmt::blob_length(vector);
        if (d_en_uvec) {
            fmt::print("pdu length = {:10d} bytes\n"
                       "pdu vector contents = \n",
                       len);
            size_t offset(0);
            const uint8_t* d =
                (const uint8_t*)pmt::uniform_vector_elements(vector, offset);
            for (size_t i = 0; i < len; i += 16) {
                fmt::print("{:04x}: ", static_cast<unsigned int>(i));
                for (size_t j = i; j < std::min(i + 16, len); j++) {
                    fmt::print("{:02x} ", d[j]);
                }
                fmt::print("\n");
            }
        } else {
            fmt::print("pdu length = {:10d} bytes (printing disabled)\n", len);
        }

    } else {
        fmt::print("{:*^{}}\n"
                   "{:s}\n",
                   " MESSAGE DEBUG PRINT ",
                   PRINT_LINE_LENGTH,
                   pmt::write_string(msg));
    }

    fmt::print("{:*^{}}\n", "", PRINT_LINE_LENGTH);
}

