                out[produced++] = m_pl[plh];
                out[produced++] = m_zero;
            }
            for (int j = 0; j < slots; j++) {
                for (int k = 0; k < 90; k++) {
                    tempin = in[consumed++];
                    switch (m_cscram[n++]) {
                    case 0:
                        tempout = tempin;
                        break;
                    case 1:
                        tempout = gr_complex(-tempin.imag(), tempin.real());
                        break;
                    case 2:
                        tempout = -tempin;
