QRfnocF15Surface::drawGrid()
{
    float x[2], y[2];
    int i;

    if (!d_grid_enabled)
        return;

    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    glBegin(GL_LINES);
    glColor4f(0.02f, 0.02f, 0.02f, 0.5f);

    /* Vertical div */
    x[0] = d_layout.x[1];
    x[1] = d_layout.x[2];

    for (i = 0; i < 11; i++) {
        y[0] = d_layout.y[3] + i * d_layout.y_div + 0.5f;

        glVertex2f(x[0], y[0]);
        glVertex2f(x[1], y[0]);
    }

    /* Horizontal div */
    y[0] = d_layout.y[3];
    y[1] = d_layout.y[4];

    for (i = 0; i < 11; i++) {
        x[0] = d_layout.x[1] + i * d_layout.x_div + 0.5f;

        glVertex2f(x[0], y[0]);
        glVertex2f(x[0], y[1]);
    }

    glEnd();
    glDisable(GL_BLEND);
}

