fsm::generate_TM()
{
    gr::logger logger("gnuradio-config-info.cc");
    d_TMi.resize(d_S * d_S);
    d_TMl.resize(d_S * d_S);

    for (int i = 0; i < d_S * d_S; i++) {
        d_TMi[i] = -1;  // no meaning
        d_TMl[i] = d_S; // infinity: you need at most S-1 steps
        if (i / d_S == i % d_S)
            d_TMl[i] = 0;
    }

    for (int s = 0; s < d_S; s++) {
        bool done = false;
        int attempts = 0;
        while (done == false && attempts < d_S - 1) {
            done = find_es(s);
            attempts++;
        }
        if (done == false && d_S > 1) {
            // throw std::runtime_error ("fsm::generate_TM(): FSM appears to be
            // disconnected");

            logger.error("fsm::generate_TM(): FSM appears to be disconnected; state "
                         "{:d} cannot be reached from all other states",
                         s);
        }
    }
}

