pfb_decimator_ccf_impl::work_fir_exp(int noutput_items,
                                         gr_vector_const_void_star& input_items,
                                         gr_vector_void_star& output_items)
{
    const gr_complex* in;
    gr_complex* out = (gr_complex*)output_items[0];

    int i;
    for (i = 0; i < noutput_items; i++) {
        // Move through filters from bottom to top
        out[i] = 0;
        for (int j = d_rate - 1; j >= 0; j--) {
            // Take items from M-1 to 0; filter and rotate
            in = (const gr_complex*)input_items[d_rate - 1 - j];
            out[i] += d_fir_filters[j].filter(&in[i]) * d_rotator[j];
        }
    }

    return noutput_items;
}

fft_filter_ccf::compute_sizes(int ntaps)
{
    int old_fftsize = d_fftsize;
    d_ntaps = ntaps;
    d_fftsize = (int)(2 * pow(2.0, ceil(log(double(ntaps)) / log(2.0))));
    d_nsamples = d_fftsize - d_ntaps + 1;

    if (VERBOSE) {
        d_logger->alert("fft_filter_ccf: ntaps = {:d} fftsize = {:d} nsamples = {:d}",
                        d_ntaps,
                        d_fftsize,
                        d_nsamples);
    }

    // compute new plans
    if (d_fftsize != old_fftsize) {
        d_fwdfft = std::make_unique<fft::fft_complex_fwd>(d_fftsize, d_nthreads);
        d_invfft = std::make_unique<fft::fft_complex_rev>(d_fftsize, d_nthreads);
        d_xformed_taps.resize(d_fftsize);
    }
}

