dvbs2_physical_cc_impl::b_64_8_code(unsigned char in, int* out)
{
    unsigned long temp, bit;

    temp = 0;

    if (in & 0x80) {
        temp ^= g[0];
    }
    if (in & 0x40) {
        temp ^= g[1];
    }
    if (in & 0x20) {
        temp ^= g[2];
    }
    if (in & 0x10) {
        temp ^= g[3];
    }
    if (in & 0x08) {
        temp ^= g[4];
    }
    if (in & 0x04) {
        temp ^= g[5];
    }
    if (in & 0x02) {
        temp ^= g[6];
    }

    bit = 0x80000000;
    for (int m = 0; m < 32; m++) {
        out[(m * 2)] = (temp & bit) ? 1 : 0;
        out[(m * 2) + 1] = out[m * 2] ^ (in & 0x01);
        bit >>= 1;
    }
    // Randomise it
    for (int m = 0; m < 64; m++) {
        out[m] = out[m] ^ ph_scram_tab[m];
    }
}

