windows_sink::find_device(std::string szDeviceName)
{
    UINT result = -1;
    UINT num_devices = waveOutGetNumDevs();
    if (num_devices > 0) {
        // what the device name passed as a number?
        if (is_number(szDeviceName)) {
            // a number, so must be referencing a device ID (which incremement from zero)
            UINT num = std::stoul(szDeviceName);
            if (num < num_devices) {
                result = num;
            } else {
                d_logger->warn("waveOut deviceID {:d} was not found. "
                               "defaulting to WAVE_MAPPER",
                               num);
                result = WAVE_MAPPER;
            }

        } else {
            // device name passed as string
            for (UINT i = 0; i < num_devices; i++) {
                WAVEOUTCAPS woc;
                if (waveOutGetDevCaps(i, &woc, sizeof(woc)) != MMSYSERR_NOERROR) {
                    d_logger->error("Could not retrieve wave out device "
                                    "capabilities for {:s} device",
                                    strerror(errno));
                    return -1;
                }
                if (woc.szPname == szDeviceName) {
                    result = i;
                }
                if (verbose) {
                    d_debug_logger->info("WaveOut Device {:d}: {:s}", i, woc.szPname);
                }
            }
            if (result == (UINT)-1) {
                d_logger->warn("waveOut device '{:s}' was not found, "
                               "defaulting to WAVE_MAPPER",
                               szDeviceName);
                result = WAVE_MAPPER;
            }
        }
    } else {
        d_logger->error("No WaveOut devices present or accessible: {:s}",
                        strerror(errno));
    }
    return result;
}

