    switch (argtype) {
    case SoapySDR::ArgInfo::BOOL:
        ret = py::bool_(gr::soapy::string_to_setting<bool>(str));
        break;

    case SoapySDR::ArgInfo::INT:
        ret = py::int_(gr::soapy::string_to_setting<int>(str));
        break;

    case SoapySDR::ArgInfo::FLOAT:
        ret = py::float_(gr::soapy::string_to_setting<double>(str));
        break;

    default:
        ret = py::str(str);
        break;
    }

    return ret;
}

fft_filter_ccc::compute_sizes(int ntaps)
{
    int old_fftsize = d_fftsize;
    d_ntaps = ntaps;
    d_fftsize = (int)(2 * pow(2.0, ceil(log(double(ntaps)) / log(2.0))));
    d_nsamples = d_fftsize - d_ntaps + 1;

    if (VERBOSE) {
        d_logger->alert("fft_filter_ccc: ntaps = {:d} fftsize = {:d} nsamples = {:d}",
                        d_ntaps,
                        d_fftsize,
                        d_nsamples);
    }

    // compute new plans
    if (d_fftsize != old_fftsize) {
        d_fwdfft = std::make_unique<fft::fft_complex_fwd>(d_fftsize, d_nthreads);
        d_invfft = std::make_unique<fft::fft_complex_rev>(d_fftsize, d_nthreads);
        d_xformed_taps.resize(d_fftsize);
    }
}

