context:
tpc_decoder::generic_work(const void* inBuffer, void* outBuffer)
{
    const float* inPtr = (const float*)inBuffer;
    unsigned char* out = (unsigned char*)outBuffer;

    unsigned int m, n, ii;
    int iter;

    for (ii = 0; ii < numInitLoadIter; ii++) {
        memset(&channel_llr[ii][0], 0, sizeof(float) * codeword_N);
        memset(&Z[ii][0], 0, sizeof(float) * codeword_N);
    }
    memset(&channel_llr[ii][0], 0, sizeof(float) * numInitRemaining);
    memset(&Z[ii][0], 0, sizeof(float) * numInitRemaining);
    memcpy(&channel_llr[ii][numInitRemaining],
           &inPtr[0],
           (codeword_N - numInitRemaining) * sizeof(float));
    memcpy(&Z[ii][numInitRemaining],
           &inPtr[0],
           (codeword_N - numInitRemaining) * sizeof(float));
    int inPtrIdx = codeword_N - numInitRemaining;
    for (ii = ii + 1; ii < codeword_M; ii++) {
        memcpy(&channel_llr[ii][0], &inPtr[inPtrIdx], sizeof(float) * codeword_N);
        memcpy(&Z[ii][0], &inPtr[inPtrIdx], sizeof(float) * codeword_N);
        inPtrIdx += codeword_N;
    }

    // clear out extrinsic-info between blocks
    memset(&extrinsic_info[0], 0, sizeof(float) * extrinsic_info.size());

    // DEBUG_PRINT("Starting TURBO Decoding\n");

    for (iter = 0; iter < d_max_iter; iter++) {
        // DEBUG_PRINT("Turbo Iter=%d\n", iter+1);
        // DEBUG_PRINT_F(fp, "Turbo Iter=%d\n", iter+1);
        // decode each row
        for (m = 0; m < codeword_M; m++) {
            // stage the data
            volk_32f_x2_add_32f(&input_c_rows[0],
                                &channel_llr[m][0],
                                &extrinsic_info[m * codeword_N],
                                codeword_N);

            // DEBUG_PRINT("input_c_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&input_c_rows[0], codeword_N);
            // DEBUG_PRINT_F(fp, "input_c_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &input_c_rows[0], codeword_N);

            // call siso decode
            siso_decode_row();

            // DEBUG_PRINT("output_u_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&output_u_rows[0], output_u_rows.size());
            // DEBUG_PRINT_F(fp, "output_u_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &output_u_rows[0],
            // output_u_rows.size()); DEBUG_PRINT("output_c_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&output_c_rows[0], output_c_rows.size());
            // DEBUG_PRINT_F(fp, "output_c_rows -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &output_c_rows[0],
            // output_c_rows.size());

            // copy the output coded back into Z, so we can feed it back through the
            // decoder for more iterations
            volk_32f_x2_subtract_32f(
                &Z[m][0], &output_c_rows[0], &extrinsic_info[m * codeword_N], codeword_N);
        }

        // decode each col
        earlyExit = true;
        output_c_col_idx = 0;
        for (n = 0; n < codeword_N; n++) {
            // stage the data
            for (ii = 0; ii < codeword_M; ii++) {
                input_c_cols[ii] = Z[ii][n];
            }

            // DEBUG_PRINT("input_c_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&input_c_cols[0], codeword_M);
            // DEBUG_PRINT_F(fp, "input_c_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &input_c_cols[0], codeword_M);

            // call siso decode
            siso_decode_col();

            // DEBUG_PRINT("output_u_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&output_u_cols[0], output_u_cols.size());
            // DEBUG_PRINT_F(fp, "output_u_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &output_u_cols[0],
            // output_u_cols.size()); DEBUG_PRINT("output_c_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT(&output_c_cols[output_c_col_idx],
            // codeword_M); DEBUG_PRINT_F(fp, "output_c_cols -->\n");
            // DEBUG_PRINT_FLOAT_ARRAY_AS_FLOAT_F(fp, &output_c_cols[output_c_col_idx],
            // codeword_M);

            // create the extrinsic_info vector, which subtracts from input_c_cols to
            // prevent feedback
            // DEBUG_PRINT("extrinsic_info -->\n");
            // DEBUG_PRINT_F(fp, "extrinsic_info -->\n");
            for (ii = 0; ii < codeword_M; ii++) {
                extrinsic_info[ii * codeword_N + n] =
                    output_c_cols[output_c_col_idx + ii] - input_c_cols[ii];

                if (earlyExit) {
                    if (sgn(output_c_cols[output_c_col_idx + ii]) !=
                        sgn(input_c_cols[ii])) {
                        earlyExit = false;
                    }
                }


                // DEBUG_PRINT("%f ", extrinsic_info[ii*codeword_N+n]);
                // DEBUG_PRINT_F(fp, "%f ", extrinsic_info[ii*codeword_N+n]);
            }
            // DEBUG_PRINT("\n");
            // DEBUG_PRINT_F(fp, "\n");

            output_c_col_idx += codeword_M;
        }
        if (earlyExit)
            break;
    }

    ii = 0;
    for (m = 0; m < d_kcol; m++) {
        for (n = 0; n < d_krow; n++) {
            if (ii == 0) {
                m = mInit;
                n = nInit;
            }

            // make a hard decision
            //			if(output_matrix[n*codeword_M+m]>0) {
            if (output_c_cols[n * codeword_M + m] > 0) {
                out[ii++] = (unsigned char)1;
            } else {
                out[ii++] = (unsigned char)0;
            }
        }
    }

    // DEBUG_PRINT(("Output\n"));
    // DEBUG_PRINT_UCHAR_ARRAY(out, outputSize);
    // DEBUG_PRINT_F(fp, "Output\n");
    // DEBUG_PRINT_UCHAR_ARRAY_F(fp, out, outputSize);
}

pfb_decimator_ccf_impl::work_fft_fft(int noutput_items,
                                         gr_vector_const_void_star& input_items,
                                         gr_vector_void_star& output_items)
{
    const gr_complex* in;
    gr_complex* out = (gr_complex*)output_items[0];

    int i;

    for (unsigned int j = 0; j < d_rate; j++) {
        in = (const gr_complex*)input_items[d_rate - j - 1];
        d_fft_filters[j].filter(noutput_items, in, &d_tmp[j * noutput_items]);
    }

    // Performs the rotate and add operations by implementing it as
    // an FFT.
    for (i = 0; i < noutput_items; i++) {
        for (unsigned int j = 0; j < d_rate; j++) {
            d_fft.get_inbuf()[j] = d_tmp[j * noutput_items + i];
        }

        // Perform the FFT to do the complex multiply despinning for all channels
        d_fft.execute();

        // Select only the desired channel out
        out[i] = d_fft.get_outbuf()[d_chan];
    }

    return noutput_items;
}

