snr_est_m2m4::snr()
{
    double M2 = d_y1;
    double M4 = d_y2;
    d_signal =
        M2 * (d_kw - 2) + sqrt((4.0 - d_ka * d_kw) * M2 * M2 + M4 * (d_ka + d_kw - 4.0)) /
                              (d_ka + d_kw - 4.0);
    d_noise = M2 - d_signal;

    return 10.0 * log10(d_signal / d_noise);
}

