def fir_filter2(x1, x2, taps, delay):
    y = []
    x1_2 = (len(taps) - 1) * [0, ] + x1
    x2_2 = (len(taps) - 1) * [0, ] + x2
    for i in range(len(x2)):
        yi = 0
        for j in range(len(taps)):
            yi += taps[len(taps) - 1 - j] * x2_2[i + j]
        y.append(complex(x1_2[i + delay], yi))
    return y

