codec2_decode_ps_impl::pack_frame(const unsigned char* in_unpacked,
                                       unsigned char* out_packed)
{
    memset((void*)&d_frame_buf[0], 0x00, d_bytes_per_frame);

    int byte_idx = 0, bit_idx = 0;
    for (int k = 0; k < d_bits_per_frame; k++) {
        out_packed[byte_idx] |= ((in_unpacked[k] & 0x01) << (7 - bit_idx));
        bit_idx = (bit_idx + 1) % 8;
        if (bit_idx == 0) {
            byte_idx++;
        }
    }
}

header_format_ofdm::parse(int nbits_in,
                               const unsigned char* input,
                               std::vector<pmt::pmt_t>& info,
                               int& nbits_processed)
{
    while (nbits_processed <= nbits_in) {
        // Remove scrambing and fill up header buffer. Scramble mask has 8 significant
        // bits per byte, while input has only one
        d_hdr_reg.insert_bit(
            ((d_scramble_mask[nbits_processed / 8] >> nbits_processed % 8) & 0x01) ^
            input[nbits_processed]);
        nbits_processed++;
        if (d_hdr_reg.length() == header_nbits()) {
            if (header_ok()) {
                int payload_len = header_payload();
                enter_have_header(payload_len);
                info.push_back(d_info);
                d_hdr_reg.clear();
                return true;
            } else {
                d_hdr_reg.clear();
                return false;
            }
            break;
        }
    }

    return true;
}

