_si_scaling(double val, int max_num, char* prefix, int* exp)
{
    const char prefixes[5] = { ' ', 'k', 'M', 'G', 'T' };
    int exponent = log10f(fabs(val));
    int d = exponent >= max_num ? ((exponent - max_num + 3) / 3) : 0;

    if (prefix)
        *prefix = prefixes[d];

    if (exp)
        *exp = d * 3;

    return val / powf(10.0, d * 3);
}

