window::max_attenuation(win_type type, double param)
{
    switch (type) {
    case (WIN_HAMMING):
        return 53;
    case (WIN_HANN):
        return 44;
    case (WIN_BLACKMAN):
        return 74;
    case (WIN_RECTANGULAR):
        return 21;
    case (WIN_KAISER):
        // linear approximation
        return (param / 0.1102 + 8.7);
    case (WIN_BLACKMAN_hARRIS):
        return 92;
    case (WIN_BARTLETT):
        return 27;
    case (WIN_FLATTOP):
        return 93;
    case WIN_NUTTALL:
        return 114;
    case WIN_NUTTALL_CFD:
        return 112;
    case WIN_WELCH:
        return 31;
    case WIN_PARZEN:
        return 56;
    case WIN_EXPONENTIAL:
        // varies slightly depending on the decay factor, but this is a safe return value
        return 26;
    case WIN_RIEMANN:
        return 39;
    case WIN_GAUSSIAN:
        // value not meaningful for gaussian windows, but return something reasonable
        return 100;
    case WIN_TUKEY:
        // low end is a rectangular window, attenuation exponentially approaches Hann
        // piecewise linear estimate, determined empirically via curve fitting, median
        // error is less than 0.5dB and maximum error is 2.5dB; the returned value will
        // never be less than expected attenuation to ensure that window designed filters
        // are never below expected quality.
        if (param > 0.9)
            return ((param - 0.9) * 135 + 30.5);
        else if (param > 0.7)
            return ((param - 0.6) * 20 + 24);
        return (param * 5 + 21);
    default:
        throw std::out_of_range("window::max_attenuation: unknown window type provided.");
    }
}

interpolating_resampler_ccf::make(
    enum ir_type type, bool derivative, int nfilts, const std::vector<float>& taps)
{
    switch (type) {
    case IR_MMSE_8TAP:
        return std::make_unique<interp_resampler_mmse_8tap_cc>(derivative);
    case IR_PFB_NO_MF:
        return std::make_unique<interp_resampler_pfb_no_mf_cc>(derivative, nfilts);
