dvbs2_physical_cc_impl::general_work(int noutput_items,
                                         gr_vector_int& ninput_items,
                                         gr_vector_const_void_star& input_items,
                                         gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];
    int consumed = 0;
    int produced = 0;
    int slot_count, n;
    int group, symbols;
    gr_complex tempin, tempout;

    if (vlsnr_set == VLSNR_OFF) {
        for (int i = 0; i < noutput_items / 2;
             i += (((slots * 90) + 90) + pilot_symbols)) {
            n = 0;
            slot_count = 0;
            for (int plh = 0; plh < 90; plh++) {
                out[produced++] = m_pl[plh];
                out[produced++] = m_zero;
            }
            for (int j = 0; j < slots; j++) {
                for (int k = 0; k < 90; k++) {
                    tempin = in[consumed++];
                    switch (m_cscram[n++]) {
                    case 0:
                        tempout = tempin;
                        break;
                    case 1:
                        tempout = gr_complex(-tempin.imag(), tempin.real());
                        break;
                    case 2:
                        tempout = -tempin;
                        break;
                    case 3:
                        tempout = gr_complex(tempin.imag(), -tempin.real());
                        break;
                    }
                    out[produced++] = tempout;
                    out[produced++] = m_zero;
                }
                slot_count = (slot_count + 1) % 16;
                if ((slot_count == 0) && (j < slots - 1)) {
                    if (pilot_mode) {
                        // Add pilots if needed
                        for (int p = 0; p < 36; p++) {
                            tempin = m_bpsk[0][0];
                            switch (m_cscram[n++]) {
                            case 0:
                                tempout = tempin;
                                break;
                            case 1:
                                tempout = gr_complex(-tempin.imag(), tempin.real());
                                break;
                            case 2:
                                tempout = -tempin;
                                break;
                            case 3:
                                tempout = gr_complex(tempin.imag(), -tempin.real());
                                break;
                            }
                            out[produced++] = tempout;
                            out[produced++] = m_zero;
                        }
                    }
                }
            }
        }
    } else if (vlsnr_set == VLSNR_SET1) {
        for (int i = 0; i < noutput_items / 2;
             i += (((slots * 90) + 90) + pilot_symbols + VLSNR_HEADER_LENGTH + 36)) {
            n = 900;
            slot_count = 10;
            group = 0;
            symbols = 0;
            for (int plh = 0; plh < 90; plh++) {
                out[produced++] = m_pl[plh];
                out[produced++] = m_zero;
            }
            for (int vlh = 0; vlh < VLSNR_HEADER_LENGTH; vlh++) {
                out[produced++] = m_vlsnr_header[vlh];
                out[produced++] = m_zero;
            }
            for (int j = 0; j < slots; j++) {
                for (int k = 0; k < 90; k++) {
                    tempin = in[consumed++];
                    if (signal_constellation == MOD_QPSK) {
                        switch (m_cscram[n++]) {
                        case 0:
                            tempout = tempin;
                            break;
                        case 1:
                            tempout = gr_complex(-tempin.imag(), tempin.real());
                            break;
                        case 2:
                            tempout = -tempin;
                            break;
                        case 3:
                            tempout = gr_complex(tempin.imag(), -tempin.real());
                            break;
                        }
                    } else {
                        switch (m_cscram[n++]) {
                        case 0:
                            tempout = tempin;
                            break;
                        case 1:
                            tempout = -tempin;
                            break;
                        case 2:
                            tempout = tempin;
                            break;
                        case 3:
                            tempout = -tempin;
                            break;
                        }
                    }
                    out[produced++] = tempout;
                    out[produced++] = m_zero;
                    symbols++;
                    if (group <= 18 && symbols == 703) {
                        for (int p = 0; p < 34; p++) {
                            tempin = m_bpsk[0][0];
                            switch (m_cscram[n++]) {
                            case 0:
                                tempout = tempin;
                                break;
                            case 1:
                                tempout = gr_complex(-tempin.imag(), tempin.real());
                                break;
                            case 2:
                                tempout = -tempin;
                                break;
                            case 3:
                                tempout = gr_complex(tempin.imag(), -tempin.real());
                                break;
                            }
                            out[produced++] = tempout;
                            out[produced++] = m_zero;
                        }
                        for (int x = (k + 1 + 34) - 90; x < 90; x++) {
                            tempin = in[consumed++];
                            if (signal_constellation == MOD_QPSK) {
                                switch (m_cscram[n++]) {
                                case 0:
                                    tempout = tempin;
                                    break;
                                case 1:
                                    tempout = gr_complex(-tempin.imag(), tempin.real());
                                    break;
