mpsk_snr_est_simple::update(int noutput_items, const gr_complex* input)
{
    int i = 0;
    if (d_counter == 0) {
        d_y1 = abs(input[0]);
        d_y2 = 0;
        d_counter++;
        i++;
    }

    for (; i < noutput_items; i++) {
        double x = abs(input[i]);
        double m = d_y1 + (x - d_y1) / d_counter;
        d_y2 = d_y2 + (x - d_y1) * (x - m);
        d_y1 = m;
        d_counter++;
    }
    return noutput_items;
}

