    int num = mapped_items - stream_items - 1840 - (N_post / eta_mod) - (N_FC - C_FC);
    std::fill_n(&dummy_randomize[0], num, 0);
    for (int i = 0; i < num; i++) {
        int b = ((sr) ^ (sr >> 1)) & 1;
        dummy_randomize[i] = (b ? -1.0 : 1.0);
        sr >>= 1;
        if (b) {
            sr |= 0x4000;
        }
    }
}

