correlate_access_code_tag_ff_impl::set_access_code(const std::string& access_code)
{
    gr::thread::scoped_lock l(d_mutex_access_code);

    d_len = access_code.length(); // # of bytes in string
    if (d_len > 64)
        return false;

    // set len bottom bits to 1.
    d_mask = ((~0ULL) >> (64 - d_len));

    d_access_code = 0;
    for (unsigned i = 0; i < d_len; i++) {
        d_access_code = (d_access_code << 1) | (access_code[i] & 1);
    }

    d_logger->debug("Access code: {:x}", d_access_code);
    d_logger->debug("Mask: {:x}", d_mask);

    return true;
}

dvbt2_miso_cc_impl::work(int noutput_items,
                             gr_vector_const_void_star& input_items,
                             gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out1 = (gr_complex*)output_items[0];
    gr_complex* out2 = (gr_complex*)output_items[1];
    gr_complex temp1, temp2;

    for (int i = 0; i < noutput_items; i += miso_items) {
        memcpy(out1, in, sizeof(gr_complex) * miso_items);
        out1 += miso_items;
        for (int j = 0; j < miso_items; j += 2) {
            temp1 = std::conj(*in++);
            temp2 = std::conj(*in++);
            *out2++ = -temp2;
            *out2++ = temp1;
        }
    }

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

