dvbt2_interleaver_bb_impl::generate_lookup()
{
    int rows, index = 0;
    // vectors instead of arrays because they're fairly big.
    std::vector<int> tempv2(FRAME_SIZE_NORMAL);
    std::vector<int> tempu2(FRAME_SIZE_NORMAL);
    const int* twist;
    const int *c1, *c2, *c3, *c4, *c5, *c6, *c7, *c8;
    const int *c9, *c10, *c11, *c12, *c13, *c14, *c15, *c16;

    for (int i = 0; i < FRAME_SIZE_NORMAL; i++) {
        lookup_table[i] = i;
    }

    const int* in = &lookup_table[0];

    switch (signal_constellation) {
        // ignore QPSK, not worth it, as there is no column interleaving
    case MOD_16QAM:
        rows = frame_size / (mod * 2);

        if (frame_size == FRAME_SIZE_NORMAL) {
            twist = &twist16n[0];
        } else {
            twist = &twist16s[0];
        }

        interleave_parity_bits(tempu2.data(), in);

        c1 = &tempv2[0];
        c2 = &tempv2[rows];
        c3 = &tempv2[rows * 2];
        c4 = &tempv2[rows * 3];
        c5 = &tempv2[rows * 4];
        c6 = &tempv2[rows * 5];
        c7 = &tempv2[rows * 6];
        c8 = &tempv2[rows * 7];

        twist_interleave_columns(tempv2.data(), tempu2.data(), rows, mod * 2, twist);

        for (int j = 0; j < rows; j++) {
            tempu2[index++] = c1[j];
            tempu2[index++] = c2[j];
            tempu2[index++] = c3[j];
            tempu2[index++] = c4[j];
            tempu2[index++] = c5[j];
            tempu2[index++] = c6[j];
            tempu2[index++] = c7[j];
            tempu2[index++] = c8[j];
        }
        break;

    case MOD_64QAM:
        rows = frame_size / (mod * 2);

        if (frame_size == FRAME_SIZE_NORMAL) {
            twist = twist64n;
        } else {
            twist = twist64s;
        }

        interleave_parity_bits(tempu2.data(), in);

        c1 = &tempv2[0];
        c2 = &tempv2[rows];
        c3 = &tempv2[rows * 2];
        c4 = &tempv2[rows * 3];
        c5 = &tempv2[rows * 4];
        c6 = &tempv2[rows * 5];
        c7 = &tempv2[rows * 6];
        c8 = &tempv2[rows * 7];
        c9 = &tempv2[rows * 8];
        c10 = &tempv2[rows * 9];
        c11 = &tempv2[rows * 10];
        c12 = &tempv2[rows * 11];

        twist_interleave_columns(tempv2.data(), tempu2.data(), rows, mod * 2, twist);

        for (int j = 0; j < rows; j++) {
            tempu2[index++] = c1[j];
            tempu2[index++] = c2[j];
            tempu2[index++] = c3[j];
            tempu2[index++] = c4[j];
            tempu2[index++] = c5[j];
            tempu2[index++] = c6[j];
            tempu2[index++] = c7[j];
            tempu2[index++] = c8[j];
            tempu2[index++] = c9[j];
            tempu2[index++] = c10[j];
            tempu2[index++] = c11[j];
            tempu2[index++] = c12[j];
        }
        break;

    case MOD_256QAM:
        if (frame_size == FRAME_SIZE_NORMAL) {
            rows = frame_size / (mod * 2);

            interleave_parity_bits(tempu2.data(), in);

            c1 = &tempv2[0];
            c2 = &tempv2[rows];
            c3 = &tempv2[rows * 2];
            c4 = &tempv2[rows * 3];
            c5 = &tempv2[rows * 4];
            c6 = &tempv2[rows * 5];
            c7 = &tempv2[rows * 6];
            c8 = &tempv2[rows * 7];
            c9 = &tempv2[rows * 8];
            c10 = &tempv2[rows * 9];
            c11 = &tempv2[rows * 10];
            c12 = &tempv2[rows * 11];
            c13 = &tempv2[rows * 12];
            c14 = &tempv2[rows * 13];
            c15 = &tempv2[rows * 14];
            c16 = &tempv2[rows * 15];

            twist_interleave_columns(
                tempv2.data(), tempu2.data(), rows, mod * 2, twist256n);

            for (int j = 0; j < rows; j++) {
                tempu2[index++] = c1[j];
                tempu2[index++] = c2[j];
                tempu2[index++] = c3[j];
                tempu2[index++] = c4[j];
                tempu2[index++] = c5[j];
                tempu2[index++] = c6[j];
                tempu2[index++] = c7[j];
                tempu2[index++] = c8[j];
                tempu2[index++] = c9[j];
                tempu2[index++] = c10[j];
                tempu2[index++] = c11[j];
                tempu2[index++] = c12[j];
                tempu2[index++] = c13[j];
                tempu2[index++] = c14[j];
                tempu2[index++] = c15[j];
                tempu2[index++] = c16[j];
            }
        } else { // frame_size == FRAME_SIZE_SHORT
            rows = frame_size / mod;

            interleave_parity_bits(tempu2.data(), in);

            c1 = &tempv2[0];
            c2 = &tempv2[rows];
            c3 = &tempv2[rows * 2];
            c4 = &tempv2[rows * 3];
            c5 = &tempv2[rows * 4];
            c6 = &tempv2[rows * 5];
            c7 = &tempv2[rows * 6];
            c8 = &tempv2[rows * 7];

            twist_interleave_columns(tempv2.data(), tempu2.data(), rows, mod, twist256s);

            for (int j = 0; j < rows; j++) {
                tempu2[index++] = c1[j];
                tempu2[index++] = c2[j];
                tempu2[index++] = c3[j];
                tempu2[index++] = c4[j];
                tempu2[index++] = c5[j];
                tempu2[index++] = c6[j];
                tempu2[index++] = c7[j];
                tempu2[index++] = c8[j];
            }
        }
    }

    // tempu2 now has the input indices interleaved correctly, so save it
    memcpy(lookup_table, tempu2.data(), frame_size * sizeof(int));
}

