pfb_clock_sync_ccf_impl::set_taps(
    const std::vector<float>& newtaps,
    std::vector<std::vector<float>>& ourtaps,
    std::vector<filter::kernel::fir_filter_ccf>& ourfilter)
{
    int i, j;

    const unsigned int ntaps = newtaps.size();
    d_taps_per_filter = (unsigned int)ceil((double)ntaps / (double)d_nfilters);

    // Create d_numchan vectors to store each channel's taps
    ourtaps.resize(d_nfilters);

    // Make a vector of the taps plus fill it out with 0's to fill
    // each polyphase filter with exactly d_taps_per_filter
    std::vector<float> tmp_taps;
    tmp_taps = newtaps;
    while ((float)(tmp_taps.size()) < d_nfilters * d_taps_per_filter) {
        tmp_taps.push_back(0.0);
    }

    // Partition the filter
    for (i = 0; i < d_nfilters; i++) {
        // Each channel uses all d_taps_per_filter with 0's if not enough taps to fill out
        ourtaps[i] = std::vector<float>(d_taps_per_filter, 0);
        for (j = 0; j < d_taps_per_filter; j++) {
            ourtaps[i][j] = tmp_taps[i + j * d_nfilters];
        }

        // Build a filter for each channel and add it's taps to it
        ourfilter[i].set_taps(ourtaps[i]);
    }

    // Set the history to ensure enough input items for each filter
    set_history(d_taps_per_filter + d_sps + d_sps);

    // Make sure there is enough output space for d_osps outputs/input.
    set_output_multiple(d_osps);
}

firdes::root_raised_cosine(
    double gain, double sampling_freq, double symbol_rate, double alpha, int ntaps)
{
    ntaps |= 1; // ensure that ntaps is odd

    double spb = sampling_freq / symbol_rate; // samples per bit/symbol
    vector<float> taps(ntaps);
    double scale = 0;
    for (int i = 0; i < ntaps; i++) {
        double x1, x2, x3, num, den;
        double xindx = i - ntaps / 2;
        x1 = GR_M_PI * xindx / spb;
        x2 = 4 * alpha * xindx / spb;
        x3 = x2 * x2 - 1;

        if (fabs(x3) >= 0.000001) { // Avoid Rounding errors...
            if (i != ntaps / 2)
                num = cos((1 + alpha) * x1) +
                      sin((1 - alpha) * x1) / (4 * alpha * xindx / spb);
            else
                num = cos((1 + alpha) * x1) + (1 - alpha) * GR_M_PI / (4 * alpha);
            den = x3 * GR_M_PI;
        } else {
            if (alpha == 1) {
                taps[i] = -1;
                scale += taps[i];
                continue;
            }
            x3 = (1 - alpha) * x1;
            x2 = (1 + alpha) * x1;
            num = (sin(x2) * (1 + alpha) * GR_M_PI -
                   cos(x3) * ((1 - alpha) * GR_M_PI * spb) / (4 * alpha * xindx) +
                   sin(x3) * spb * spb / (4 * alpha * xindx * xindx));
            den = -32 * GR_M_PI * alpha * alpha * xindx / spb;
        }
        taps[i] = 4 * alpha * num / den;
        scale += taps[i];
    }

    for (int i = 0; i < ntaps; i++)
        taps[i] = taps[i] * gain / scale;

    return taps;
}

