basic_sincos_vec(float* x, float* y)
{
    gr::nco<float, float> nco;

    nco.set_freq(2 * GR_M_PI / freq);

    for (auto i = iterations / block_size; i; --i) {
        for (uint64_t j = 0; j < block_size; j++) {
            nco.sincos(&x[2 * j + 1], &x[2 * j]);
            nco.step();
        }
    }
}

dvbt_demod_reference_signals_impl::general_work(
    int noutput_items,
    gr_vector_int& ninput_items,
    gr_vector_const_void_star& input_items,
    gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    int symbol_index = 0;
    int frame_index = 0;
    int to_out = 0;

    for (int i = 0; i < noutput_items; i++) {
        to_out += d_pg.parse_input(
            &in[i * d_ninput], &out[i * d_noutput], &symbol_index, &frame_index);
    }

    /*
     * Wait for a sync_start tag from upstream that signals when to start.
     * Always consume until to a superframe start.
     */
    if (is_sync_start(noutput_items)) {
        d_init = 0;
    }

    if (d_init == 0) {
        // This is super-frame start
        if (((symbol_index % 68) == 0) && ((frame_index % 4) == d_fi_start)) {
            d_init = 1;

            const uint64_t offset = this->nitems_written(0);
            pmt::pmt_t key = pmt::string_to_symbol("superframe_start");
            pmt::pmt_t value = pmt::from_long(0xaa);
            this->add_item_tag(0, offset, key, value);
        } else {
            consume_each(1);
            return (0);
        }
    }

    // Send a tag for each OFDM symbol informing about
    // symbol index.
    const uint64_t offset = this->nitems_written(0);
    pmt::pmt_t key = pmt::string_to_symbol("symbol_index");
    pmt::pmt_t value = pmt::from_long(symbol_index);
    this->add_item_tag(0, offset, key, value);

    // Consume from input stream
    consume_each(noutput_items);

    // Tell runtime system how many output items we produced.
    return to_out;
}

timing_error_detector::revert(bool preserve_error)
{
    if (d_input_clock == 0 && preserve_error != true)
        d_error = d_prev_error;
    revert_input_clock();

    if (d_needs_derivative) {
        d_input_derivative.push_back(d_input_derivative.back());
        d_input_derivative.pop_front();
    }

    if (d_constellation) {
        d_decision.push_back(d_decision.back());
        d_decision.pop_front();
    }

    d_input.push_back(d_input.back());
    d_input.pop_front();
}

def load_lxml(filename, document_type_def=None):
    """Load block description from xml file"""

    try:
        xml_tree = etree.parse(filename)
        _get_validator(document_type_def)
        element = xml_tree.getroot()
    except etree.LxmlError:
        raise ValueError("Failed to parse or validate {}".format(filename))

    version_info = {}
    for inst in xml_tree.xpath('/processing-instruction()'):
        if inst.target == 'grc':
            version_info.update(inst.attrib)

    return element, version_info

