    // Non-standard tones or edge tones get 2% guard band, otherwise
    // guards are set at adjacent ctcss tone frequencies
    if (i == -1 || i == 0)
        f_l = freq * 0.98;
    else
        f_l = ctcss_tones[i - 1];

    if (i == -1 || i == max_tone_index)
        f_r = freq * 1.02;
    else
        f_r = ctcss_tones[i + 1];
}

