regenerate_bb_impl::work(int noutput_items,
                             gr_vector_const_void_star& input_items,
                             gr_vector_void_star& output_items)
{
    const char* iptr = (const char*)input_items[0];
    char* optr = (char*)output_items[0];

    for (int i = 0; i < noutput_items; i++) {
        optr[i] = 0;

        if (d_regen_count < d_max_regen) {
            d_countdown--;

            if (d_countdown == 0) {
                optr[i] = 1;
                d_countdown = d_period;
                d_regen_count++;
            }
        }

        if (iptr[i] == 1) {
            d_countdown = d_period;
            optr[i] = 1;
            d_regen_count = 0;
        }
    }
    return noutput_items;
}

wavfile_sink_impl::open_file_for_rewrite()
{

    SF_INFO sfinfo;
    memset(&sfinfo, 0, sizeof(sfinfo));
    sfinfo.samplerate = d_h.sample_rate;
    sfinfo.channels = d_h.nchans;
    switch (d_h.format) {
    case FORMAT_WAV:
        switch (d_h.subformat) {
        case FORMAT_PCM_U8:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_PCM_U8);
            break;
        case FORMAT_PCM_16:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_PCM_16);
            break;
        case FORMAT_PCM_24:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_PCM_24);
            break;
        case FORMAT_PCM_32:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_PCM_32);
            break;
        case FORMAT_FLOAT:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_FLOAT);
            break;
        case FORMAT_DOUBLE:
            sfinfo.format = (SF_FORMAT_WAV | SF_FORMAT_DOUBLE);
            break;
        }
        break;
    case FORMAT_FLAC:
        switch (d_h.subformat) {
        case FORMAT_PCM_S8:
            sfinfo.format = (SF_FORMAT_FLAC | SF_FORMAT_PCM_S8);
            break;
        case FORMAT_PCM_16:
            sfinfo.format = (SF_FORMAT_FLAC | SF_FORMAT_PCM_16);
            break;
        case FORMAT_PCM_24:
            sfinfo.format = (SF_FORMAT_FLAC | SF_FORMAT_PCM_24);
            break;
        }
        break;
    case FORMAT_OGG:
        switch (d_h.subformat) {
        case FORMAT_VORBIS:
            sfinfo.format = (SF_FORMAT_OGG | SF_FORMAT_VORBIS);
            break;
        case FORMAT_OPUS:
#ifdef HAVE_SF_FORMAT_OPUS
            sfinfo.format = (SF_FORMAT_OGG | SF_FORMAT_OPUS);
#else
            throw std::runtime_error("libsndfile < 1.0.29 does not support Opus.");
#endif
            break;
        }
        break;
    case FORMAT_RF64:
        switch (d_h.subformat) {
        case FORMAT_PCM_U8:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_PCM_U8);
            break;
        case FORMAT_PCM_16:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_PCM_16);
            break;
        case FORMAT_PCM_24:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_PCM_24);
            break;
        case FORMAT_PCM_32:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_PCM_32);
            break;
        case FORMAT_FLOAT:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_FLOAT);
            break;
        case FORMAT_DOUBLE:
            sfinfo.format = (SF_FORMAT_RF64 | SF_FORMAT_DOUBLE);
            break;
        }
        break;
    }
    errno = 0;
    if (!(d_new_fp = sf_open(d_filename.c_str(), SFM_WRITE, &sfinfo))) {
        if (errno) {
            d_logger->error("sf_open(2) failed: {:s}: {:s}", d_filename, strerror(errno));
        } else {
            d_logger->error(
                "sf_open(2) failed: {:s}: {:s}", d_filename, sf_strerror(NULL));
        }

        return false;
    }

    d_updated = true;
    return true;
}

