            py::arg("min_streams"),
            py::arg("max_streams"),
            py::arg("sizeof_stream_items"),
            D(io_signature, makev))

        .def_static(
            "makev",
            [](int min,
               int max,
               const std::vector<size_t>& sizeof_stream_items,
               const gr::gr_vector_buffer_type& buftypes) {
