tpc_decoder::linear_log_map(const float delta1, const float delta2)
{
    float diff;

    diff = delta2 - delta1;

    if (diff > TJIAN)
        return (delta2);
    else if (diff < -TJIAN)
        return (delta1);
    else if (diff > 0)
        return (delta2 + AJIAN * (diff - TJIAN));
    else
        return (delta1 - AJIAN * (diff + TJIAN));
}

