attr_source_impl::work(int noutput_items,
                           gr_vector_const_void_star& input_items,
                           gr_vector_void_star& output_items)
{
    int sample;
    void* out;

    out = output_items[0];

    for (sample = 0; sample < samples_per_update; sample++) {
        std::this_thread::sleep_for(std::chrono::milliseconds(update_interval_ms));
        if (attr_type == attr_type_t::DEVICE_DEBUG)
            get_register_data(address, (((int*)out) + sample));
        else {
            switch (data_type) {
            case data_type_t::DOUBLE:
                get_attribute_data(attribute, ((double*)out + sample));
                break;
            case data_type_t::FLOAT:
                get_attribute_data(attribute, ((float*)out + sample));
                break;
            case data_type_t::LONGLONG:
                get_attribute_data(attribute, ((long long*)out + sample));
                break;
            case data_type_t::INT:
                get_attribute_data(attribute, ((int*)out + sample));
                break;
            case data_type_t::UINT8:
                get_attribute_data(attribute, ((uint8_t*)out + sample));
                break;
            }
        }
    }

    // Tell runtime system how many output items we produced.
    return samples_per_update;
}

freq_axis_render(struct freq_axis* fx, char* str, int step)
{
    /* Special case: count mode */
    if (step && (fx->mode == FX_MODE_COUNT)) {
        sprintf(str, "%+d", step);
        return;
    }

    /* Special case: no center frequency */
    if (!step && (fx->center == 0.0)) {
        sprintf(str, "0");
        return;
    }

    /* Relative case */
    if (step && (fx->mode == FX_MODE_RELATIVE)) {
        sprintf(str, fx->rel_fmt, step * fx->rel_step);
        return;
    }

    /* Normal full absolute frequency */
    sprintf(str, fx->abs_fmt, (fx->center + step * fx->step) * fx->abs_scale);
}

