pfb_channelizer_ccf_impl::general_work(int noutput_items,
                                           gr_vector_int& ninput_items,
                                           gr_vector_const_void_star& input_items,
                                           gr_vector_void_star& output_items)
{
    gr::thread::scoped_lock guard(d_mutex);

    const gr_complex* in = (const gr_complex*)input_items[0];
    gr_complex* out = (gr_complex*)output_items[0];

    if (d_updated) {
        d_updated = false;
        return 0; // history requirements may have changed.
    }

    size_t noutputs = output_items.size();

    // The following algorithm looks more complex in order to handle
    // the cases where we want more that 1 sps for each
    // channel. Otherwise, this would boil down into a single loop
    // that operates from input_items[0] to [d_nfilts].

    // When dealing with osps>1, we start not at the last filter,
    // but nfilts/osps and then wrap around to the next symbol into
    // the other set of filters.
    // For details of this operation, see:
    // fred harris, Multirate Signal Processing For Communication
    // Systems. Upper Saddle River, NJ: Prentice Hall, 2004.

    int n = 1, i = -1, j = 0, oo = 0, last;
    int toconsume = (int)rintf(noutput_items / d_oversample_rate);
    while (n <= toconsume) {
        j = 0;
        i = (i + d_rate_ratio) % d_nfilts;
        last = i;
        while (i >= 0) {
            in = (const gr_complex*)input_items[j];
            d_fft.get_inbuf()[d_idxlut[j]] = d_fir_filters[i].filter(&in[n]);
            j++;
            i--;
        }

        i = d_nfilts - 1;
        while (i > last) {
            in = (const gr_complex*)input_items[j];
            d_fft.get_inbuf()[d_idxlut[j]] = d_fir_filters[i].filter(&in[n - 1]);
            j++;
            i--;
        }

        n += (i + d_rate_ratio) >= (int)d_nfilts;

        // despin through FFT
        d_fft.execute();

        // Send to output channels
        for (unsigned int nn = 0; nn < noutputs; nn++) {
            out = (gr_complex*)output_items[nn];
            out[oo] = d_fft.get_outbuf()[d_channel_map[nn]];
        }
        oo++;
    }

    consume_each(toconsume);
    return noutput_items;
}

publish_message()
{
    /* determine the time. we always have the offset that the SOB tag
     * was received on, we know the rate, and also have a known time/offset
     * pair - calculate the delta and apply accordingly.
     */
    double delta;
    delta = ((int64_t)d_sob_tag_offset - (int64_t)d_known_time_offset) / d_samp_rate;
    int int_delta = (int)delta;
    delta -= int_delta;

    uint64_t int_seconds = d_known_time_int_sec + int_delta;
    double frac_seconds = d_known_time_frac_sec + delta;

    // keep fractional seconds in range [0, 1.0)
    if (frac_seconds >= 1.0) {
        frac_seconds -= 1.0;
        int_seconds += 1;
    }
    pmt::pmt_t time_tuple =
        pmt::make_tuple(pmt::from_uint64(int_seconds), pmt::from_double(frac_seconds));
    d_meta_dict = pmt::dict_add(d_meta_dict, metadata_keys::rx_time(), time_tuple);
    d_meta_dict = pmt::dict_add(
        d_meta_dict, metadata_keys::sample_rate(), pmt::from_double(d_samp_rate));
    d_meta_dict = pmt::dict_add(
        d_meta_dict, metadata_keys::pdu_num(), pmt::from_uint64(d_burst_counter));
    if (d_wall_clock_time) {
        double t_now(std::chrono::duration<double>(
                         std::chrono::system_clock::now().time_since_epoch())
                         .count());
        d_meta_dict = pmt::dict_add(
            d_meta_dict, metadata_keys::sys_time(), pmt::from_double(t_now));
    }
    if (d_vector.size() > d_tail_size)
        this->message_port_pub(msgport_names::pdus(),
                               pmt::cons(d_meta_dict, init_data(d_vector)));

    // prepare for next burst
    d_burst_counter++;
    d_triggered = false;
    d_vector.clear();
}

