def find_filenames_match(self, regex):
        """ Find the filenames that match a certain regex
        on lines that aren't comments """
        filenames = []
        reg = re.compile(regex)
        fname_re = re.compile(r'[a-zA-Z]\w+\.\w{1,5}$')
        for line in self.cfile.splitlines():
            if len(line.strip()) == 0 or line.strip()[0] == '#':
                continue
            for word in re.split('[ /)(\t\n\r\f\v]', line):
                if fname_re.match(word) and reg.search(word):
                    filenames.append(word)
        return filenames

d_oversample_rate(oversample_rate)
{
    // The over sampling rate must be rationally related to the number of channels
    // in that it must be N/i for i in [1,N], which gives an outputsample rate
    // of [fs/N, fs] where fs is the input sample rate.
    // This tests the specified input sample rate to see if it conforms to this
    // requirement within a few significant figures.
    const double srate = nfilts / oversample_rate;
    const double rsrate = round(srate);
    if (fabs(srate - rsrate) > 0.00001)
        throw std::invalid_argument(
            "pfb_channelizer: oversample rate must be N/i for i in [1, N]");

    set_relative_rate(oversample_rate);

    // Default channel map. The channel map specifies which input
    // goes to which output channel; so out[0] comes from
    // channel_map[0].
    d_channel_map.resize(d_nfilts);
    for (unsigned int i = 0; i < d_nfilts; i++) {
        d_channel_map[i] = i;
    }

    // We use a look up table to set the index of the FFT input
    // buffer, which equivalently performs the FFT shift operation
    // on every other turn when the rate_ratio>1.  Also, this
    // performs the index 'flip' where the first input goes into the
    // last filter. In the pfb_decimator_ccf, we directly index the
    // input_items buffers starting with this last; here we start
    // with the first and put it into the fft object properly for
    // the same effect.
    d_rate_ratio = (int)rintf(d_nfilts / d_oversample_rate);
    d_idxlut.resize(d_nfilts);
    for (unsigned int i = 0; i < d_nfilts; i++) {
        d_idxlut[i] = d_nfilts - ((i + d_rate_ratio) % d_nfilts) - 1;
    }

    // Calculate the number of filtering rounds to do to evenly
    // align the input vectors with the output channels
    d_output_multiple = 1;
    while ((d_output_multiple * d_rate_ratio) % d_nfilts != 0)
        d_output_multiple++;
    set_output_multiple(d_output_multiple);

    // Use set_taps to also set the history requirement
    set_taps(taps);

    // because we need a stream_to_streams block for the input,
    // only send tags from in[i] -> out[i].
    set_tag_propagation_policy(TPP_ONE_TO_ONE);
}

constellation_receiver_cb_impl::general_work(int noutput_items,
                                                 gr_vector_int& ninput_items,
                                                 gr_vector_const_void_star& input_items,
                                                 gr_vector_void_star& output_items)
{
    const auto in = reinterpret_cast<const gr_complex*>(input_items[0]);
    auto out = reinterpret_cast<std::uint8_t*>(output_items[0]);
    size_t idx = 0;

    std::vector<tag_t> tags;
    auto offset = nitems_read(0);

    get_tags_in_range(tags, 0, offset, offset + ninput_items[0]);
    if (output_items.size() == 5) {
        auto out_err = reinterpret_cast<float*>(output_items[1]);
        auto out_phase = reinterpret_cast<float*>(output_items[2]);
        auto out_freq = reinterpret_cast<float*>(output_items[3]);
        auto out_symbol = reinterpret_cast<gr_complex*>(output_items[4]);

        for (const auto& tag : tags) {
            for (; idx < tag.offset - offset; ++idx) {
                auto nco =
                    gr_expj(d_phase); // NCO value for derotating the current sample
                auto sample = in[idx] * nco; // downconverted symbol

                float phase_error;
                unsigned int sym_value =
                    d_constellation->decision_maker_pe(&sample, &phase_error);
                phase_error_tracking(phase_error); // corrects phase and frequency offsets

                out[idx] = sym_value;
                out_err[idx] = phase_error;
                out_phase[idx] = d_phase;
                out_freq[idx] = d_freq;
                out_symbol[idx] = sample;
            }
            dispatch_msg(tag.key, tag.value);
        }
        for (; idx < static_cast<unsigned int>(noutput_items); ++idx) {
            auto nco = gr_expj(d_phase); // NCO value for derotating the current sample
            auto sample = in[idx] * nco; // downconverted symbol

            float phase_error;
            unsigned int sym_value =
                d_constellation->decision_maker_pe(&sample, &phase_error);
            phase_error_tracking(phase_error); // corrects phase and frequency offsets

            out[idx] = sym_value;
            out_err[idx] = phase_error;
            out_phase[idx] = d_phase;
            out_freq[idx] = d_freq;
            out_symbol[idx] = sample;
        }
    } else {
        for (const auto& tag : tags) {
            for (; idx < tag.offset - offset; ++idx) {
                auto nco =
                    gr_expj(d_phase); // NCO value for derotating the current sample
                auto sample = in[idx] * nco; // downconverted symbol

                float phase_error;
                unsigned int sym_value =
                    d_constellation->decision_maker_pe(&sample, &phase_error);
                phase_error_tracking(phase_error); // corrects phase and frequency offsets

                out[idx] = sym_value;
            }
            dispatch_msg(tag.key, tag.value);
        }
        for (; idx < static_cast<unsigned int>(noutput_items); ++idx) {
            auto nco = gr_expj(d_phase); // NCO value for derotating the current sample
            auto sample = in[idx] * nco; // downconverted symbol

            float phase_error;
            unsigned int sym_value =
                d_constellation->decision_maker_pe(&sample, &phase_error);
            phase_error_tracking(phase_error); // corrects phase and frequency offsets
            out[idx] = sym_value;
        }
    }


    consume_each(noutput_items);
    return noutput_items;
}

