fll_band_edge_cc_impl::set_rolloff(float rolloff)
{
    if (rolloff < 0 || rolloff > 1.0) {
        throw std::out_of_range(
            "fll_band_edge_cc: invalid rolloff factor. Must be in [0,1].");
    }
    {
        /* local lock - release before calling design_filter, such that other setter calls
         * might also called before the large mutex'ed section in design_filter. */
        gr::thread::scoped_lock lock(d_setlock);
        d_rolloff = rolloff;
    }
    design_filter();
}

calc_metric(int O, int D, const std::vector<float> &TABLE, const float *input,
                 float *metric, digital::trellis_metric_type_t type)
{
  float minm = FLT_MAX;
  int minmi = 0;

  switch(type) {
  case digital::TRELLIS_EUCLIDEAN:
    for(int o=0;o<O;o++) {
      metric[o]=0.0;
      for(int m=0;m<D;m++) {
        float s=input[m]-TABLE[o*D+m];
        metric[o]+=s*s;
      }
    }
    break;
  case digital::TRELLIS_HARD_SYMBOL:
    for(int o=0;o<O;o++) {
      metric[o]=0.0;
      for(int m=0;m<D;m++) {
        float s=input[m]-TABLE[o*D+m];
        metric[o]+=s*s;
      }
      if(metric[o]<minm) {
        minm=metric[o];
        minmi=o;
      }
    }
    for(int o=0;o<O;o++) {
      metric[o] = (o==minmi?0.0:1.0);
    }
    break;
  case digital::TRELLIS_HARD_BIT:
    throw std::runtime_error("calc_metric: Invalid metric type (not yet implemented).");
    break;
  default:
    throw std::runtime_error("calc_metric: Invalid metric type.");
  }
}

