        oss << block_alias << "::" << functionbase;
        d_id = oss.str();
        // std::cerr << "REGISTERING TRIGGER: " << d_id << "  " << desc_ << std::endl;
        rpcmanager::get()->i()->registerConfigureCallback(d_id, extractor);
#endif
