write_list_tail(pmt_t obj, std::ostream& port)
{
    write(car(obj), port); // write the car
    obj = cdr(obj);        // step to cdr

    if (is_null(obj)) // ()
        port << ")";

    else if (is_pair(obj)) { // normal list
        port << " ";
        write_list_tail(obj, port);
    } else { // dotted pair
        port << " . ";
        write(obj, port);
        port << ")";
    }
}

