    d_pre_diff_code[2] = 0x3;
    d_pre_diff_code[3] = 0x2;
    d_apply_pre_diff_code = true;

    d_rotational_symmetry = 4;
    d_dimensionality = 1;
    // normalization_t norm = POWER_NORMALIZATION;
    // normalize(norm);
    calc_arity();
}

