portaudio_sink::work(int noutput_items,
                         gr_vector_const_void_star& input_items,
                         gr_vector_void_star& output_items)
{
    const float** in = (const float**)&input_items[0];
    const unsigned nchan =
        d_output_parameters.channelCount; // # of channels == samples/frame

    int k;
    for (k = 0; k < noutput_items;) {
        int nframes = d_writer->space_available() / nchan; // How much space in ringbuffer
        if (nframes == 0) {                                // no room...
            if (d_ok_to_block) {
                {
                    gr::thread::scoped_lock guard(d_ringbuffer_mutex);
                    while (!d_ringbuffer_ready)
                        d_ringbuffer_cond.wait(guard);
                }
                continue;
            } else {
                // There's no room and we're not allowed to block.
                // (A USRP is most likely controlling the pacing through the pipeline.)
                // We drop the samples on the ground, and say we processed them all ;)
                //
                // FIXME, there's probably room for a bit more finesse here.
                return noutput_items;
            }
        }

        // We can write the smaller of the request and the room we've got
        {
            gr::thread::scoped_lock guard(d_ringbuffer_mutex);

            int nf = std::min(noutput_items - k, nframes);
            float* p = (float*)d_writer->write_pointer();

            for (int i = 0; i < nf; i++) {
                for (unsigned int c = 0; c < nchan; c++) {
                    *p++ = in[c][k + i];
                }
            }

            d_writer->update_write_pointer(nf * nchan);
            k += nf;

            d_ringbuffer_ready = false;
        }
    }

    return k; // tell how many we actually did
}

interleaver::interleaver(const char* name)
{
    FILE* interleaverfile;

    if ((interleaverfile = fopen(name, "r")) == NULL)
        throw std::runtime_error("file open error in interleaver()");
    // printf("file open error in interleaver()\n");

    int k;
    if (fscanf(interleaverfile, "%d\n", &k) == EOF) {
        if (ferror(interleaverfile) != 0)
            throw std::runtime_error("interleaver::interleaver(const char *name): file "
                                     "error before vector length read");
    }

    d_interleaver_indices.resize(k);
    d_deinterleaver_indices.resize(k);

    for (int i = 0; i < k; i++) {
        if (fscanf(interleaverfile, "%d", &(d_interleaver_indices[i])) == EOF) {
            if (ferror(interleaverfile) != 0)
                throw std::runtime_error("interleaver::interleaver(const char *name): "
                                         "file error before vector read");
        }
    }

    // generate DEINTER table
    for (int i = 0; i < k; i++) {
        d_deinterleaver_indices[d_interleaver_indices[i]] = i;
    }

    fclose(interleaverfile);
}

probe_avg_mag_sqrd_cf_impl::work(int noutput_items,
                                     gr_vector_const_void_star& input_items,
                                     gr_vector_void_star& output_items)
{
    const gr_complex* in = (const gr_complex*)input_items[0];
    float* out = (float*)output_items[0];

    for (int i = 0; i < noutput_items; i++) {
        out[i] = d_iir.prev_output();
        double mag_sqrd = in[i].real() * in[i].real() + in[i].imag() * in[i].imag();
        d_iir.filter(mag_sqrd); // computed for side effect: prev_output()
    }

    d_unmuted = d_iir.prev_output() >= d_threshold;
    d_level = d_iir.prev_output();
    return noutput_items;
}

