def _scan_param_list(start_idx):
            """ Go through a parameter list and return a tuple each:
                (type, name, default_value). Python's re just doesn't cut
                it for C++ code :( """
            i = start_idx
            c = self.code_h
            if c[i] != '(':
                raise ValueError
            i += 1

            param_list = []
            read_state = 'type'
            in_string = False
            parens_count = 0  # Counts ()
            brackets_count = 0  # Counts <>
            end_of_list = False
            this_type = ''
            this_name = ''
            this_defv = ''
            WHITESPACE = ' \t\n\r\f\v'
            while not end_of_list:
                # Keep track of (), stop when reaching final closing parens
                if not in_string:
                    if c[i] == ')':
                        if parens_count == 0:
                            if read_state == 'type' and len(this_type):
                                raise ValueError(
                                    'Found closing parentheses before finishing '
                                    'last argument (this is how far I got: {})'.format
                                    (str(param_list))
                                )
                            if len(this_type):
                                param_list.append(
                                    (this_type, this_name, this_defv))
                            end_of_list = True
                            break
                        else:
                            parens_count -= 1
                    elif c[i] == '(':
                        parens_count += 1
                # Parameter type (int, const std::string, std::vector<gr_complex>, unsigned long ...)
                if read_state == 'type':
                    if c[i] == '<':
                        brackets_count += 1
                    if c[i] == '>':
                        brackets_count -= 1
                    if c[i] == '&':
                        i += 1
                        continue
                    if c[i] in WHITESPACE and brackets_count == 0:
                        while c[i] in WHITESPACE:
                            i += 1
                            continue
                        if this_type == 'const' or this_type == '':  # Ignore this
                            this_type = ''
                        elif this_type == 'unsigned':  # Continue
                            this_type += ' '
                            continue
                        else:
                            read_state = 'name'
                        continue
                    this_type += c[i]
                    i += 1
                    continue
                # Parameter name
                if read_state == 'name':
                    if c[i] == '&' or c[i] in WHITESPACE:
                        i += 1
                    elif c[i] == '=':
                        if parens_count != 0:
                            raise ValueError(
                                'While parsing argument {} ({}): name finished but no closing parentheses.'.format
                                (len(param_list) + 1, this_type + ' ' + this_name)
                            )
                        read_state = 'defv'
                        i += 1
                    elif c[i] == ',':
                        if parens_count:
                            raise ValueError(
                                'While parsing argument {} ({}): name finished but no closing parentheses.'.format
                                (len(param_list) + 1, this_type + ' ' + this_name)
                            )
                        read_state = 'defv'
                    else:
                        this_name += c[i]
                        i += 1
                    continue
                # Default value
                if read_state == 'defv':
                    if in_string:
                        if c[i] == '"' and c[i - 1] != '\\':
                            in_string = False
                        else:
                            this_defv += c[i]
                    elif c[i] == ',':
                        if parens_count:
                            raise ValueError(
                                'While parsing argument {} ({}): default value finished but no closing parentheses.'.format
                                (len(param_list) + 1, this_type + ' ' + this_name)
                            )
                        read_state = 'type'
                        param_list.append((this_type, this_name, this_defv))
                        this_type = ''
                        this_name = ''
                        this_defv = ''
                    else:
                        this_defv += c[i]
                    i += 1
                    continue
            return param_list
        # Go, go, go!
        if self.version in ('37', '38', '39', '310'):
            make_regex = r'static\s+sptr\s+make\s*'
        else:
            make_regex = r'(?<=_API)\s+\w+_sptr\s+\w+_make_\w+\s*'
        make_match = re.compile(make_regex, re.MULTILINE).search(self.code_h)
        try:
            params_list = _scan_param_list(make_match.end(0))
        except ValueError as ve:
            logger.error("Can't parse the argument list: ", ve.args[0])
            sys.exit(0)
        params = []
        for plist in params_list:
            params.append({'type': self.type_trans(plist[0], plist[2]),
                           'key': plist[1],
                           'default': plist[2],
                           'in_constructor': True})
        return params

class atsc_randomize
{
public:
    atsc_randomize();

    /*! \brief reset randomizer LFSR
     *
     * must be called during the Data Segment Sync interval prior to the
     * first data segment.  I.e., the LFSR is reset prior to the first
     * field of each VSB data frame.
     */
    void reset();

    //! randomize (whiten) mpeg packet and remove leading MPEG-2 sync byte
    void randomize(atsc_mpeg_packet_no_sync& out, const atsc_mpeg_packet& in);

    //! derandomize (de-whiten) mpeg packet and add leading MPEG-2 sync byte
    void derandomize(uint8_t* out, const uint8_t* in);

    unsigned int state() const { return d_state; }

private:
    static void initialize_output_map();
    static unsigned char slow_output_map(int st);

    static unsigned char fast_output_map(int st)
    {
        return s_output_map[(st & 0xb23c) >>
                            2]; // Magic const with 8 bits set improves cache
                                // utilization.  The bits correspond to the taps
                                // used in output calculation.  Others may be
                                // safely ignored.
    }

    //! return current output value
    unsigned char output() { return fast_output_map(d_state); }

    //! clock LFSR; advance to next state.
    void clk()
    {
        if (d_state & 0x1)
            d_state = ((d_state ^ MASK) >> 1) | 0x8000;
        else
            d_state = d_state >> 1;
    }

    //! return current output value and advance to next state
    unsigned char output_and_clk()
    {
        unsigned char r = output();
        clk();
        return r;
    }

    unsigned int d_state;

    static constexpr unsigned int PRELOAD_VALUE = 0x018f; /* 0xf180 bit reversed */
    static constexpr unsigned int MASK = 0xa638;
    static unsigned char s_output_map[1 << 14];
    static bool s_output_map_initialized_p;
}

freq_axis_build(struct freq_axis* fx, double center, double span, int n_div)
{
    /* Basic info */
    fx->center = center;
    fx->span = span;
    fx->step = span / n_div;

    /* Select mode of operation */
    if (span == 0.0) {
        fx->mode = FX_MODE_COUNT;
    } else if (center == 0.0) {
        fx->mode = FX_MODE_RELATIVE;
    } else if (floor(log10f(fx->step)) < (floor(log10f(fx->center)) - 4)) {
        fx->mode = FX_MODE_RELATIVE;
    } else {
        fx->mode = FX_MODE_ABSOLUTE;
    }

    /* Select display format for absolute frequencies */
    if (center != 0.0) {
        double min_freq, max_freq, big_freq;
        char prefix[2] = { 0, 0 };
        int exp, x, y, z;

        max_freq = fx->center + (span / 2.0);
        min_freq = fx->center - (span / 2.0);

        big_freq = (fabs(max_freq) > fabs(min_freq)) ? fabs(max_freq) : fabs(min_freq);

        _si_scaling(big_freq, 4, prefix, &exp);

        if (prefix[0] == ' ')
            prefix[0] = '\0';

        fx->abs_scale = 1.0 / powf(10.0, exp);

        x = (int)floor(log10f(big_freq)) - exp + 1;
        y = _num_decimals(fx->center * fx->abs_scale);
        z = _num_decimals(fx->step * fx->abs_scale);

        if (z > y)
            y = z;

        if (x + y > 6)
            y = 6 - x;

        sprintf(fx->abs_fmt, "%%.%dlf%s", y, prefix);
    }

    /* Select display format for relative mode */
    if (fx->mode == FX_MODE_RELATIVE) {
        double max_dev = fx->step * 5;
        char prefix[2] = { 0, 0 };
        int exp, x, y;

        _si_scaling(max_dev, 3, prefix, &exp);

        if (prefix[0] == ' ')
            prefix[0] = '\0';

        fx->rel_step = fx->step / powf(10.0, exp);

        x = (int)floor(log10f(max_dev)) - exp + 1;
        y = _num_decimals(fx->rel_step);

        if (x + y > 4)
            y = 4 - x;

        sprintf(fx->rel_fmt, "%%+.%dlf%s", y, prefix);
    }
}

