SpectrumDisplayForm::customEvent(QEvent* e)
{
    if (e->type() == QEvent::User + 3) {
        if (_systemSpecifiedFlag) {
            WindowComboBox->setCurrentIndex(_system->getWindowType());
            FFTSizeComboBox->setCurrentIndex(_system->getFFTSizeIndex());
        }

        waterfallMinimumIntensityChangedCB(WaterfallMinimumIntensitySlider->value());
        waterfallMaximumIntensityChangedCB(WaterfallMaximumIntensitySlider->value());

        // Clear any previous display
        reset();
    } else if (e->type() == SpectrumUpdateEventType) {
        SpectrumUpdateEvent* spectrumUpdateEvent = (SpectrumUpdateEvent*)e;
        newFrequencyData(spectrumUpdateEvent);
    } else if (e->type() == SpectrumWindowCaptionEventType) {
        setWindowTitle(((SpectrumWindowCaptionEvent*)e)->getLabel());
    } else if (e->type() == SpectrumWindowResetEventType) {
        reset();
        if (_systemSpecifiedFlag) {
            _system->resetPendingGUIUpdateEvents();
        }
    } else if (e->type() == SpectrumFrequencyRangeEventType) {
        _startFrequency = ((SpectrumFrequencyRangeEvent*)e)->GetStartFrequency();
        _stopFrequency = ((SpectrumFrequencyRangeEvent*)e)->GetStopFrequency();
        _centerFrequency = ((SpectrumFrequencyRangeEvent*)e)->GetCenterFrequency();

        useRFFrequenciesCB(UseRFFrequenciesCheckBox->isChecked());
    }
}

d_periodicity(periodicity)
{
    this->set_tag_propagation_policy(gr::block::TPP_DONT); // handle tags manually
    // some sanity checks
    if (offset < 0) {
        throw std::invalid_argument(
            fmt::format("offset {} needs to be non-negative.", offset));
    }
    if (periodicity <= 0) {
        throw std::invalid_argument(
            fmt::format("periodicy {} needs to be positive.", periodicity));
    }
    if (offset >= periodicity) {
        throw std::invalid_argument(fmt::format(
            "offset {} needs to be smaller than periodicity {}.", offset, periodicity));
    }
    if (static_cast<size_t>(periodicity) <= data.size()) {
        throw std::invalid_argument(
            fmt::format("periodicity {} needs to be larger than data size {}.",
                        periodicity,
                        data.size()));
    }
}

atsc_viterbi_decoder_impl::work(int noutput_items,
                                    gr_vector_const_void_star& input_items,
                                    gr_vector_void_star& output_items)
{
    auto in = static_cast<const float*>(input_items[0]);
    auto out = static_cast<unsigned char*>(output_items[0]);
    auto plin = static_cast<const plinfo*>(input_items[1]);
    auto plout = static_cast<plinfo*>(output_items[1]);

    // The way the fs_checker works ensures we start getting packets
    // starting with a field sync, and out input multiple is set to
    // 12, so we should always get a mod 12 numbered first packet
    assert(noutput_items % NCODERS == 0);

    int dbwhere;
    int dbindex;
    int shift;
    float symbols[NCODERS][enco_which_max];
    unsigned char dibits[NCODERS][enco_which_max];

    unsigned char out_copy[OUTPUT_SIZE];

    std::vector<tag_t> tags;
    for (int i = 0; i < noutput_items; i += NCODERS) {
        /* Build a continuous symbol buffer for each encoder */
        for (unsigned int encoder = 0; encoder < NCODERS; encoder++)
            for (unsigned int k = 0; k < enco_which_max; k++)
                symbols[encoder][k] =
                    in[(i + (enco_which_syms[encoder][k] / ATSC_DATA_SEGMENT_LENGTH)) *
                           ATSC_DATA_SEGMENT_LENGTH +
                       enco_which_syms[encoder][k] % ATSC_DATA_SEGMENT_LENGTH];

        /* Now run each of the 12 Viterbi decoders over their subset of
           the input symbols */
        for (unsigned int encoder = 0; encoder < NCODERS; encoder++)
            for (unsigned int k = 0; k < enco_which_max; k++)
                dibits[encoder][k] = viterbi[encoder].decode(symbols[encoder][k]);

        /* Move dibits into their location in the output buffer */
        for (unsigned int encoder = 0; encoder < NCODERS; encoder++) {
            for (unsigned int k = 0; k < enco_which_max; k++) {
                /* Store the dibit into the output data segment */
                dbwhere = enco_which_dibits[encoder][k];
                dbindex = dbwhere >> 3;
                shift = dbwhere & 0x7;
                out_copy[dbindex] = (out_copy[dbindex] & ~(0x03 << shift)) |
                                    (fifo[encoder].stuff(dibits[encoder][k]) << shift);
            } /* Symbols fed into one encoder */
        }     /* Encoders */

        // copy output from contiguous temp buffer into final output
        for (int j = 0; j < NCODERS; j++) {
            memcpy(&out[(i + j) * ATSC_MPEG_RS_ENCODED_LENGTH],
                   &out_copy[j * ATSC_MPEG_RS_ENCODED_LENGTH],
                   ATSC_MPEG_RS_ENCODED_LENGTH * sizeof(out_copy[0]));

            plout[i + j] = plinfo();
            // adjust pipeline info to reflect 12 segment delay
            plinfo::delay(plout[i + j], plin[i + j], NCODERS);
        }
    }

    return noutput_items;
}

